/* =========================================================
   ROK BETA v0.15: VIEW SIEMPRE + KASTEO VISUAL + MARCADOR RESPAWN
   ========================================================= */

.spawn-markers-layer {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
}

.spawn-marker {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 28px;
  aspect-ratio: var(--card-skin-aspect);
  filter: drop-shadow(0 0 8px var(--marker-glow)) drop-shadow(0 0 14px var(--marker-glow));
}

.spawn-marker .card {
  position: absolute;
  inset: 0;
}

.spawn-marker .card-cost,
.spawn-marker .key-label { display: none !important; }

.cell.caster-zone {
  background: rgba(255, 255, 255, .18) !important;
  cursor: pointer;
  animation: pulseCastCell 0.95s infinite alternate;
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.45), 0 0 14px rgba(255,255,255,.20);
}

.cell.caster-zone::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url('assets/kast-cell-icon.jpg');
  background-position: center;
  background-repeat: no-repeat;
  background-size: 100% 100%;
  opacity: .92;
  filter: drop-shadow(0 0 6px rgba(255,255,255,.55));
  pointer-events: none;
}

.cell.caster-zone:hover {
  background: rgba(255,255,255,.38) !important;
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.88), 0 0 16px rgba(255,255,255,.55);
}

.cell.selected-place {
  background: rgba(255, 255, 255, .55) !important;
  outline: 2px solid #fff;
}

@keyframes pulseCastCell {
  from { box-shadow: inset 0 0 0 1px rgba(255,255,255,.35), 0 0 8px rgba(255,255,255,.18); }
  to { box-shadow: inset 0 0 0 4px rgba(255,255,255,.90), 0 0 18px rgba(255,255,255,.55); }
}

.card-info-btn:disabled {
  opacity: .4;
  cursor: not-allowed;
  filter: grayscale(0.25);
  box-shadow: none !important;
}

.cast-item {
  position: relative;
  overflow: visible !important;
}

.cast-item img {
  filter: drop-shadow(0 0 10px rgba(255,255,255,.65)) drop-shadow(0 10px 8px rgba(0,0,0,.65)) !important;
}

.cast-item.entering {
  animation: castDropIn .42s ease-out;
}

.cast-status {
  position: absolute;
  right: -8px;
  bottom: 0px;
  display: flex;
  gap: 5px;
  align-items: center;
}

.cast-icon-badge,
.cast-number-badge {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #12071e;
  border: 2px solid var(--p1);
  color: white;
  font: bold 13px Arial;
  box-shadow: 0 0 10px rgba(255,255,255,.32);
}

.cast-icon-badge {
  transform: translateY(-8px);
}

@keyframes castDropIn {
  0% { transform: translateY(-34px) scale(.78); opacity: 0; filter: blur(3px); }
  60% { transform: translateY(6px) scale(1.04); opacity: 1; filter: blur(0); }
  100% { transform: translateY(0) scale(1); opacity: 1; }
}


/* =========================================================
   ROK BETA v0.17: BADGES SUPERPUESTOS + LINK VISUAL RESPAWN/FICHA
   ========================================================= */

.spawn-marker {
  pointer-events: auto;
  overflow: visible;
}

.spawn-status {
  position: absolute;
  right: -8px;
  bottom: -4px;
  z-index: 3;
}

.cast-status {
  position: absolute;
  right: -8px;
  bottom: -4px;
  display: block;
}

.cast-icon-badge.big {
  position: relative;
  width: 34px;
  height: 34px;
  font-size: 22px;
  line-height: 1;
  display: grid;
  place-items: center;
}

.cast-corner-number {
  position: absolute;
  right: -3px;
  bottom: -3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #ffffff;
  color: #12071e;
  border: 1px solid #12071e;
  font: bold 10px Arial;
  box-shadow: 0 0 8px rgba(255,255,255,.65);
}

.cast-number-badge { display: none !important; }

.cast-item.entering {
  animation: castDropFromTop .58s ease-out;
}

@keyframes castDropFromTop {
  0% { transform: translateY(-88px) scale(.72); opacity: 0; filter: blur(4px); }
  62% { transform: translateY(0) scale(1.04); opacity: 1; filter: blur(0); }
  78% { transform: translateY(0) scale(.98); opacity: 1; }
  100% { transform: translateY(0) scale(1); opacity: 1; box-shadow: 0 0 0 rgba(255,255,255,0); }
}

.cast-item.entering img {
  animation: castLandingPulse .55s .38s ease-out 1;
}

@keyframes castLandingPulse {
  0% { filter: drop-shadow(0 0 3px rgba(255,255,255,.3)) drop-shadow(0 10px 8px rgba(0,0,0,.65)); }
  50% { filter: drop-shadow(0 0 16px rgba(255,255,255,.95)) drop-shadow(0 10px 8px rgba(0,0,0,.65)); }
  100% { filter: drop-shadow(0 0 10px rgba(255,255,255,.65)) drop-shadow(0 10px 8px rgba(0,0,0,.65)); }
}

.pulse-linked {
  animation: linkedPulse 0.9s infinite alternate;
}

@keyframes linkedPulse {
  from { transform: translate(-50%, -50%) scale(1); filter: drop-shadow(0 0 6px rgba(255,255,255,.35)) drop-shadow(0 0 12px rgba(255,255,255,.15)); }
  to { transform: translate(-50%, -50%) scale(1.12); filter: drop-shadow(0 0 16px rgba(255,255,255,.95)) drop-shadow(0 0 22px rgba(255,255,255,.75)); }
}

.spawn-marker.pulse-linked .card,
.spawn-marker.hover-linked .card {
  outline: 2px solid rgba(255,255,255,.85);
  box-shadow: 0 0 16px rgba(255,255,255,.85);
}

.unit.invocation.hover-linked > .unit-token-img {
  filter: brightness(1.25) saturate(0) contrast(1.05) drop-shadow(0 0 12px rgba(255,255,255,.95));
}

.spawn-marker.hover-linked {
  filter: drop-shadow(0 0 10px #fff) drop-shadow(0 0 18px #fff);
}


