/* Permite que el HUD flote fuera del rectángulo visual de la arena si hace falta. */
.board-panel,
.board {
  overflow: visible !important;
}

/* HUD flotante: ya no usa right/top/bottom de la columna anterior. */
.combat-hud {
  position: absolute !important;
  left: var(--combat-hud-float-left) !important;
  top: var(--combat-hud-float-top) !important;
  right: auto !important;
  bottom: auto !important;
  width: var(--combat-hud-float-width) !important;
  max-height: var(--combat-hud-float-max-height) !important;
