/* =========================================================
   ROK v5.3.0 · RITMO Y ANIMACIÓN DE COMBATE
   ========================================================= */
:root {
  --combat-text-duration: 1.85s;
  --combat-clash-duration: .92s;
}

/* Textos flotantes más lentos y legibles. */
.floating-damage {
  animation: damageFloatUpSlow var(--combat-text-duration) cubic-bezier(.16,.84,.22,1) forwards !important;
}

.floating-combat {
  animation: combatFloatUpSlow var(--combat-text-duration) cubic-bezier(.16,.84,.22,1) forwards !important;
}

@keyframes damageFloatUpSlow {
  0% { opacity: 0; transform: translate(-50%, -28%) scale(.72); }
  12% { opacity: 1; transform: translate(-50%, -48%) scale(1.08); }
  62% { opacity: 1; transform: translate(-50%, -78%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -124%) scale(.94); }
}

@keyframes combatFloatUpSlow {
  0% { opacity: 0; transform: translate(-50%, -25%) scale(.75); }
  14% { opacity: 1; transform: translate(-50%, -52%) scale(1.05); }
  68% { opacity: 1; transform: translate(-50%, -76%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -118%) scale(.96); }
}

/* Choque visual: las dos invocaciones se lanzan hacia el centro,
   vibran brevemente y vuelven. */
.unit.invocation.clash-lunge {
  animation: unitClashLunge var(--combat-clash-duration) cubic-bezier(.16,.9,.28,1) both !important;
  z-index: 420 !important;
  filter:
    drop-shadow(0 18px 10px rgba(0,0,0,.55))
    drop-shadow(0 0 10px rgba(255,245,190,.75))
    drop-shadow(0 0 18px rgba(255,95,55,.48)) !important;
}

@keyframes unitClashLunge {
  0% {
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1);
  }
  28% {
    transform: translate(calc(-50% + var(--invocation-offset-x) + var(--clash-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--clash-y, 0px))) scale(1.08);
  }
  38% {
    transform: translate(calc(-50% + var(--invocation-offset-x) + (var(--clash-x, 0px) * .55)), calc(-80% + var(--invocation-offset-y) + (var(--clash-y, 0px) * .55))) scale(1.03) rotate(-2deg);
  }
  48% {
    transform: translate(calc(-50% + var(--invocation-offset-x) + (var(--clash-x, 0px) * .72)), calc(-80% + var(--invocation-offset-y) + (var(--clash-y, 0px) * .72))) scale(1.05) rotate(2deg);
  }
  72% {
    transform: translate(calc(-50% + var(--invocation-offset-x) + (var(--clash-x, 0px) * .18)), calc(-80% + var(--invocation-offset-y) + (var(--clash-y, 0px) * .18))) scale(1.02);
  }
  100% {
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1);
  }
}


/* =========================================================
   ROK v5.3.1 · ATAQUE TIPO EMBESTIDA / SIN COMBATE VS ESTRUCTURA
   ========================================================= */
:root {
  --combat-attack-lunge-duration: 1.12s;
}

/* La animación nueva es unilateral: el atacante crece, avanza hacia el objetivo,
   vuelve a tamaño normal al llegar y regresa a su casilla. */
.unit.invocation.attack-lunge {
  animation: unitAttackLunge var(--combat-attack-lunge-duration) cubic-bezier(.16,.92,.24,1) both !important;
  z-index: 430 !important;
  filter:
    drop-shadow(0 18px 10px rgba(0,0,0,.55))
    drop-shadow(0 0 10px rgba(255,245,190,.72))
    drop-shadow(0 0 18px rgba(255,95,55,.46)) !important;
}

@keyframes unitAttackLunge {
  0% {
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1);
  }
  18% {
    transform: translate(calc(-50% + var(--invocation-offset-x) + (var(--attack-x, 0px) * .18)), calc(-80% + var(--invocation-offset-y) + (var(--attack-y, 0px) * .18))) scale(1.10);
  }
  52% {
    transform: translate(calc(-50% + var(--invocation-offset-x) + var(--attack-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--attack-y, 0px))) scale(1);
  }
  68% {
    transform: translate(calc(-50% + var(--invocation-offset-x) + (var(--attack-x, 0px) * .82)), calc(-80% + var(--invocation-offset-y) + (var(--attack-y, 0px) * .82))) scale(1.02) rotate(-1deg);
  }
  100% {
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1);
  }
}

/* Si queda alguna clase vieja por timing, no debe imponerse sobre el ataque nuevo. */
.unit.invocation.clash-lunge:not(.attack-lunge) {
  animation-duration: .01s !important;
}


