/* Optimización: animar transform es barato; filtros pesados durante lunge pueden laggear. */
.unit.invocation {
  will-change: transform;
  backface-visibility: hidden;
}

.unit.invocation.attack-lunge {
  will-change: transform !important;
  animation: unitAttackLungeLite var(--combat-attack-lunge-duration, 1.05s) cubic-bezier(.16,.92,.24,1) both !important;
  z-index: 430 !important;
  filter: drop-shadow(0 18px 10px rgba(0,0,0,.55)) !important;
}

@keyframes unitAttackLungeLite {
  0% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y)), 0) scale(1);
  }
  18% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + (var(--attack-x, 0px) * .18)), calc(-80% + var(--invocation-offset-y) + (var(--attack-y, 0px) * .18)), 0) scale(1.08);
  }
  52% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--attack-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--attack-y, 0px)), 0) scale(1);
  }
  100% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y)), 0) scale(1);
  }
}

/* ROK v299 · Oscilación no usa la embestida frontal. La ficha describe un
   arco corto dentro de su propia casilla mientras la cadena conserva su ancla. */
.unit.invocation.oscillation-attack-orbit {
  animation: unitOscillationAttackOrbit .98s cubic-bezier(.2,.78,.22,1) both !important;
  z-index: 430 !important;
  filter: drop-shadow(0 18px 10px rgba(0,0,0,.55)) !important;
  will-change: transform !important;
}

@keyframes unitOscillationAttackOrbit {
  0% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y)), 0) scale(1) rotate(0deg);
  }
  18% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--oscillation-orbit-a-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--oscillation-orbit-a-y, 0px)), 0) scale(1.06) rotate(-1.2deg);
  }
  42% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--oscillation-orbit-b-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--oscillation-orbit-b-y, 0px)), 0) scale(1.045) rotate(1.6deg);
  }
  66% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--oscillation-orbit-c-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--oscillation-orbit-c-y, 0px)), 0) scale(1.025) rotate(-1.4deg);
  }
  84% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--oscillation-orbit-d-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--oscillation-orbit-d-y, 0px)), 0) scale(1.01) rotate(.7deg);
  }
  100% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y)), 0) scale(1) rotate(0deg);
  }
}


