.structure-destroy-fx {
  position: absolute;
  width: 86px;
  height: 86px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 119;
  border-radius: 50%;
  --destroy-color: #5400FF;
  animation: structureDestroyBurst 1.15s ease-out forwards;
}
.structure-destroy-fx::before {
  content: '';
  position: absolute;
  inset: 18px;
  border-radius: 50%;
  border: 2px solid var(--destroy-color);
  box-shadow: 0 0 22px var(--destroy-color), inset 0 0 18px var(--destroy-color);
}
.structure-destroy-fx span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 10px;
  height: 18px;
  border-radius: 999px;
  background: linear-gradient(180deg, #fff, var(--destroy-color));
  box-shadow: 0 0 14px var(--destroy-color);
  transform-origin: center;
  opacity: .95;
}
.structure-destroy-fx span:nth-child(1) { transform: translate(-50%, -50%) rotate(0deg) translateY(-34px); }
.structure-destroy-fx span:nth-child(2) { transform: translate(-50%, -50%) rotate(60deg) translateY(-34px); }
.structure-destroy-fx span:nth-child(3) { transform: translate(-50%, -50%) rotate(120deg) translateY(-34px); }
.structure-destroy-fx span:nth-child(4) { transform: translate(-50%, -50%) rotate(180deg) translateY(-34px); }
.structure-destroy-fx span:nth-child(5) { transform: translate(-50%, -50%) rotate(240deg) translateY(-34px); }
.structure-destroy-fx span:nth-child(6) { transform: translate(-50%, -50%) rotate(300deg) translateY(-34px); }
@keyframes structureDestroyBurst {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.48) rotate(0deg); filter: blur(1px); }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1.05) rotate(8deg); filter: blur(0); }
  64% { opacity: .85; transform: translate(-50%, -50%) scale(1.28) rotate(18deg); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.72) rotate(34deg); filter: blur(2px); }
}
.critical-slash-fx {
  position: absolute;
  width: 66px;
  height: 66px;
  z-index: 122;
  transform: translate(-50%, -50%) rotate(-20deg) scale(.75);
  pointer-events: none;
  opacity: 0;
  animation: criticalSlash 740ms cubic-bezier(.2,.86,.18,1) forwards;
}
.critical-slash-fx::before,
.critical-slash-fx::after {
  content: '';
  position: absolute;
  left: 7px;
  right: 7px;
  top: 30px;
  height: 5px;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, #fff 17%, #ffd84a 52%, #FF0000 78%, transparent);
  box-shadow: 0 0 16px rgba(255,216,74,.8), 0 0 28px rgba(255,90,31,.45);
