@keyframes criticalSlash {
  0% { opacity: 0; transform: translate(-50%, -50%) rotate(-20deg) scale(.55); filter: blur(2px); }
  22% { opacity: 1; transform: translate(-50%, -50%) rotate(-20deg) scale(1.08); filter: blur(0); }
  100% { opacity: 0; transform: translate(-50%, -50%) rotate(-20deg) scale(1.22); filter: blur(1px); }
}
.combat-side.critical-slash-flash .combat-mini-card::after {
