@keyframes structureUnitBreakGlow {
  0% {
    opacity: 1;
    transform: scale(1);
    filter: brightness(1) saturate(1.1) drop-shadow(0 0 4px var(--destroy-color, #5400FF));
  }
  28% {
    opacity: 1;
    transform: scale(1.018);
    filter: brightness(1.35) saturate(1.85) drop-shadow(0 0 16px var(--destroy-color, #5400FF)) drop-shadow(0 0 28px var(--destroy-color, #5400FF));
  }
  58% {
    opacity: .95;
    transform: scale(1.03);
    filter: brightness(1.65) saturate(2.15) drop-shadow(0 0 22px var(--destroy-color, #5400FF)) drop-shadow(0 0 42px var(--destroy-color, #5400FF));
  }
  100% {
    opacity: 0;
    transform: scale(.72);
    filter: brightness(2.1) saturate(2.4) drop-shadow(0 0 34px var(--destroy-color, #5400FF)) blur(1px);
  }
}
@keyframes structureUnitBreakShake {
  0%, 100% { transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y))) translate(0,0) rotate(0deg); }
  12% { transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y))) translate(-1px, 1px) rotate(-.8deg); }
  22% { transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y))) translate(2px, -1px) rotate(.7deg); }
  32% { transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y))) translate(-2px, -2px) rotate(-.5deg); }
  46% { transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y))) translate(2px, 2px) rotate(.9deg); }
  62% { transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y))) translate(-1px, 2px) rotate(-.6deg); }
  78% { transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y))) translate(1px, -2px) rotate(.4deg); }
}
.structure-destroy-fx {
  width: 112px !important;
  height: 112px !important;
  z-index: 290 !important;
  animation: structureDestroyBurst 1.18s cubic-bezier(.15,.86,.22,1) forwards !important;
}
.structure-destroy-fx::after {
  content: '';
  position: absolute;
  inset: 23px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff 0 8%, color-mix(in srgb, var(--destroy-color, #5400FF) 74%, transparent 26%) 9% 38%, transparent 68%);
  box-shadow: 0 0 30px var(--destroy-color, #5400FF), 0 0 55px color-mix(in srgb, var(--destroy-color, #5400FF) 42%, transparent 58%);
  animation: structureDestroyCore 1.05s ease-out forwards;
}
.structure-destroy-fx i {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 18px var(--destroy-color, #5400FF);
