}
.structure-destroy-fx i:nth-of-type(1) { transform: translate(-50%, -50%) translate(-24px, -18px); }
.structure-destroy-fx i:nth-of-type(2) { transform: translate(-50%, -50%) translate(24px, -6px); }
.structure-destroy-fx i:nth-of-type(3) { transform: translate(-50%, -50%) translate(6px, 24px); }
@keyframes structureDestroyCore {
  0% { opacity: 0; transform: scale(.18); filter: blur(3px); }
  18% { opacity: 1; transform: scale(.72); filter: blur(0); }
  58% { opacity: .9; transform: scale(1.28); }
