/* =========================================================
   OSCILACIÓN PARCIAL · capa protegida de barrido ofensivo
   ========================================================= */
.oscillation-sweep-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 12020 !important;
}

.oscillation-sweep-cell {
  position: absolute;
  width: 5%;
  height: 3.4%;
  transform: translate(-50%, -50%) scale(.72);
  border-radius: 10px;
  opacity: 0;
  background: transparent;
  animation: oscillationPartialSweepCell var(--oscillation-step-duration, 620ms) linear var(--oscillation-delay, 0ms) both;
}

.oscillation-inner-cell {
  background: rgba(139, 71, 255, .34);
  box-shadow:
    inset 0 0 10px rgba(139, 71, 255, .34),
    0 0 calc(18px * .42) rgba(139, 71, 255, .42);
}

.oscillation-impact-cell {
  background: rgba(139, 71, 255, calc(.74 * .38));
  box-shadow:
    inset 0 0 8px rgba(255,255,255,.18),
    0 0 18px rgba(139, 71, 255, .72);
}

.oscillation-impact-icon {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 15px;
  height: 15px;
  transform: translate(-50%, -50%) rotate(45deg);
  border-radius: 3px;
  background:
    radial-gradient(circle at 50% 50%,
      rgba(255,255,255,.96) 0 18%,
      rgba(139, 71, 255, .96) 20% 58%,
      rgba(139, 71, 255, .16) 60% 100%);
  box-shadow:
    0 0 calc(18px * .72) rgba(139, 71, 255, .92),
    0 0 4px rgba(255,255,255,.55);
  animation: oscillationImpactLead var(--oscillation-step-duration, 620ms) linear var(--oscillation-delay, 0ms) both;
}

.oscillation-sweep-stop-cell {
  animation: none !important;
  opacity: .82 !important;
  transform: translate(-50%, -50%) scale(1.02) !important;
  filter: none !important;
  box-shadow:
    inset 0 0 10px rgba(255,255,255,.24),
    0 0 20px rgba(139, 71, 255, .88) !important;
}

.oscillation-sweep-stop-cell .oscillation-impact-icon {
  animation: none !important;
  opacity: 1 !important;
  transform: translate(-50%, -50%) rotate(45deg) scale(1.04) !important;
}

.oscillation-impact-icon::before,
.oscillation-impact-icon::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 160%;
  height: 2px;
  background: rgba(255,255,255,.72);
  transform: translate(-50%, -50%) rotate(45deg);
  box-shadow: 0 0 6px rgba(139, 71, 255, .86);
}

.oscillation-impact-icon::after {
  transform: translate(-50%, -50%) rotate(-45deg);
}

.oscillation-hit-label {
  color: #fff;
  text-shadow: 0 0 8px rgba(139, 71, 255, .95);
}

@keyframes oscillationPartialSweepCell {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.72); filter: blur(.5px); }
  12% { opacity: .74; transform: translate(-50%, -50%) scale(1.02); filter: blur(0); }
  40% { opacity: calc(.74 * .72); transform: translate(-50%, -50%) scale(1.00); }
  70% { opacity: calc(.74 * .34); transform: translate(-50%, -50%) scale(.98); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(.94); filter: blur(.8px); }
}

@keyframes oscillationImpactLead {
  0% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(.68); }
  10% { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(1.02); }
  32% { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(1); }
  48% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(.92); }
  100% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(.88); }
}

/* =========================================================
   ROK v290 · OSCILACIÓN PARCIAL · CADENAS INDIVIDUALES
   Sutoka / Junkai / Kurokagi
   ========================================================= */
.oscillation-character-chain-layer {
  --oscillation-chain-light: rgba(233, 219, 247, .96);
  --oscillation-chain-mid: rgba(145, 87, 183, .94);
  --oscillation-chain-dark: rgba(18, 11, 23, .98);
  --oscillation-chain-glow: rgba(147, 71, 201, .82);
  --oscillation-chain-impact: rgba(203, 145, 238, .96);
}

.oscillation-character-chain-step {
  overflow: visible;
  border-radius: 0;
  background: transparent !important;
  box-shadow: none !important;
  filter: none !important;
}

.oscillation-character-chain-runner {
  animation: none !important;
  transform: translateY(-50%);
  transform-origin: 0 50%;
  transition: none !important;
  will-change: width, transform, opacity;
}

.oscillation-character-chain {
  position: absolute;
  left: 0;
  top: 50%;
  width: 100%;
  height: 26px;
  opacity: 1;
  transform: translateY(-50%);
