    width: var(--rok-main-menu-btn-w);
  }
}

/* =========================================================
   ROK v5.3.213ZX · BIBLIOTECA + SPELLBOOK BUILDER V1
   ========================================================= */
:root {
  --library-builder-z: 4100;
  --library-builder-hud-h: 92px;
  --library-builder-side-w: minmax(320px, 1.05fr);
  --library-builder-actions-w: clamp(150px, 14cqw, 210px);
  --library-builder-gap: clamp(10px, 1.1cqw, 18px);
  --library-builder-panel-radius: 18px;
}

body.rok-library-mode {
  overflow: hidden;
  background: #05050b;
}

body.rok-library-mode .game-shell,
body.rok-library-mode .selected-unit-command-panel,
body.rok-library-mode .persistent-unit-command-stack,
body.rok-library-mode #mainMenuScreen {
  visibility: hidden !important;
  pointer-events: none !important;
}

body.rok-library-mode .transition-overlay {
  display: none !important;
}

.library-builder-screen {
  position: fixed;
  inset: 0;
  z-index: var(--library-builder-z);
  display: none;
  overflow: hidden;
  color: #f6edf9;
  background: #05050b;
}

body.rok-library-mode .library-builder-screen,
.library-builder-screen[aria-hidden="false"] {
  display: block;
}

.library-builder-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(4, 5, 12, .76), rgba(9, 6, 16, .52) 46%, rgba(5, 3, 10, .82)),
    radial-gradient(circle at 50% 24%, rgba(142, 82, 255, .18), transparent 40%),
    url('assets/menu/main-menu-bg.webp') center center / cover no-repeat;
  filter: saturate(.9) brightness(.72);
  transform: scale(1.012);
}

.library-builder-shell {
  position: relative;
  z-index: 2;
  height: 100%;
  display: grid;
  grid-template-rows: var(--library-builder-hud-h) minmax(0, 1fr);
  gap: var(--library-builder-gap);
  padding: clamp(12px, 1.6cqw, 24px);
  box-sizing: border-box;
}

.library-builder-hud {
  display: grid;
  grid-template-columns: minmax(320px, 1fr) minmax(320px, .95fr);
  gap: var(--library-builder-gap);
  min-height: 0;
}

.library-builder-hud-block,
.library-builder-panel,
.library-builder-actions {
  border: 1px solid rgba(221, 196, 136, .28);
  background:
    linear-gradient(180deg, rgba(18, 14, 28, .84), rgba(6, 5, 12, .78));
  box-shadow:
    0 14px 34px rgba(0,0,0,.42),
    inset 0 0 22px rgba(255,255,255,.045),
    inset 0 0 0 1px rgba(255,255,255,.035);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.library-builder-hud-block {
  border-radius: 16px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}

.library-builder-summary-hud {
  text-align: right;
}

.library-builder-kicker,
.library-builder-panel-head span {
  display: block;
  color: #caa8ff;
  font: 700 11px/1.2 system-ui, sans-serif;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.library-builder-hud-block strong,
.library-builder-panel-head strong {
  display: block;
  color: #ffeec2;
  font: 800 clamp(17px, 1.45cqw, 24px)/1.1 Georgia, serif;
  text-shadow: 0 2px 12px rgba(0,0,0,.75);
}

.library-builder-hud-block small {
  color: rgba(244, 235, 255, .72);
  font: 600 clamp(11px, .9cqw, 14px)/1.25 system-ui, sans-serif;
  margin-top: 5px;
}

.library-builder-layout {
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(360px, 1.05fr) var(--library-builder-actions-w) minmax(360px, 1fr);
  gap: var(--library-builder-gap);
}

.library-builder-panel {
  min-height: 0;
  border-radius: var(--library-builder-panel-radius);
  padding: 12px;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  overflow: hidden;
}

.library-builder-library-panel {
  border-color: rgba(0, 245, 255, .24);
  background:
    linear-gradient(180deg, rgba(6, 30, 45, .82), rgba(5, 7, 16, .82));
  grid-template-rows: auto auto minmax(0, 1fr);
}

.library-builder-spellbook-panel {
  border-color: rgba(255, 184, 92, .24);
  background:
    linear-gradient(180deg, rgba(55, 12, 10, .70), rgba(12, 5, 8, .84));
}

.library-builder-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 2px 10px;
}

.library-builder-page-chip {
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 999px;
  padding: 6px 10px;
  background: rgba(0,0,0,.36);
  color: #f6edf9;
  font: 800 12px/1 system-ui, sans-serif;
}

.library-builder-card-grid {
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  display: grid;
  gap: 8px;
  padding: 4px 4px 10px;
  scrollbar-width: thin;
  scrollbar-color: rgba(217, 193, 255, .45) rgba(0,0,0,.22);
}

.library-builder-library-grid {
  grid-template-columns: repeat(auto-fill, minmax(92px, 1fr));
  align-content: start;
  row-gap: var(--biblioteca-cartas-separacion-vertical) !important;
  column-gap: var(--biblioteca-cartas-separacion-horizontal) !important;
  gap: var(--biblioteca-cartas-separacion-vertical) var(--biblioteca-cartas-separacion-horizontal) !important;
}

.library-builder-spellbook-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(4, auto);
  align-content: start;
  overflow: hidden;
}

.library-builder-card-tile {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  aspect-ratio: var(--card-skin-aspect);
  padding: 0;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(10,10,16,.82), rgba(2,2,5,.92));
  box-shadow: inset 0 0 18px rgba(0,0,0,.72), 0 6px 16px rgba(0,0,0,.34);
  cursor: pointer;
  overflow: hidden;
  transition: transform .14s ease, border-color .14s ease, box-shadow .14s ease;
}

.library-builder-card-tile:hover,
.library-builder-card-tile:focus-visible {
  transform: translateY(-2px);
  border-color: rgba(255,238,194,.58);
  box-shadow: inset 0 0 18px rgba(0,0,0,.62), 0 8px 18px rgba(0,0,0,.45), 0 0 14px rgba(194, 116, 255, .22);
}

.library-builder-card-tile.selected {
  border-color: #fff2b2;
  box-shadow: inset 0 0 18px rgba(0,0,0,.52), 0 0 0 2px rgba(255, 224, 116, .28), 0 0 22px rgba(255, 206, 98, .25);
}

.library-builder-card-tile.empty {
  cursor: default;
  border-style: dashed;
  border-color: rgba(255,255,255,.12);
  background: linear-gradient(180deg, rgba(255,255,255,.035), rgba(0,0,0,.22));
}

.library-builder-empty-mark {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: rgba(255,255,255,.09);
  font-size: 34px;
}

.library-builder-card-tile .card {
  position: absolute !important;
  left: 6px !important;
  right: 6px !important;
  top: 6px !important;
  bottom: 6px !important;
  inset: 6px !important;
  aspect-ratio: var(--card-skin-aspect) !important;
  border-radius: 6px;
}

.library-builder-card-tile .card-layer {
  pointer-events: none !important;
}

.library-builder-actions {
  border-radius: 16px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  overflow: auto;
}

.library-builder-action,
.library-builder-mini-btn {
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(35, 27, 51, .95), rgba(9, 8, 15, .94));
  color: #f9f0ff;
  font: 900 12px/1.15 system-ui, sans-serif;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 10px 10px;
  cursor: pointer;
  box-shadow: inset 0 0 12px rgba(255,255,255,.045), 0 5px 12px rgba(0,0,0,.28);
}

.library-builder-action:hover,
.library-builder-mini-btn:hover,
.library-builder-action:focus-visible,
.library-builder-mini-btn:focus-visible {
  border-color: rgba(255, 229, 154, .55);
  transform: translateY(-1px);
}

.library-builder-action.primary {
  background: linear-gradient(180deg, rgba(82, 43, 139, .98), rgba(22, 11, 42, .98));
  border-color: rgba(204, 152, 255, .48);
}

.library-builder-action.danger {
  background: linear-gradient(180deg, rgba(97, 27, 31, .96), rgba(25, 8, 12, .98));
  border-color: rgba(255, 132, 132, .38);
}

.library-builder-action.back {
  margin-top: auto;
  background: linear-gradient(180deg, rgba(25, 41, 56, .96), rgba(8, 12, 18, .98));
}

.library-builder-action.planned,
.library-builder-mini-btn.planned {
  opacity: .72;
}

.library-builder-notice {
  min-height: 44px;
  padding: 8px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(0,0,0,.24);
  color: rgba(245, 237, 255, .85);
  font: 700 11px/1.25 system-ui, sans-serif;
}

.library-builder-notice:empty::before {
  content: 'Selecciona cartas para construir el Spellbook.';
  color: rgba(245, 237, 255, .46);
}

.library-builder-notice.pulse {
  animation: libraryBuilderNoticePulse .55s ease both;
}

@keyframes libraryBuilderNoticePulse {
  0% { opacity: .42; transform: scale(.985); }
  55% { opacity: 1; transform: scale(1.015); }
  100% { opacity: 1; transform: scale(1); }
}

.library-builder-page-row {
  display: flex;
  gap: 8px;
  justify-content: space-between;
  padding: 8px 2px 0;
}

.library-builder-page-row .library-builder-mini-btn {
  flex: 1;
  padding: 8px;
  font-size: 11px;
}

@container rok-app-stage  (max-width: 1050px) {
  :root {
    --library-builder-hud-h: 118px;
    --library-builder-actions-w: 145px;
  }
  .library-builder-layout {
    grid-template-columns: minmax(260px, 1fr) var(--library-builder-actions-w) minmax(260px, 1fr);
  }
  .library-builder-library-grid {
    grid-template-columns: repeat(auto-fill, minmax(78px, 1fr));
  }
}


/* =========================================================
   ROK v5.3.213ZY · SPELLBOOK GRID FIT 12 SLOTS
   ========================================================= */
:root {
  --library-builder-spellbook-gap: 6px;
  --library-builder-spellbook-card-inset: 4px;
}

.library-builder-spellbook-panel {
  min-height: 0;
}

.library-builder-spellbook-grid {
  height: 100%;
  min-height: 0;
  gap: var(--library-builder-spellbook-gap) !important;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(4, minmax(0, 1fr));
  align-content: stretch;
  align-items: stretch;
}

.library-builder-spellbook-grid .library-builder-card-tile {
  min-height: 0;
  height: 100%;
  aspect-ratio: auto;
}

.library-builder-spellbook-grid .library-builder-card-tile .card {
  left: var(--library-builder-spellbook-card-inset) !important;
  right: var(--library-builder-spellbook-card-inset) !important;
  top: var(--library-builder-spellbook-card-inset) !important;
  bottom: var(--library-builder-spellbook-card-inset) !important;
  inset: var(--library-builder-spellbook-card-inset) !important;
}


/* =========================================================
   ROK v5.3.213ZZ · SPELLBOOK SLOTS SQUARE 1:1
   ========================================================= */
:root {
  --library-builder-spellbook-gap: 6px;
  --library-builder-spellbook-card-inset: 4px;
}

.library-builder-spellbook-grid {
  height: auto !important;
  min-height: 0;
  gap: var(--library-builder-spellbook-gap) !important;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: none !important;
  grid-auto-rows: auto;
  align-content: start;
  align-items: start;
  overflow: auto;
}

.library-builder-spellbook-grid .library-builder-card-tile {
  min-height: 0;
  height: auto !important;
  aspect-ratio: 1 / 1 !important;
}

.library-builder-spellbook-grid .library-builder-card-tile .card {
  left: var(--library-builder-spellbook-card-inset) !important;
  right: var(--library-builder-spellbook-card-inset) !important;
  top: var(--library-builder-spellbook-card-inset) !important;
  bottom: var(--library-builder-spellbook-card-inset) !important;
  inset: var(--library-builder-spellbook-card-inset) !important;
}


/* =========================================================
   ROK v5.3.213ZZA · SPELLBOOK 12 SLOTS FIT INSIDE PANEL
   ========================================================= */
/* Mantiene las casillas cuadradas, pero reduce su tamaño real
   para que las 12 entren dentro del contenedor sin desbordar. */

:root {
  --library-builder-spellbook-slot-size: min(24.5cqw, 24.5cqh, 178px);
  --library-builder-spellbook-gap: 7px;
}

.library-builder-spellbook-grid {
  width: max-content !important;
  max-width: 100% !important;
  height: max-content !important;
  max-height: 100% !important;
  margin: 0 auto !important;
  padding: 2px 2px 8px !important;
  overflow: hidden !important;
  display: grid !important;
  grid-template-columns: repeat(3, var(--library-builder-spellbook-slot-size)) !important;
  grid-template-rows: repeat(4, var(--library-builder-spellbook-slot-size)) !important;
  grid-auto-rows: var(--library-builder-spellbook-slot-size) !important;
  justify-content: center !important;
  align-content: start !important;
  justify-items: stretch !important;
  align-items: stretch !important;
  gap: var(--library-builder-spellbook-gap) !important;
}

.library-builder-spellbook-grid .library-builder-card-tile {
  width: var(--library-builder-spellbook-slot-size) !important;
  height: var(--library-builder-spellbook-slot-size) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: var(--library-builder-spellbook-slot-size) !important;
  max-height: var(--library-builder-spellbook-slot-size) !important;
  aspect-ratio: 1 / 1 !important;
}

/* En pantallas más bajas, baja otro poco para que no se coma los botones de página. */
@container rok-app-stage  (max-height: 820px) {
  :root {
    --library-builder-spellbook-slot-size: min(23cqw, 20.8cqh, 156px);
    --library-builder-spellbook-gap: 6px;
  }
}

@container rok-app-stage  (max-height: 700px) {
  :root {
    --library-builder-spellbook-slot-size: min(22cqw, 19.2cqh, 138px);
    --library-builder-spellbook-gap: 5px;
  }
}


/* =========================================================
   ROK v5.3.213ZZB · SPELLBOOK MOUSE-WHEEL SCROLL, HIDDEN BAR
   ========================================================= */
/* Mantiene la grilla cuadrada, pero permite desplazar verticalmente
   con la ruedita del mouse sin mostrar barra lateral. */

.library-builder-spellbook-grid {
  overflow-y: auto !important;
  overflow-x: hidden !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  padding-right: 0 !important;
}

.library-builder-spellbook-grid::-webkit-scrollbar {
  width: 0 !important;
  height: 0 !important;
  display: none !important;
}

/* El contenido puede ser más alto que el panel, pero queda dentro del área desplazable. */
.library-builder-spellbook-panel {
  overflow: hidden !important;
}

.library-builder-spellbook-grid {
  max-height: 100% !important;
  overscroll-behavior: contain;
}


/* =========================================================
   ROK v5.3.213ZZI · SHARED REAL CARD MODAL IN LIBRARY
   ========================================================= */
/* Biblioteca usa el MISMO modal real del juego: #cardInfoOverlay.
   No se crea otro modal. Solo se permite que el modal real viva encima
   de la pantalla de Biblioteca. */

body.rok-library-mode {
  background: #000 !important;
  overflow: hidden !important;
}

/* Oculta visualmente el Home detrás de Biblioteca. */
body.rok-library-mode #mainMenuScreen,
body.rok-library-mode .main-menu-screen,
body.rok-library-mode .main-menu-bg {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

/* La Biblioteca queda como ventana completa. */
body.rok-library-mode #libraryBuilderScreen,
body.rok-library-mode .library-builder-screen {
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  background: #000 !important;
  background-image: none !important;
  z-index: 4100 !important;
  isolation: isolate !important;
}

body.rok-library-mode .library-builder-bg {
  position: fixed !important;
  inset: 0 !important;
  z-index: 0 !important;
  display: block !important;
  background: #000 !important;
  background-image: none !important;
  opacity: 1 !important;
  pointer-events: none !important;
}

body.rok-library-mode .library-builder-shell {
  position: relative !important;
  z-index: 2 !important;
}

/* El modal real vive dentro de .game-shell. Si el padre se oculta,
   el modal real nunca se ve. Por eso se deja visible, pero sin interacción
   salvo para el propio modal. */
body.rok-library-mode .game-shell {
  visibility: visible !important;
  opacity: 1 !important;
  pointer-events: none !important;
}

/* En Biblioteca, el overlay real se convierte en modal de pantalla completa
   por encima del Builder, sin duplicar estructura ni datos. */
body.rok-library-mode #cardInfoOverlay.card-info-overlay,
body.rok-library-mode .card-info-overlay {
  position: fixed !important;
  inset: 0 !important;
  grid-column: auto !important;
  grid-row: auto !important;
  z-index: 9200 !important;
  width: 100cqw !important;
  height: 100cqh !important;
  max-width: none !important;
  max-height: none !important;
  padding: clamp(12px, 2cqw, 28px) !important;
  background: rgba(0, 0, 0, .86) !important;
  pointer-events: auto !important;
  place-items: center !important;
}

body.rok-library-mode #cardInfoOverlay.card-info-overlay.open,
body.rok-library-mode .card-info-overlay.open {
  display: grid !important;
  visibility: visible !important;
  opacity: 1 !important;
}

/* Mantiene la estructura interna real del modal, pero flotando como ventana. */
body.rok-library-mode #cardInfoOverlay .card-info-box {
  width: min(980px, 94cqw) !important;
  max-height: min(760px, 90cqh) !important;
  overflow: auto !important;
  padding: clamp(14px, 2cqw, 24px) !important;
  border: 1px solid rgba(155, 77, 255, .48) !important;
  border-radius: 22px !important;
  background:
    radial-gradient(circle at 20% 0%, rgba(155, 77, 255, .18), transparent 42%),
    linear-gradient(180deg, rgba(18, 15, 28, .98), rgba(4, 4, 8, .98)) !important;
  box-shadow: 0 26px 90px rgba(0,0,0,.76), inset 0 0 32px rgba(0,0,0,.55) !important;
}

/* En Biblioteca no se kastea; se consulta información. */
body.rok-library-mode #cardInfoKastBtn {
  display: none !important;
}

/* El botón Salir del modal real sí queda usable. */
body.rok-library-mode #cardInfoCloseBtn,
body.rok-library-mode #cardInfoOverlay button {
  pointer-events: auto !important;
}

@container rok-app-stage  (max-width: 760px) {
  body.rok-library-mode #cardInfoOverlay .card-info-main {
    grid-template-columns: 1fr !important;
  }

  body.rok-library-mode #cardInfoOverlay .card-info-preview {
    margin: 0 auto !important;
  }
}


/* =========================================================
   ROK v5.3.213ZZJ · TEMP LIBRARY LOCK + META MODAL CLICK FIX
   ========================================================= */
/* TEMP: mientras se crean/ajustan cartas, el JS abre Biblioteca al refrescar.
   Esta parte CSS corrige capas/interacción de los modales secundarios
   de factores, cualidades, habilitado por, X y Back dentro de Biblioteca. */

/* La game-shell debe existir porque ahí vive el modal real compartido. */
body.rok-library-mode .game-shell {
  visibility: visible !important;
  opacity: 1 !important;
  pointer-events: none !important;
}

/* Modal principal real de carta, por encima de Biblioteca. */
body.rok-library-mode #cardInfoOverlay.card-info-overlay,
body.rok-library-mode .card-info-overlay {
  pointer-events: auto !important;
  z-index: 9200 !important;
}

/* Todo lo clicable dentro del modal principal debe recibir eventos. */
body.rok-library-mode #cardInfoOverlay,
body.rok-library-mode #cardInfoOverlay *,
body.rok-library-mode .card-info-overlay,
body.rok-library-mode .card-info-overlay * {
  pointer-events: auto !important;
}

/* Modal secundario real: factores, cualidades, "habilitado por", etc. */
body.rok-library-mode #cardMetaInfoOverlay,
body.rok-library-mode .card-meta-info-overlay,
body.rok-library-mode .card-meta-overlay,
body.rok-library-mode .meta-info-overlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: 9800 !important;
  pointer-events: auto !important;
  visibility: visible !important;
}

/* Si el modal secundario usa clase open, debe quedar encima de todo. */
body.rok-library-mode #cardMetaInfoOverlay.open,
body.rok-library-mode .card-meta-info-overlay.open,
body.rok-library-mode .card-meta-overlay.open,
body.rok-library-mode .meta-info-overlay.open {
  display: grid !important;
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
}

/* Caja/contenido del modal secundario. */
body.rok-library-mode #cardMetaInfoOverlay *,
body.rok-library-mode .card-meta-info-overlay *,
body.rok-library-mode .card-meta-overlay *,
body.rok-library-mode .meta-info-overlay * {
  pointer-events: auto !important;
}

/* Botones críticos que se estaban quedando pegados. */
body.rok-library-mode #cardMetaInfoCloseBtn,
body.rok-library-mode #cardMetaInfoBackBtn,
body.rok-library-mode .card-meta-info-close,
body.rok-library-mode .card-meta-info-back,
body.rok-library-mode .meta-info-close,
body.rok-library-mode .meta-info-back {
  pointer-events: auto !important;
  cursor: pointer !important;
  z-index: 9900 !important;
}

/* Chips/recuadros clicables dentro de los modales reales. */
