    radial-gradient(circle at 78% 66%, rgba(255,104,32,.68) 0 1.8px, transparent 3.1px),
    radial-gradient(circle at 50% 86%, rgba(255,178,88,.70) 0 2px, transparent 3.2px);
  filter: blur(.2px);
  animation: kaguyaChargeSparkle calc(var(--kaguya-charge-pulse-seconds, 1.46s) * 1.32) ease-in-out infinite;
}

.kaguya-charge-persistent-fx.kaguya-charge-primed .kaguya-charge-ring-b,
.kaguya-charge-persistent-fx.kaguya-charge-primed .kaguya-charge-sparks {
  opacity: calc(var(--kaguya-charge-ring-opacity, .42) * .72);
}

.kaguya-charge-persistent-fx.kaguya-charge-channeling[data-kaguya-charge-stage="3"] .kaguya-charge-aura {
  background:
    radial-gradient(circle at 50% 38%, rgba(255,255,240,.88) 0%, rgba(255,226,147,.64) 12%, rgba(255,152,52,.40) 30%, rgba(255,94,14,.22) 46%, transparent 72%),
    radial-gradient(circle at 50% 75%, rgba(255,92,0,.32) 0%, rgba(255,64,0,.18) 28%, transparent 68%);
}


/* =========================================================
   ROK v5.3.131 · KAGUYA · TAMAÑO DE CANALIZACIÓN AJUSTADO
   Mantiene la animación persistente, pero reduce su huella visual.
   ========================================================= */
:root {
  --kaguya-charge-fx-scale: .204;
}

.kaguya-charge-persistent-fx {
  width: calc(var(--token-invocation-w, 76px) * var(--kaguya-charge-fx-scale, .68)) !important;
  height: calc(var(--token-invocation-h, 112px) * var(--kaguya-charge-fx-scale, .68)) !important;
  transform: translate(-50%, -86%) !important;
}

.kaguya-charge-persistent-fx .kaguya-charge-aura {
  filter: blur(calc(5px + (var(--kaguya-charge-strength, .58) * 7px))) !important;
}

.kaguya-charge-persistent-fx .kaguya-charge-ring-a {
  box-shadow:
    0 0 0 1px rgba(255,255,255,.12),
    0 0 calc(7px + (var(--kaguya-charge-strength, .58) * 9px)) rgba(255, 164, 44, .30) !important;
}

.kaguya-charge-persistent-fx .kaguya-charge-ring-b {
  box-shadow: 0 0 calc(6px + (var(--kaguya-charge-strength, .58) * 8px)) rgba(255, 92, 0, .24) !important;
}


/* =========================================================
   ROK v5.3.132 · AJUSTE FINO OCULTO SOBRE ATAQUE
   El icono de Oculto queda más a la derecha, centrado sobre el icono de arma.
   ========================================================= */


/* =========================================================
   ROK v5.3.133 · EVASIÓN COMO REDUCCIÓN DE PRECISIÓN
   Burbuja oscura, clickeable y desplazada 90% a la derecha.
   ========================================================= */
.combat-mini-modifier-chip,
button.combat-mini-modifier-chip {
  right: -7px !important;
  transform: translateX(90%) !important;
  border: 1px solid rgba(255,255,255,.72) !important;
  background: radial-gradient(circle at 35% 25%, rgba(69, 52, 91, .96), rgba(20, 13, 31, .98) 58%, rgba(5, 3, 9, .98) 100%) !important;
  box-shadow: 0 0 8px rgba(0,0,0,.85), 0 0 10px rgba(155,77,255,.42) !important;
  pointer-events: auto !important;
  cursor: help !important;
  appearance: none !important;
  -webkit-appearance: none !important;
}

.combat-mini-modifier-chip img {
  filter: brightness(1.24) drop-shadow(0 0 4px rgba(255,255,255,.52)) !important;
}

.combat-mini-modifier-chip b {
  color: #ffffff !important;
  text-shadow: 0 1px 2px rgba(0,0,0,.95), 0 0 5px rgba(255,255,255,.38) !important;
}

.combat-mini-precision-penalty::after {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: inherit;
  pointer-events: none;
}


/* =========================================================
   ROK v5.3.151 · ESTELA DE PARTÍCULAS PARA QUEMADURA
   La flecha conserva su color elemental, pero los ataques con Quemadura
   dejan brasas flotantes detrás del proyectil.
   ========================================================= */
.distance-burn-trail-particle {
  position: absolute;
  width: var(--burn-trail-size, 6px);
  height: var(--burn-trail-size, 6px);
  border-radius: 999px;
  pointer-events: none;
  z-index: 52036 !important;
  transform: translate(-50%, -50%) scale(.35);
  opacity: 0;
  background:
    radial-gradient(circle, rgba(255,255,224,.96) 0 16%, rgba(255,202,72,.86) 26%, rgba(255,93,0,.72) 50%, rgba(255,29,0,0) 78%);
  box-shadow:
    0 0 7px rgba(255,222,108,.92),
    0 0 14px rgba(255,100,0,.72),
    0 0 22px rgba(255,36,0,.46);
  mix-blend-mode: screen;
  filter: blur(.15px);
  animation: burnProjectileParticleTrail .62s ease-out var(--burn-trail-delay, 0s) both;
}

.distance-burn-trail-particle:nth-last-child(2n) {
  background:
    radial-gradient(circle, rgba(255,238,178,.90) 0 18%, rgba(255,132,24,.78) 38%, rgba(255,45,0,0) 78%);
}

.distance-burn-trail-particle:nth-last-child(3n) {
  filter: blur(.7px);
}

@keyframes burnProjectileParticleTrail {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(.24);
  }
  18% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.05);
  }
  70% {
    opacity: .58;
    transform: translate(calc(-50% + var(--burn-trail-drift-x, 12px)), calc(-50% + var(--burn-trail-drift-y, -10px))) scale(.82);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + (var(--burn-trail-drift-x, 12px) * 1.45)), calc(-50% + (var(--burn-trail-drift-y, -10px) * 1.45))) scale(.18);
  }
}

/* =========================================================
   ROK v5.3.132 · Quemadura activa visible en tarjeta inferior
   Muestra el nombre del factor quemado junto al ícono sin tocar otros estados.
   ========================================================= */
.selected-unit-command-status-factor-burn {
  width: 20px !important;
  height: 20px !important;
  min-width: 20px !important;
  padding: 0 !important;
  gap: 0 !important;
  margin-right: -5px;
  background: rgba(18, 20, 28, .92) !important;
  border-color: rgba(255, 118, 42, .68) !important;
  box-shadow: 0 8px 16px rgba(0,0,0,.34), 0 0 12px rgba(255, 87, 28, .28) !important;
}

.selected-unit-command-status-factor-burn .selected-unit-command-status-icon,
.selected-unit-command-status-factor-burn .selected-unit-command-status-svg {
  width: 12px !important;
  height: 12px !important;
}

.selected-unit-command-status-factor-burn .selected-unit-command-status-svg svg {
  width: 12px !important;
  height: 12px !important;
}

.selected-unit-command-status-label {
  color: #ffe8cf;
  font-size: 9px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .01em;
  text-shadow: 0 1px 2px rgba(0,0,0,.65);
  white-space: nowrap;
}

.selected-unit-command-status-factor-burn .selected-unit-command-status-count {
  background: #ff8a2a !important;
  color: #190c06 !important;
}

/* =========================================================
   ROK v5.3.131 · FACTORES PROGRESIVOS · PULSO EN TARJETA INFERIOR
   La Quemadura se muestra solo en la tarjeta inferior, no sobre el token.
   ========================================================= */
.selected-unit-command-panel.progressive-factor-card-pulse {
  animation: progressiveFactorCardPulse .82s ease-in-out both !important;
}

.selected-unit-command-panel.progressive-factor-card-pulse-burn .selected-unit-command-card {
  box-shadow: 0 0 0 2px rgba(255, 147, 42, .72), 0 0 20px rgba(255, 82, 0, .46), 0 14px 28px rgba(0,0,0,.42) !important;
}

@keyframes progressiveFactorCardPulse {
  0%   { transform: translateX(0) scale(1); filter: brightness(1); }
  12%  { transform: translateX(-3px) scale(1.02); filter: brightness(1.28); }
  24%  { transform: translateX(3px) scale(1.02); filter: brightness(1.22); }
  38%  { transform: translateX(-4px) scale(1.03); filter: brightness(1.34); }
  52%  { transform: translateX(4px) scale(1.03); filter: brightness(1.26); }
  70%  { transform: translateX(-2px) scale(1.01); filter: brightness(1.16); }
  100% { transform: translateX(0) scale(1); filter: brightness(1); }
}


/* =========================================================
   ROK v5.3.133 · VENTANA RÁPIDA DE REACCIÓN · BASE VISUAL
   Barra breve al inicio de fase. Enter abre el modal base.
   ========================================================= */
.quick-reaction-window {
  position: fixed;
  left: 50%;
  top: 88px;
  transform: translateX(-50%);
  width: min(360px, calc(100cqw - 32px));
  z-index: 9100;
  display: none;
  pointer-events: none;
}

.quick-reaction-window.visible {
  display: block;
}

.quick-reaction-window-shell {
  padding: 9px 12px 10px;
  border: 1px solid rgba(255,255,255,.22);
  border-radius: 14px;
  background: rgba(10, 11, 18, .82);
  box-shadow: 0 14px 30px rgba(0,0,0,.46), 0 0 18px rgba(255, 214, 96, .16);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.quick-reaction-window-title {
  color: #fff3cf;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
  line-height: 1;
}

.quick-reaction-window-hint {
  margin-top: 4px;
  color: rgba(255,255,255,.84);
  font-size: 10px;
  font-weight: 800;
}

.quick-reaction-window-track {
  position: relative;
  overflow: hidden;
  margin-top: 7px;
  height: 5px;
  border-radius: 999px;
  background: rgba(255,255,255,.12);
}

.quick-reaction-window-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 0%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(255, 214, 96, .95), rgba(255, 112, 42, .95));
  box-shadow: 0 0 12px rgba(255, 160, 44, .45);
}

@keyframes quickReactionFill {
  from { width: 0%; }
  to { width: 100%; }
}

.quick-reaction-modal {
  position: fixed;
  inset: 0;
  z-index: 9200;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(0,0,0,.20);
  pointer-events: auto;
}

.quick-reaction-modal.visible {
  display: flex;
}

.quick-reaction-modal-shell {
  width: min(520px, calc(100cqw - 30px));
  max-height: min(70cqh, 540px);
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 18px;
  background: rgba(9, 10, 16, .88);
  box-shadow: 0 20px 44px rgba(0,0,0,.54), 0 0 24px rgba(255, 214, 96, .13);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.quick-reaction-modal-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid rgba(255,255,255,.12);
  color: #fff3cf;
  font-size: 13px;
  letter-spacing: .03em;
}

#quickReactionModalTimer {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 24px;
  border-radius: 999px;
  background: rgba(255, 214, 96, .16);
  color: #fff;
  font-weight: 900;
}

.quick-reaction-modal-list {
  max-height: calc(min(70cqh, 540px) - 50px);
  overflow-y: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 10px;
}

.quick-reaction-modal-list::-webkit-scrollbar {
  width: 0;
  height: 0;
}

.quick-reaction-candidate-row {
  display: grid;
  grid-template-columns: 74px 1fr;
  gap: 10px;
  align-items: center;
  padding: 8px;
  border-radius: 14px;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.10);
}

.quick-reaction-candidate-row + .quick-reaction-candidate-row {
  margin-top: 8px;
}

.quick-reaction-candidate-thumb {
  width: 68px;
  height: 68px;
  overflow: hidden;
  border-radius: 10px;
  background: rgba(0,0,0,.28);
}

.quick-reaction-candidate-thumb .selected-command-card-composite,
.quick-reaction-candidate-thumb .selected-command-card-shell,
.quick-reaction-candidate-thumb .card {
  width: 100%;
  height: 100%;
}

.quick-reaction-candidate-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.quick-reaction-candidate-actions strong {
  flex: 0 0 100%;
  color: #fff;
  font-size: 12px;
  line-height: 1.1;
}

.quick-reaction-candidate-note {
  flex: 0 0 100%;
  margin-bottom: 2px;
  color: rgba(255,255,255,.62);
  font-size: 10px;
  font-weight: 700;
}

.quick-reaction-candidate-actions button {
  min-height: 25px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.22);
  background: rgba(255,255,255,.10);
  color: rgba(255,255,255,.72);
  font-size: 10px;
  font-weight: 900;
}

body.rok-menu-mode .quick-reaction-window,
body.rok-menu-mode .quick-reaction-modal,
body.rok-library-mode .quick-reaction-window,
body.rok-library-mode .quick-reaction-modal {
  display: none !important;
}

/* =========================================================
   ROK v40.1 · VENTANA DE REACCIÓN · OBJETIVOS DE ATAQUE A DISTANCIA
   Conecta el botón Atacar con una lista corta de objetivos válidos.
   ========================================================= */
.quick-reaction-target-list {
  width: 100%;
  max-height: 74px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.quick-reaction-target-list::-webkit-scrollbar {
  width: 0;
  height: 0;
}

.quick-reaction-candidate-actions .quick-reaction-target-btn {
  width: 100%;
  justify-content: flex-start;
  padding: 5px 8px;
  font-size: 10px;
  text-align: left;
  background: rgba(42, 22, 12, .88);
  border-color: rgba(255, 151, 72, .52);
}

.quick-reaction-candidate-actions .quick-reaction-target-btn:hover:not(:disabled) {
  background: rgba(77, 34, 14, .94);
}

/* =========================================================
   ROK v45 · AVISO BREVE · EL RIVAL ESTÁ PENSANDO
   Señal compacta para ventanas de reacción/IA sin bloquear pantalla.
   ========================================================= */
.opponent-thinking-notice {
  position: fixed;
  top: 148px;
  left: 50%;
  transform: translateX(-50%) translateY(-6px);
  z-index: 9150;
  display: none;
  pointer-events: none;
  opacity: 0;
}

.opponent-thinking-notice.visible {
  display: block;
  animation: opponentThinkingNoticeIn .18s ease-out forwards;
}

.opponent-thinking-notice-shell {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.20);
  background: rgba(8, 10, 17, .84);
  color: rgba(255,255,255,.92);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .02em;
  box-shadow: 0 12px 26px rgba(0,0,0,.42), 0 0 18px rgba(255, 214, 96, .16);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.opponent-thinking-hourglass {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: rgba(255, 214, 96, .16);
  animation: opponentThinkingHourglassPulse .72s ease-in-out infinite alternate;
}

@keyframes opponentThinkingNoticeIn {
  from { opacity: 0; transform: translateX(-50%) translateY(-6px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

@keyframes opponentThinkingHourglassPulse {
  from { transform: scale(.94); filter: brightness(.92); }
  to { transform: scale(1.08); filter: brightness(1.24); }
}

body.rok-menu-mode .opponent-thinking-notice,
body.rok-library-mode .opponent-thinking-notice {
  display: none !important;
}

/* =========================================================
   ROK v46 · KASTER EN ZONA RIVAL · AVISO + DAÑO VISUAL
   ========================================================= */
.caster-enemy-zone-warning {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 4px;
  padding: 4px 8px;
  border: 1px solid rgba(255, 78, 78, .72);
  border-radius: 999px;
  background: rgba(48, 8, 8, .82);
  color: #ffe7df;
  font-size: 9px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: .02em;
  text-transform: uppercase;
  text-shadow: 0 1px 2px rgba(0,0,0,.75), 0 0 9px rgba(255, 68, 40, .45);
  box-shadow: 0 0 0 1px rgba(255,255,255,.08), 0 0 16px rgba(255, 48, 18, .28);
  cursor: pointer;
}

.caster-enemy-zone-warning[hidden] {
  display: none !important;
}

.caster-enemy-zone-warning:hover,
.caster-enemy-zone-warning:focus-visible {
  transform: translateY(-1px);
  background: rgba(78, 12, 8, .92);
  box-shadow: 0 0 0 1px rgba(255,255,255,.12), 0 0 22px rgba(255, 58, 22, .42);
  outline: none;
}

.caster-enemy-zone-warning.pulse {
  animation: casterEnemyZoneWarningPulse 1s ease-in-out both;
}

.cell.caster-enemy-zone-damage-pulse {
  animation: casterEnemyZoneCellPulse .9s ease-in-out both !important;
  background: rgba(255, 18, 18, .52) !important;
  box-shadow: inset 0 0 0 2px rgba(255, 240, 220, .86), 0 0 18px rgba(255, 30, 10, .62) !important;
}

@keyframes casterEnemyZoneWarningPulse {
  0%, 100% { transform: translateY(0) scale(1); filter: brightness(1); }
  16% { transform: translateY(-1px) scale(1.04); filter: brightness(1.55); }
  34% { transform: translateY(1px) scale(.98); filter: brightness(1.15); }
  52% { transform: translateY(-1px) scale(1.06); filter: brightness(1.48); }
  76% { transform: translateY(0) scale(1.01); filter: brightness(1.25); }
}

@keyframes casterEnemyZoneCellPulse {
  0% { filter: brightness(1); }
  20% { filter: brightness(1.85) saturate(1.35); }
  42% { filter: brightness(1.05); }
  64% { filter: brightness(1.7) saturate(1.25); }
  100% { filter: brightness(1); }
}

/* =========================================================
   ROK v52 · MOVIMIENTO ASISTIDO · BOTÓN EN COLUMNA DE FASES
   Controles CSS actuales de esta etapa.
   ========================================================= */


.assisted-move-toggle {
