/* =========================================================
   ROK v136 · Círculo de invocación previo + entrada antes de buffs
   ========================================================= */
.invocation-summon-circle-fx {
  position: absolute;
  transform: translate(-50%, -50%) scale(.85);
  transform-origin: center;
  pointer-events: none;
  display: grid;
  place-items: center;
  isolation: isolate;
  mix-blend-mode: screen;
}
.invocation-summon-circle-fx::before {
  content: '';
  position: absolute;
  inset: 17%;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--summon-color, #fff) 46%, white 54%) 0%, color-mix(in srgb, var(--summon-color, #fff) 32%, transparent 68%) 38%, transparent 72%);
  opacity: .34;
  filter: blur(7px);
  animation: summonCircleGlowBreath 1.02s ease-out both;
  z-index: -1;
}
.invocation-summon-circle-fx .summon-circle-core {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  transform-origin: center;
  animation: summonCircleSpinGrow 1.04s cubic-bezier(.16,.78,.18,1) both;
}
.invocation-summon-circle-fx img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: .92;
  filter:
    drop-shadow(0 0 4px rgba(255,255,255,.92))
    drop-shadow(0 0 12px var(--summon-color, #ffffff))
    drop-shadow(0 0 24px color-mix(in srgb, var(--summon-color, #ffffff) 62%, transparent 38%));
}
.invocation-summon-circle-fx .summon-light-ray {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 36%;
  transform-origin: 50% 0%;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255,255,255,.98), color-mix(in srgb, var(--summon-color, #fff) 74%, rgba(255,255,255,.55) 26%) 34%, transparent 100%);
  box-shadow: 0 0 8px var(--summon-color, #fff), 0 0 14px rgba(255,255,255,.34);
  opacity: 0;
  animation: summonRayFade 1.02s cubic-bezier(.16,.78,.18,1) both;
}
.invocation-summon-circle-fx .summon-light-ray-a { transform: translate(-50%, -50%) rotate(12deg); animation-delay: .02s; }
.invocation-summon-circle-fx .summon-light-ray-b { transform: translate(-50%, -50%) rotate(72deg); animation-delay: .11s; }
.invocation-summon-circle-fx .summon-light-ray-c { transform: translate(-50%, -50%) rotate(135deg); animation-delay: .06s; }
.invocation-summon-circle-fx .summon-light-ray-d { transform: translate(-50%, -50%) rotate(204deg); animation-delay: .15s; }
.invocation-summon-circle-fx .summon-light-ray-e { transform: translate(-50%, -50%) rotate(268deg); animation-delay: .08s; }
.invocation-summon-circle-fx .summon-light-ray-f { transform: translate(-50%, -50%) rotate(322deg); animation-delay: .18s; }

@keyframes summonCircleSpinGrow {
  0% { opacity: 0; transform: scale(.72) rotate(-35deg); filter: blur(1px); }
  14% { opacity: 1; transform: scale(.84) rotate(8deg); filter: blur(0); }
  72% { opacity: 1; transform: scale(1.10) rotate(236deg); filter: blur(0); }
  100% { opacity: 0; transform: scale(1.25) rotate(318deg); filter: blur(1.1px); }
}
@keyframes summonCircleGlowBreath {
  0% { opacity: 0; transform: scale(.64); }
  24% { opacity: .42; transform: scale(.88); }
  74% { opacity: .32; transform: scale(1.18); }
  100% { opacity: 0; transform: scale(1.32); }
}
@keyframes summonRayFade {
  0% { opacity: 0; height: 18%; transform-origin: 50% 0%; }
  18% { opacity: .88; height: 35%; }
  64% { opacity: .52; height: 47%; }
  100% { opacity: 0; height: 55%; }
}

.unit.invocation.summon-entry-drop {
  animation: invocationSummonEntryDrop .86s cubic-bezier(.16,.76,.18,1) both !important;
  pointer-events: none !important;
}
.unit.invocation.summon-entry-drop > .unit-token-img {
  filter:
    drop-shadow(1px 0 0 rgba(255,255,255,.95))
    drop-shadow(-1px 0 0 rgba(255,255,255,.95))
    drop-shadow(0 1px 0 rgba(255,255,255,.95))
    drop-shadow(0 -1px 0 rgba(255,255,255,.95))
    drop-shadow(0 0 10px color-mix(in srgb, var(--unit-glow, #fff) 76%, white 24%))
    drop-shadow(0 0 18px color-mix(in srgb, var(--unit-glow, #fff) 50%, transparent 50%))
    drop-shadow(0 12px 9px rgba(0,0,0,.60)) !important;
}
.unit.invocation.summon-entry-drop::before {
  content: '';
  position: absolute;
  left: 50%;
  bottom: 6%;
  width: 64px;
  height: 24px;
  border-radius: 50%;
  pointer-events: none;
  z-index: 1;
  background: radial-gradient(ellipse, color-mix(in srgb, var(--unit-glow, #fff) 34%, rgba(255,255,255,.22) 66%) 0%, color-mix(in srgb, var(--unit-glow, #fff) 18%, transparent 82%) 54%, transparent 78%);
  filter: blur(.2px);
  transform: translateX(-50%) scale(.70);
  animation: invocationSummonGroundPulse .86s ease-out both;
}
@keyframes invocationSummonEntryDrop {
  0% {
    opacity: 0;
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-116% + var(--invocation-offset-y))) scale(.88);
    filter: blur(2px) drop-shadow(0 18px 10px rgba(0,0,0,.38));
  }
  48% {
    opacity: 1;
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-77% + var(--invocation-offset-y))) scale(1.035, .975);
    filter: blur(0) drop-shadow(0 18px 10px rgba(0,0,0,.55));
  }
  62% {
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(.975, 1.045);
  }
  77% {
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-84% + var(--invocation-offset-y))) scale(1.018, .992);
  }
  100% {
    opacity: 1;
    transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1);
    filter: drop-shadow(0 18px 10px rgba(0,0,0,.55));
  }
}
@keyframes invocationSummonGroundPulse {
  0% { opacity: 0; transform: translateX(-50%) scale(.48); }
  48% { opacity: .46; transform: translateX(-50%) scale(1.04); }
  100% { opacity: 0; transform: translateX(-50%) scale(1.32); }
}

