/* =========================================================
   ROK v5.5.130 · DEFENSA 2 / COLOR DE COUNTER / TRACKERS
   ========================================================= */
.caster-defend-fx {
  position: absolute;
  width: 76px;
  height: 76px;
  transform: translate(-50%, -50%);
  z-index: 52070;
  pointer-events: none;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 10px color-mix(in srgb, var(--caster-defend-color, #5400FF) 70%, transparent));
  animation: casterDefendFxLife .62s ease-out both;
}
.caster-defend-ring,
.caster-defend-shield {
  position: absolute;
  border-radius: 50%;
}
.caster-defend-ring {
  inset: 4px;
  border: 2px solid color-mix(in srgb, var(--caster-defend-color, #5400FF) 72%, white 28%);
  box-shadow:
    0 0 12px color-mix(in srgb, var(--caster-defend-color, #5400FF) 66%, transparent),
    inset 0 0 12px color-mix(in srgb, var(--caster-defend-color, #5400FF) 28%, transparent);
  animation: casterDefendRingPulse .62s ease-out both;
}
.caster-defend-shield {
  width: 42px;
  height: 48px;
  border-radius: 44% 44% 56% 56% / 32% 32% 68% 68%;
  border: 1px solid color-mix(in srgb, var(--caster-defend-color, #5400FF) 54%, white 46%);
  background: linear-gradient(145deg,
    color-mix(in srgb, var(--caster-defend-color, #5400FF) 18%, rgba(255,255,255,.18)),
    color-mix(in srgb, var(--caster-defend-color, #5400FF) 10%, transparent));
  box-shadow: inset 0 0 14px rgba(255,255,255,.12), 0 0 10px color-mix(in srgb, var(--caster-defend-color, #5400FF) 40%, transparent);
  clip-path: polygon(50% 0%, 88% 15%, 82% 67%, 50% 100%, 18% 67%, 12% 15%);
  animation: casterDefendShieldSet .62s ease-out both;
}
@keyframes casterDefendFxLife {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.62); }
  24% { opacity: 1; transform: translate(-50%, -50%) scale(1.06); }
  76% { opacity: .88; transform: translate(-50%, -50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.14); }
}
@keyframes casterDefendRingPulse {
  0% { opacity: 0; transform: scale(.58); }
  34% { opacity: 1; transform: scale(1.03); }
  100% { opacity: 0; transform: scale(1.18); }
}
@keyframes casterDefendShieldSet {
  0% { opacity: 0; transform: scale(.72); filter: brightness(1.7); }
  34% { opacity: .92; transform: scale(1.04); filter: brightness(1.25); }
  100% { opacity: 0; transform: scale(.96); filter: brightness(1); }
}

