/* v243 · reglas conectadas a los controles del inicio del CSS */
.saved-spellbook-summary-chip.type-ability .saved-spellbook-chip-icon,
.saved-spellbook-summary-chip.type-casterAbility .saved-spellbook-chip-icon {
  position: relative;
  width: 29px;
  height: 29px;
  overflow: visible;
}

.saved-spellbook-summary-chip.type-ability .saved-spellbook-chip-icon > img:first-child {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--spellbook-ability-icon-size);
  height: var(--spellbook-ability-icon-size);
  object-fit: contain;
  transform: translate(
    calc(-50% + var(--spellbook-ability-icon-x)),
    calc(-50% + var(--spellbook-ability-icon-y))
  );
}

.saved-spellbook-summary-chip.type-casterAbility .saved-spellbook-chip-icon > img:first-child {
  position: absolute;
