  height: 17px;
  margin-left: -11px;
  margin-top: -8.5px;
  background: center / contain no-repeat var(--yasugana-crow-image);
  transform-origin: center 55%;
  opacity: .84;
  font-size: 0;
  line-height: 0;
  color: transparent;
  text-shadow: none;
