.yasugana-crow-mark.crow-1 { --crow-scale: .82; --yasugana-crow-image: url('assets/yasugana-crow-real-side.png'); animation: yasuganaCrowFlightA 2.2s ease-in-out .00s infinite; }
.yasugana-crow-mark.crow-2 { --crow-scale: .98; --yasugana-crow-image: url('assets/yasugana-crow-real-front.png'); animation: yasuganaCrowFlightB 2.4s ease-in-out .24s infinite; }
