.minokage-channel-fx-v340 .minokage-channel-ring,
.minokage-channel-fx-v340 .minokage-channel-core,
.minokage-channel-fx-v340 .minokage-channel-slash {
  position: absolute;
  left: 50%;
  top: 50%;
  pointer-events: none;
}

.minokage-channel-fx-v340 .minokage-channel-ring {
  width: 72%;
  height: 72%;
  border: 2px solid rgba(255,255,255,.74);
  border-left-color: rgba(0,0,0,.95);
  border-bottom-color: rgba(0,0,0,.78);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: minokage-channel-spin 1.12s linear infinite;
}

.minokage-channel-fx-v340 .minokage-channel-ring-b {
  width: 48%;
  height: 48%;
  border-width: 1px;
  opacity: .72;
  animation-direction: reverse;
  animation-duration: .76s;
}

.minokage-channel-fx-v340 .minokage-channel-core {
  width: 20%;
  height: 20%;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(255,255,255,.9) 0 12%, rgba(255,255,255,.16) 35%, rgba(0,0,0,.72) 72%, transparent 74%);
  animation: minokage-channel-pulse .82s ease-in-out infinite alternate;
}

.minokage-channel-fx-v340 .minokage-channel-slash {
  width: 92%;
  height: 3px;
  transform-origin: center;
  background: linear-gradient(90deg, transparent 0 5%, rgba(0,0,0,.95) 20%, #fff 49%, rgba(0,0,0,.95) 78%, transparent 96%);
  box-shadow: 0 0 7px rgba(255,255,255,.66);
  animation: minokage-channel-slash 1.04s ease-in-out infinite;
}

.minokage-channel-fx-v340 .minokage-channel-slash-b {
  transform: translate(-50%, -50%) rotate(76deg);
