/* ==========================================================================
   R.O.K Lite v379 · Foil por botón y burbuja de disponibilidad separada
   ========================================================================== */

/* Cada botón es un recorte independiente. Nada del foil puede pintarse sobre
   Página 1, Página 2 o Página 3 vecinas. */
#tabStack.tab-stack > .deck-tab {
  position: relative !important;
  overflow: hidden !important;
  contain: paint !important;
  isolation: isolate !important;
}

/* El estado disponible solo usa iluminación interior. No hay resplandor del
   propio botón fuera de sus límites. */
#tabStack.tab-stack > .deck-tab.spellbook-page-ready,
#tabStack.tab-stack > .deck-tab.spellbook-page-active-ready {
  border-color: rgba(255, 226, 125, .82) !important;
  box-shadow:
    inset 0 0 0 1px rgba(255, 232, 150, .60),
    inset 0 0 12px rgba(255, 211, 74, .22) !important;
}

/* Anula definitivamente todos los pseudo-foils antiguos. */
#tabStack.tab-stack > .deck-tab.spellbook-page-ready::after,
#tabStack.tab-stack > .deck-tab.spellbook-page-active-ready::after,
#tabStack.tab-stack > .deck-tab.quick-reaction-page-focus::after {
  content: none !important;
  display: none !important;
  animation: none !important;
}

/* La reacción rápida ya no dibuja foil sobre los botones de página. */
#tabStack.tab-stack > .deck-tab > .quick-reaction-page-foil {
  display: none !important;
}

/* Foil normal de disponibilidad: capa real, hija del botón exacto. */
#tabStack.tab-stack > .deck-tab > .spellbook-page-foil {
  position: absolute !important;
  inset: 2px !important;
  display: none !important;
  pointer-events: none !important;
  overflow: hidden !important;
  border: 0 !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  clip-path: inset(0) !important;
  mix-blend-mode: screen !important;
  opacity: 1 !important;
  z-index: 2 !important;
  background-image: linear-gradient(
    115deg,
    transparent 0%,
    transparent 30%,
    rgba(255,255,255,.10) 39%,
    rgba(255,244,188,.62) 48%,
    rgba(255,255,255,.16) 57%,
    transparent 68%,
    transparent 100%
  ) !important;
  background-repeat: no-repeat !important;
  background-size: 240% 100% !important;
  background-position: 155% 50%;
  animation: spellbookPageButtonFoilSweep 1.65s ease-in-out infinite !important;
  filter: none !important;
}

#tabStack.tab-stack > .deck-tab.spellbook-page-ready > .spellbook-page-foil,
#tabStack.tab-stack > .deck-tab.spellbook-page-active-ready > .spellbook-page-foil {
  display: block !important;
}

/* Cada página usa una fase distinta para que los tres botones no parezcan una
   sola franja luminosa continua. */
#tabStack.tab-stack > .deck-tab[data-tab="0"] > .spellbook-page-foil {
  animation-delay: 0s !important;
}
#tabStack.tab-stack > .deck-tab[data-tab="1"] > .spellbook-page-foil {
  animation-delay: -.55s !important;
}
#tabStack.tab-stack > .deck-tab[data-tab="2"] > .spellbook-page-foil {
  animation-delay: -1.10s !important;
}

/* Burbuja pequeña e independiente. Nunca se reutiliza como foil rectangular. */
#tabStack.tab-stack > .deck-tab > .spellbook-page-ready-indicator {
  position: absolute !important;
  top: 4px !important;
  right: auto !important;
  bottom: auto !important;
  left: 4px !important;
  width: 9px !important;
  height: 9px !important;
  min-width: 9px !important;
  min-height: 9px !important;
  display: none !important;
  pointer-events: none !important;
  overflow: visible !important;
  border: 1px solid rgba(255,255,255,.92) !important;
  border-radius: 50% !important;
  clip-path: none !important;
  mix-blend-mode: normal !important;
  opacity: 1 !important;
  z-index: 4 !important;
  background:
    radial-gradient(
      circle at 35% 35%,
      #ffffff 0%,
      #fff4a8 32%,
      #ffd84d 62%,
      #d79c11 100%
    ) !important;
  background-size: 100% 100% !important;
  background-position: center !important;
  box-shadow:
    0 0 2px rgba(255,255,255,.92),
    0 0 5px rgba(255,215,74,.72) !important;
  animation: spellbookPageReadyDotPulse .90s ease-in-out infinite !important;
  filter: none !important;
}

#tabStack.tab-stack > .deck-tab.spellbook-page-ready > .spellbook-page-ready-indicator,
#tabStack.tab-stack > .deck-tab.spellbook-page-active-ready > .spellbook-page-ready-indicator {
  display: block !important;
}

/* Ninguna pseudo-capa puede agrandar el foil o la burbuja. */
#tabStack.tab-stack > .deck-tab > .spellbook-page-foil::before,
#tabStack.tab-stack > .deck-tab > .spellbook-page-foil::after,
#tabStack.tab-stack > .deck-tab > .spellbook-page-ready-indicator::before,
#tabStack.tab-stack > .deck-tab > .spellbook-page-ready-indicator::after {
  content: none !important;
  display: none !important;
}

/* El texto siempre permanece por encima del foil y debajo de la burbuja. */
#tabStack.tab-stack > .deck-tab > .deck-tab-label {
  position: relative !important;
  z-index: 3 !important;
  pointer-events: none !important;
}

@keyframes spellbookPageButtonFoilSweep {
  0% {
    background-position: 155% 50%;
    opacity: .18;
  }
  38% {
    opacity: .92;
  }
  100% {
    background-position: -55% 50%;
    opacity: .18;
  }
}

@keyframes spellbookPageReadyDotPulse {
  0%, 100% {
    transform: scale(.86);
    opacity: .72;
  }
  50% {
    transform: scale(1.14);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  #tabStack.tab-stack > .deck-tab > .spellbook-page-foil,
  #tabStack.tab-stack > .deck-tab > .spellbook-page-ready-indicator {
    animation: none !important;
  }
  #tabStack.tab-stack > .deck-tab > .spellbook-page-foil {
    background-position: 50% 50% !important;
    opacity: .55 !important;
  }
}


/* ========================================================================== 
   R.O.K Lite v382 · Contenedores 10% más bajos y contenido protegido arriba
   ========================================================================== */

@container rok-app-stage  (min-width: 901px) {
  /* Solo se fija la geometría exterior: cuatro filas a la izquierda y una
     quinta fila de enfriamientos a todo lo ancho. El contenido interno de
     cada fila conserva sus flex, wraps, chips, iconos y orden originales. */
  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open) .card-info-lower {
    --card-info-uniform-row-height: 58px;
    --card-info-uniform-row-gap: 8px;
    position: relative !important;
    display: grid !important;
    grid-template-columns: minmax(0, 58%) minmax(190px, 1fr) !important;
    grid-template-rows: calc(
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap)
    ) !important;
    gap: 10px !important;
    width: 100% !important;
    height: calc(
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap)
    ) !important;
    min-height: 0 !important;
    max-height: none !important;
    margin: 8px 0 12px !important;
    padding: 0 !important;
    overflow: visible !important;
    align-items: stretch !important;
  }

  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-lower > .card-info-stats.card-info-stats-grouped {
    position: static !important;
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) !important;
    grid-template-rows: repeat(4, var(--card-info-uniform-row-height)) !important;
    gap: var(--card-info-uniform-row-gap) !important;
    width: 100% !important;
    height: calc(
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap)
    ) !important;
    min-height: 0 !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: visible !important;
  }

  /* Las cuatro filas conservan su distribución interna original. Solo reciben
     la misma caja exterior y scroll vertical cuando su propio contenido salta
     a una segunda línea. */
  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-stats.card-info-stats-grouped > .stat-row:not(.stat-row-cooldowns) {
    box-sizing: border-box !important;
    width: 100% !important;
    height: var(--card-info-uniform-row-height) !important;
    min-height: var(--card-info-uniform-row-height) !important;
    max-height: var(--card-info-uniform-row-height) !important;
    margin: 0 !important;
    padding: 10px 8px 2px !important;
    overflow-x: hidden !important;
    overflow-y: auto !important;
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
  }

  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-stats.card-info-stats-grouped > .stat-row:not(.stat-row-cooldowns)::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
    display: none !important;
  }

  /* El panel derecho conserva exactamente su composición interna; únicamente
     se iguala su altura exterior a la suma de las cuatro primeras filas. */
  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-lower > .card-info-extra-panel {
    width: 100% !important;
    height: calc(
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-height) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap) +
      var(--card-info-uniform-row-gap)
    ) !important;
    min-height: 0 !important;
    max-height: none !important;
    margin: 0 !important;
    align-self: stretch !important;
  }

  /* Quinta fila: se mantiene el marco exterior que comparte estilo con las
     otras cuatro filas, pero cruza desde el borde izquierdo hasta el derecho. */
  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-stats.card-info-stats-grouped > .stat-row-cooldowns {
    box-sizing: border-box !important;
    position: absolute !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    width: 100% !important;
    height: var(--card-info-uniform-row-height) !important;
    min-height: var(--card-info-uniform-row-height) !important;
    max-height: var(--card-info-uniform-row-height) !important;
    margin: 0 !important;
    padding: 10px 8px 2px !important;
    overflow-x: hidden !important;
    overflow-y: auto !important;
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
  }

  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-stats.card-info-stats-grouped > .stat-row-cooldowns::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
    display: none !important;
  }

  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-stats.card-info-stats-grouped > .stat-row-cooldowns[hidden] {
    display: none !important;
  }

  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .stat-row-cooldowns > strong,
  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    #cardInfoCooldownTray {
    width: 100% !important;
    height: 100% !important;
    min-width: 0 !important;
    min-height: 0 !important;
    max-width: none !important;
    padding: 0 !important;
  }

  /* Se elimina únicamente la cápsula negra adicional. El orden, chips, wrap,
     alineación y separación de los enfriamientos permanecen intactos. */
  #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open)
    .card-info-cooldown-tray {
    width: 100% !important;
    height: 100% !important;
    min-height: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
