  animation: gloriaGroundGlowV410 1.18s cubic-bezier(.16,.84,.22,1) both;
}
.gloria-restore-ray-v410 {
  bottom: -8% !important;
  opacity: 0;
  transform-origin: 50% 100%;
  animation-name: gloriaRayTravelV410 !important;
  animation-duration: var(--gloria-ray-duration, 980ms) !important;
  animation-delay: var(--gloria-ray-delay, 0ms) !important;
  animation-timing-function: cubic-bezier(.17,.74,.18,1) !important;
  animation-fill-mode: both !important;
}
.gloria-restore-spark-v410 {
  animation-name: gloriaSparkTravelV410 !important;
  animation-duration: var(--gloria-spark-duration, 900ms) !important;
  animation-delay: var(--gloria-spark-delay, 0ms) !important;
  animation-timing-function: ease-out !important;
  animation-fill-mode: both !important;
}
@keyframes gloriaRestoreFxFadeV410 {
  0% { opacity: 0; }
  7% { opacity: 1; }
  84% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes gloriaGroundGlowV410 {
  0% { opacity: 0; transform: scaleX(.18) scaleY(.08); }
  28% { opacity: .94; transform: scaleX(.88) scaleY(.34); }
  78% { opacity: .58; transform: scaleX(1.02) scaleY(.42); }
  100% { opacity: 0; transform: scaleX(1.12) scaleY(.50); }
}
@keyframes gloriaRayTravelV410 {
  0% {
    opacity: 0;
    transform: translate(var(--gloria-ray-drift, 0%), 26%) rotate(var(--gloria-ray-tilt, 0deg)) scaleX(.42) scaleY(.16);
    filter: blur(1.8px);
  }
  16% {
    opacity: .88;
    filter: blur(.35px);
  }
  58% {
    opacity: 1;
    transform: translate(calc(var(--gloria-ray-drift, 0%) * .35), -16%) rotate(var(--gloria-ray-tilt, 0deg)) scaleX(.92) scaleY(.94);
    filter: blur(0);
  }
  100% {
    opacity: 0;
    transform: translate(calc(var(--gloria-ray-drift, 0%) * -0.45), -92%) rotate(var(--gloria-ray-tilt, 0deg)) scaleX(.64) scaleY(1.18);
    filter: blur(1.15px);
  }
}
@keyframes gloriaSparkTravelV410 {
  0% { opacity: 0; transform: translate(0, 8px) scale(.22); }
  20% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--gloria-spark-drift, 0px), -44px) scale(1.12); }
}

.healing-factor-cell-fx-v410 {
  animation: healingCellFxFadeV410 2.42s ease-out both;
}
.healing-factor-cell-fx-v410 .healing-cell-glow {
  animation: healingCellGlowV410 1.55s ease-out both;
}
.healing-cross-v410 {
  opacity: 0;
  filter: drop-shadow(0 0 7px var(--healing-primary)) drop-shadow(0 0 13px color-mix(in srgb, var(--healing-primary) 72%, transparent 28%));
  animation-name: healingCrossRiseV410 !important;
  animation-duration: var(--healing-cross-duration, 1100ms) !important;
  animation-delay: var(--healing-cross-delay, 0ms) !important;
  animation-timing-function: cubic-bezier(.16,.78,.18,1) !important;
  animation-fill-mode: both !important;
}
.healing-cross-v410.healing-cross-secondary::before,
.healing-cross-v410.healing-cross-secondary::after {
