}
.healing-particle-v410 {
  opacity: 0;
  animation-name: healingParticleFloatV410 !important;
  animation-duration: var(--healing-particle-duration, 1020ms) !important;
  animation-delay: var(--healing-particle-delay, 0ms) !important;
  animation-timing-function: ease-out !important;
  animation-fill-mode: both !important;
}
@keyframes healingCellFxFadeV410 {
  0% { opacity: 0; }
  6% { opacity: 1; }
  86% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes healingCellGlowV410 {
  0% { opacity: 0; transform: scale(.28); }
  28% { opacity: .92; transform: scale(.94); }
  76% { opacity: .52; transform: scale(1.08); }
  100% { opacity: 0; transform: scale(1.20); }
}
@keyframes healingCrossRiseV410 {
  0% {
    opacity: 0;
    transform: translateY(12px) rotate(var(--healing-cross-rotate, 0deg)) scale(.38);
    filter: blur(1.2px) drop-shadow(0 0 3px var(--healing-primary));
  }
  18% {
