  }
  62% {
    opacity: 1;
    transform: translateY(calc(var(--healing-cross-rise, 34px) * -.58)) rotate(var(--healing-cross-rotate, 0deg)) scale(1.04);
  }
  100% {
    opacity: 0;
    transform: translateY(calc(var(--healing-cross-rise, 34px) * -1)) rotate(var(--healing-cross-rotate, 0deg)) scale(.80);
    filter: blur(.8px) drop-shadow(0 0 5px var(--healing-primary));
  }
}
@keyframes healingParticleFloatV410 {
  0% { opacity: 0; transform: translate(0, 8px) scale(.22); }
  20% { opacity: 1; }
  72% { opacity: .82; }
  100% { opacity: 0; transform: translate(var(--healing-particle-drift, 0px), calc(var(--healing-particle-rise, 38px) * -1)) scale(1.08); }
}

