/* =========================================================
   v412 · 天灯籠 / Tentōrō · Lámparas Celestiales
   ========================================================= */
.celestial-lamp-layer {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  overflow: visible;
}

.celestial-lamp-field {
  position: absolute;
  transform: translate(-50%, -50%);
  pointer-events: none;
  overflow: visible;
  isolation: isolate;
  filter: drop-shadow(0 0 9px rgba(255, 218, 79, .68));
}

.celestial-lamp-halo {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 300%;
  height: 300%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid rgba(255, 244, 177, .44);
