@keyframes tentorouLampRise {
  0% {
    opacity: 0;
    transform: translate(-50%, 62%) scale(.72, .28);
    filter: brightness(4.8) saturate(3.2) sepia(1) drop-shadow(0 0 20px #ffe35d);
  }
  24% {
    opacity: 1;
  }
  64% {
    transform: translate(-50%, -5%) scale(1.02, 1.04);
