body.rok-card-creator-mode .library-builder-summary-hud > #libraryBuilderDeckSummary {
  display: none !important;
}
body.rok-card-creator-mode .library-builder-summary-hud > #cardCreatorTopHud {
  display: grid !important;
}


/* v469 · Arrastrar cartas desde el Spellbook hacia la arena. */
body.rok-battle-mode .card-grid .card-slot:not(.empty) .spellbook-draggable-card {
  cursor: grab;
  -webkit-user-drag: element;
  user-select: none;
}

body.rok-battle-mode .card-grid .card-slot.spellbook-drag-source .spellbook-draggable-card {
  cursor: grabbing;
  opacity: 0.62;
  filter: brightness(1.08);
}

body.rok-battle-mode .board-content.spellbook-card-drop-ready {
  outline: 3px solid rgba(243, 213, 126, 0.92);
  outline-offset: -3px;
  box-shadow: inset 0 0 34px rgba(243, 213, 126, 0.15);
}


/* ========================================================================== 
   R.O.K Lite v470 · Etapa 1 · Biblioteca: miniaturas sin marco invasivo
   El marco exterior de la casilla ya no reduce el área útil de la carta ni
   de la banda de costo. Se limita únicamente a las cartas del catálogo.
   ========================================================================== */
.library-builder-card-tile[data-origin="library"] {
  box-sizing: border-box !important;
  border: 0 !important;
  border-radius: 7px !important;
  background: transparent !important;
  box-shadow: 0 6px 16px rgba(0,0,0,.30) !important;
  overflow: hidden !important;
}

.library-builder-card-tile[data-origin="library"] .card {
  left: 0 !important;
  right: 0 !important;
  top: 0 !important;
  bottom: 0 !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  border-radius: 7px !important;
}

.library-builder-card-tile[data-origin="library"] .library-builder-quick-layer {
  left: 4px !important;
  right: 4px !important;
  top: 4px !important;
  bottom: 4px !important;
}

.library-builder-card-tile[data-origin="library"] .library-builder-quick-cost {
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  max-width: 100% !important;
}

.library-builder-card-tile[data-origin="library"]:hover,
.library-builder-card-tile[data-origin="library"]:focus-visible {
  outline: 1px solid rgba(255,238,194,.58) !important;
  outline-offset: -1px !important;
  box-shadow: 0 8px 18px rgba(0,0,0,.45), 0 0 14px rgba(194,116,255,.22) !important;
}

.library-builder-card-tile[data-origin="library"].selected {
  outline: 2px solid rgba(255,242,178,.92) !important;
  outline-offset: -2px !important;
  box-shadow: 0 0 0 2px rgba(255,224,116,.20), 0 0 22px rgba(255,206,98,.25) !important;
}

/* ========================================================================== 
   R.O.K Lite v474 · Etapa 5 · Responsive de combate, HUD y modales
   ALCANCE: solo body.rok-battle-mode. No modifica Biblioteca/Creador.
   Objetivo: eliminar dependencias de una resolución exacta, mantener la arena
   dentro del viewport y hacer que los modales reduzcan/scrollen sin solaparse.
   ========================================================================== */

body.rok-battle-mode {
  --rok-battle-gap: clamp(4px, .45cqw, 8px);
  --rok-battle-pad: clamp(4px, .55cqw, 8px);
  --rok-left-rail-w: clamp(76px, 7.3cqw, 112px);
  --rok-phase-rail-w: clamp(92px, 8.4cqw, 128px);
  --rok-cast-rail-w: clamp(82px, 7.5cqw, 118px);
  --rok-spellbook-w: clamp(300px, min(29cqw, calc(74cqh - 133px)), 440px);
  --rok-kaster-responsive-h: clamp(88px, 13.5cqh, 110px);

  /* Ventanas de acción ancladas a porcentajes de la arena; se eliminan los
     desplazamientos fijos de +168 / -300 px que se descuadraban al redimensionar. */
  --ally-action-window-anchored-left: 24%;
  --ally-action-window-anchored-top: 73%;
  --ally-action-window-anchored-x: 0px;
  --ally-action-window-anchored-y: 0px;
  --ally-action-window-anchored-scale: .9;
  --ally-action-window-anchored-w: clamp(132px, 11.5cqw, 170px);
  --ally-action-window-overlay-left: 24%;
  --ally-action-window-overlay-top: 73%;
  --ally-action-window-overlay-x: 0px;
  --ally-action-window-overlay-y: 0px;
  --ally-action-window-overlay-scale: .9;
  --ally-action-window-overlay-w: clamp(132px, 11.5cqw, 170px);

  --rival-action-window-anchored-left: 76%;
  --rival-action-window-anchored-top: 18%;
  --rival-action-window-anchored-x: 0px;
  --rival-action-window-anchored-y: 0px;
  --rival-action-window-anchored-scale: .8;
  --rival-action-window-anchored-w: clamp(128px, 11cqw, 170px);
  --rival-action-window-overlay-left: 76%;
  --rival-action-window-overlay-top: 18%;
  --rival-action-window-overlay-x: 0px;
  --rival-action-window-overlay-y: 0px;
  --rival-action-window-overlay-scale: .8;
  --rival-action-window-overlay-w: clamp(128px, 11cqw, 170px);

  --quick-reaction-modal-card-size: clamp(72px, 7.2cqw, 92px);
  --quick-reaction-modal-shell-width: min(360px, calc(100% - 24px));
  --quick-reaction-modal-shell-max-height: min(62%, calc(100% - 24px));
  --quick-reaction-modal-gap: clamp(6px, .8cqw, 12px);
  --opponent-action-notice-shell-width: min(330px, calc(100% - 24px));
  --opponent-action-notice-scale: 1;

  /* Miniaturas persistentes ligadas al tamaño real del viewport. */
  --selected-unit-command-thumb-size: clamp(62px, 6.1cqw, 80px);
  --persistent-unit-command-thumb-size: clamp(62px, 6.1cqw, 80px);
  --persistent-unit-command-stack-bottom: clamp(76px, 9.5cqh, 96px);

  /* Spellbook en partida: evita que teclas/costo ocupen demasiado en slots chicos. */
  --game-spellbook-key-size: clamp(16px, 1.5cqw, 22px);
  --game-spellbook-key-font-size: clamp(9px, .85cqw, 12px);
  --game-spellbook-element-bar-height: clamp(14px, 1.45cqw, 18px);
  --game-spellbook-element-dot-size: clamp(10px, 1cqw, 13px);
  --game-spellbook-element-pack-icon-size: clamp(10px, 1cqw, 13px);
  --game-spellbook-element-pack-font-size: clamp(7px, .72cqw, 9px);
}

body.rok-battle-mode .game-shell {
  width: 100cqw !important;
  height: 100cqh !important;
  height: 100cqh !important;
  box-sizing: border-box !important;
  gap: var(--rok-battle-gap) !important;
  padding: var(--rok-battle-pad) !important;
  grid-template-columns:
    var(--rok-left-rail-w)
    minmax(0, 1fr)
    var(--rok-phase-rail-w)
    var(--rok-cast-rail-w)
    var(--rok-spellbook-w) !important;
  grid-template-rows: minmax(0, 1fr) var(--rok-kaster-responsive-h) !important;
  overflow: hidden !important;
}

body.rok-battle-mode .left-panel,
body.rok-battle-mode .board-panel,
body.rok-battle-mode .phase-rail,
body.rok-battle-mode .cast-panel,
body.rok-battle-mode .right-panel,
body.rok-battle-mode .caster-wide-panel {
  box-sizing: border-box !important;
  min-width: 0 !important;
  min-height: 0 !important;
}

/* La arena se dimensiona por el menor límite real: ancho de su columna o alto
   del viewport. Nunca necesita salirse del panel para conservar 2:3. */
body.rok-battle-mode .board-panel {
  overflow: hidden !important;
  align-items: center !important;
  justify-content: center !important;
}
body.rok-battle-mode .board {
  width: min(100%, calc(66.6667cqh - 12px)) !important;
  height: auto !important;
  max-width: 100% !important;
  max-height: 100% !important;
  aspect-ratio: var(--board-aspect) !important;
  flex: 0 1 auto !important;
}

/* Barras laterales: el contenido se comprime antes de invadir otra columna. */
body.rok-battle-mode .left-panel { padding: clamp(4px, .55cqw, 8px) !important; }
body.rok-battle-mode .resource-bar,
body.rok-battle-mode .vertical-resource-bar {
  gap: clamp(5px, .75cqh, 10px) !important;
  padding-top: clamp(18px, 3cqh, 28px) !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
}
body.rok-battle-mode .orb {
  width: clamp(34px, 3.6cqw, 48px) !important;
  height: clamp(34px, 3.6cqw, 48px) !important;
}

body.rok-battle-mode .phase-rail {
  padding: clamp(4px, .6cqw, 8px) !important;
  gap: clamp(4px, .7cqh, 8px) !important;
  overflow: hidden !important;
}
body.rok-battle-mode .phase-boxes,
body.rok-battle-mode .phase-boxes-vertical { gap: clamp(3px, .6cqh, 6px) !important; }
body.rok-battle-mode .phase-box {
  min-height: clamp(38px, 6.6cqh, 54px) !important;
  padding: clamp(4px, .65cqh, 7px) 4px !important;
  font-size: clamp(9px, .8cqw, 12px) !important;
}
body.rok-battle-mode .next-phase-vertical {
  height: clamp(42px, 7cqh, 56px) !important;
  min-height: 0 !important;
  font-size: clamp(9px, .75cqw, 11px) !important;
}
body.rok-battle-mode .phase-rail-bottom-controls {
  min-width: 0 !important;
  overflow: hidden !important;
}
body.rok-battle-mode .phase-rail-bottom-controls .main-button {
  min-width: 0 !important;
  width: 100% !important;
  padding-left: 4px !important;
  padding-right: 4px !important;
  font-size: clamp(8px, .7cqw, 10px) !important;
  white-space: normal !important;
}

body.rok-battle-mode .cast-panel {
  padding: clamp(4px, .55cqw, 8px) !important;
  gap: clamp(4px, .7cqh, 10px) !important;
  overflow: hidden !important;
}
body.rok-battle-mode .cast-panel h3 {
  font-size: clamp(9px, .9cqw, 13px) !important;
  line-height: 1.05 !important;
}
body.rok-battle-mode .cast-queue {
  width: 100% !important;
  min-height: 0 !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
}
body.rok-battle-mode .cast-item {
  width: clamp(54px, 5.2cqw, 76px) !important;
  height: clamp(70px, 6.8cqw, 96px) !important;
}
body.rok-battle-mode .cast-item img {
  width: clamp(52px, 5.05cqw, 74px) !important;
  height: clamp(66px, 6.35cqw, 88px) !important;
}

/* Spellbook: el ancho de la columna se limita también por la altura disponible,
   por lo que 4 filas no se pisan al usar una ventana más baja. */
body.rok-battle-mode .right-panel {
  padding: clamp(5px, .7cqw, 10px) !important;
  gap: clamp(4px, .65cqh, 10px) !important;
  grid-template-rows: clamp(28px, 4.5cqh, 36px) minmax(0, 1fr) !important;
  overflow: hidden !important;
}
body.rok-battle-mode .tab-stack { min-width: 0 !important; gap: clamp(2px, .3cqw, 4px) !important; }
body.rok-battle-mode .deck-tab {
  min-width: 0 !important;
  height: 100% !important;
  font-size: clamp(8px, .72cqw, 11px) !important;
  padding: 0 3px !important;
}
body.rok-battle-mode .card-grid {
  min-width: 0 !important;
  min-height: 0 !important;
  gap: clamp(4px, .55cqw, 8px) !important;
  overflow: hidden !important;
}
body.rok-battle-mode .card-slot { min-width: 0 !important; max-width: 100% !important; }

/* Panel inferior del Kaster: mantiene una sola fila de estadísticas y reduce
   tipografía/espacios de forma fluida sin salirse de su track. */
body.rok-battle-mode .caster-wide-panel {
  min-height: var(--rok-kaster-responsive-h) !important;
  max-height: var(--rok-kaster-responsive-h) !important;
  height: var(--rok-kaster-responsive-h) !important;
  grid-template-columns: clamp(68px, 6.2cqw, 88px) minmax(0, 1fr) !important;
  gap: clamp(6px, .7cqw, 10px) !important;
  padding: clamp(5px, .6cqw, 7px) clamp(7px, .8cqw, 10px) !important;
  overflow: hidden !important;
}
body.rok-battle-mode .caster-wide-card {
  height: min(92px, calc(var(--rok-kaster-responsive-h) - 14px)) !important;
  width: auto !important;
  max-width: min(92px, calc(var(--rok-kaster-responsive-h) - 14px)) !important;
  max-height: min(92px, calc(var(--rok-kaster-responsive-h) - 14px)) !important;
}
body.rok-battle-mode .caster-wide-info { min-width: 0 !important; overflow: hidden !important; }
body.rok-battle-mode .caster-wide-title h2 {
  font-size: clamp(13px, 1.25cqw, 18px) !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}
body.rok-battle-mode .caster-wide-title .tag { font-size: clamp(8px, .7cqw, 10px) !important; }
body.rok-battle-mode .caster-wide-domain { margin-top: 2px !important; gap: 5px !important; }
body.rok-battle-mode .caster-domain-chip {
  min-height: clamp(28px, 4cqh, 42px) !important;
  padding: 3px 8px 3px 5px !important;
}
body.rok-battle-mode .caster-domain-chip-icons { width: 44px !important; height: 23px !important; }
body.rok-battle-mode .caster-domain-icon { width: 23px !important; height: 23px !important; }
body.rok-battle-mode .caster-domain-chip-text { font-size: clamp(9px, .75cqw, 12px) !important; }
body.rok-battle-mode .caster-wide-stats {
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
  gap: clamp(3px, .4cqw, 5px) !important;
  min-width: 0 !important;
}
body.rok-battle-mode .caster-wide-stats .stats-line {
  min-width: 0 !important;
  padding: 3px 4px !important;
}
body.rok-battle-mode .caster-wide-stats .stats-line span {
  font-size: clamp(7px, .6cqw, 9px) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
body.rok-battle-mode .caster-wide-stats .stats-line strong { font-size: clamp(8px, .7cqw, 10px) !important; }

/* --------------------------------------------------------------------------
   Modal principal de carta EN PARTIDA. Mantiene su composición, pero la caja
   completa ahora es un viewport interno: si el alto no alcanza, hace scroll;
   nunca puede empujar acciones/filas fuera de la pantalla.
   -------------------------------------------------------------------------- */
body.rok-battle-mode #cardInfoOverlay.card-info-overlay {
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 100% !important;
  max-height: 100% !important;
  padding: clamp(8px, 1.2cqw, 18px) !important;
  overflow: hidden !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-box {
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 100% !important;
  max-height: 100% !important;
  grid-template-rows: auto auto auto !important;
  gap: clamp(8px, 1.1cqh, 16px) !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  scrollbar-gutter: stable !important;
  padding-right: 2px !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-main {
  grid-template-columns: clamp(118px, 14cqw, 190px) minmax(0, 1fr) !important;
  gap: clamp(10px, 1.5cqw, 22px) !important;
  min-width: 0 !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-preview,
body.rok-battle-mode #cardInfoOverlay .card-info-stats {
  width: 100% !important;
  max-width: 190px !important;
  min-width: 0 !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-text { min-width: 0 !important; overflow: hidden !important; }
body.rok-battle-mode #cardInfoOverlay .card-info-text h2 {
  transform: none !important;
  font-size: clamp(18px, 2.15cqw, 32px) !important;
  line-height: 1.05 !important;
  overflow-wrap: anywhere !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-text p {
  font-size: clamp(9px, .9cqw, 13px) !important;
  letter-spacing: clamp(.8px, .15cqw, 2px) !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-meta-icons,
body.rok-battle-mode #cardInfoOverlay .card-info-summary-tags,
body.rok-battle-mode #cardInfoOverlay .card-info-traits,
body.rok-battle-mode #cardInfoOverlay .card-info-caster-compatibility {
  min-width: 0 !important;
  max-width: 100% !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-lower {
  min-width: 0 !important;
  max-width: 100% !important;
}
body.rok-battle-mode #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open) .card-info-lower {
  --card-info-uniform-row-height: clamp(46px, 7cqh, 58px) !important;
  --card-info-uniform-row-gap: clamp(5px, .8cqh, 8px) !important;
  grid-template-columns: minmax(0, 58%) minmax(150px, 1fr) !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-actions {
  min-width: 0 !important;
  gap: clamp(6px, .9cqw, 12px) !important;
}
body.rok-battle-mode #cardInfoOverlay .card-info-btn {
  min-width: 0 !important;
  height: clamp(42px, 6.5cqh, 52px) !important;
  font-size: clamp(10px, .85cqw, 13px) !important;
}

/* Modales secundarios: siempre dentro del viewport y con scroll interno. */
body.rok-battle-mode .patch-info-overlay,
body.rok-battle-mode .meta-info-overlay,
body.rok-battle-mode .random-cost-overlay,
body.rok-battle-mode .game-menu-overlay,
body.rok-battle-mode .power-image-preview-overlay {
  box-sizing: border-box !important;
  max-width: 100cqw !important;
  max-height: 100cqh !important;
  padding: clamp(8px, 1.5cqw, 18px) !important;
  overflow: hidden !important;
}
body.rok-battle-mode .patch-info-card,
body.rok-battle-mode .meta-info-box,
body.rok-battle-mode .random-cost-box,
body.rok-battle-mode .game-menu-card {
  box-sizing: border-box !important;
  width: min(var(--modal-natural-width, 760px), 100%) !important;
  max-width: 100% !important;
  max-height: calc(100cqh - 24px) !important;
  overflow: auto !important;
  overscroll-behavior: contain !important;
}
body.rok-battle-mode .patch-info-card { --modal-natural-width: 520px; }
body.rok-battle-mode .random-cost-box { --modal-natural-width: 520px; }
body.rok-battle-mode .game-menu-card { --modal-natural-width: 360px; }
body.rok-battle-mode .meta-info-overlay.meta-info-power-mode .meta-info-box {
  width: min(1220px, 100%) !important;
  max-height: calc(100cqh - 24px) !important;
  padding: clamp(14px, 2cqw, 34px) !important;
}
body.rok-battle-mode .meta-info-overlay.meta-info-power-mode .power-detail-hero {
  grid-template-columns: minmax(180px, 38%) minmax(0, 1fr) !important;
  gap: clamp(12px, 2cqw, 28px) !important;
}

/* Reacción rápida y aviso rival: se mantienen exactamente sobre la caja de la
   arena, pero sus contenidos ya no pueden desbordar esa caja. */
body.rok-battle-mode .quick-reaction-modal,
body.rok-battle-mode .opponent-action-notice {
  max-width: 100cqw !important;
  max-height: 100cqh !important;
  overflow: hidden !important;
}
body.rok-battle-mode .quick-reaction-modal-shell {
  max-width: calc(100% - 20px) !important;
  max-height: calc(100% - 20px) !important;
  overflow: hidden !important;
}
body.rok-battle-mode .quick-reaction-modal-list {
  max-width: 100% !important;
  max-height: calc(100% - 34px) !important;
  overflow-x: auto !important;
  overflow-y: auto !important;
  flex-wrap: nowrap !important;
  justify-content: flex-start !important;
  scrollbar-width: thin !important;
}
body.rok-battle-mode .opponent-action-notice-shell {
  box-sizing: border-box !important;
  max-width: calc(100% - 20px) !important;
  max-height: calc(100% - 20px) !important;
  overflow: auto !important;
  padding: clamp(10px, 1.4cqw, 18px) !important;
}

/* Transición cinematográfica: deja de depender de 760 px / 78 px fijos. */
body.rok-battle-mode .transition-card {
  min-width: min(760px, 82cqw) !important;
  max-width: 90cqw !important;
  padding: clamp(18px, 3cqw, 38px) clamp(28px, 5.5cqw, 80px) !important;
  font-size: clamp(34px, 5.5cqw, 78px) !important;
  letter-spacing: clamp(2px, .35cqw, 4px) !important;
}

/* Altura corta: prioriza arena y Spellbook y reduce piezas de HUD vertical. */
@container rok-app-stage  (max-height: 720px) {
  body.rok-battle-mode {
    --rok-kaster-responsive-h: clamp(80px, 13cqh, 96px);
    --rok-spellbook-w: clamp(280px, min(28cqw, calc(72cqh - 108px)), 390px);
  }
  body.rok-battle-mode .caster-domain-chip { display: none !important; }
  body.rok-battle-mode .caster-wide-info { gap: 2px !important; }
  body.rok-battle-mode .phase-box { min-height: clamp(34px, 6cqh, 44px) !important; }
  body.rok-battle-mode .next-phase-vertical { height: clamp(36px, 6.2cqh, 46px) !important; }
  body.rok-battle-mode .cast-item { width: 54px !important; height: 70px !important; }
  body.rok-battle-mode .cast-item img { width: 52px !important; height: 66px !important; }
  body.rok-battle-mode #cardInfoOverlay .card-info-box { gap: 7px !important; }
  body.rok-battle-mode #cardInfoOverlay:not(.spell-card-info):not(.guardian-info-open) .card-info-lower {
    --card-info-uniform-row-height: 44px !important;
    --card-info-uniform-row-gap: 5px !important;
  }
}

/* Ancho medio: conserva las cinco columnas, pero sin mínimos rígidos de 360/430. */
@container rok-app-stage  (max-width: 1280px) {
  body.rok-battle-mode {
