  align-self: center;
}

body.rok-spellbooks-mode .saved-spellbook-info {
  grid-area: info;
  align-self: stretch;
  min-width: 0;
  padding: 4px 0 0 2px;
  display: flex;
  flex-direction: column;
}

body.rok-spellbooks-mode .saved-spellbook-info h2 {
  margin-bottom: 6px;
}

body.rok-spellbooks-mode .saved-spellbook-element-distribution {
  margin-top: 7px;
}

body.rok-spellbooks-mode .saved-spellbook-focus {
  margin-top: 7px;
  padding-top: 0;
}

body.rok-spellbooks-mode .saved-spellbook-actions {
  grid-area: actions;
  width: 100%;
  align-self: end;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
  padding: 2px 0 0 2px;
  box-sizing: border-box;
}

body.rok-spellbooks-mode .saved-spellbook-action {
  min-height: 28px;
  padding: 5px 7px;
