/* ========================================================================== 
   R.O.K Lite v478 · Sistema de amigos
   ========================================================================== */
.main-menu-profile-action-btn {
  width: 100%;
  min-height: 38px;
  margin-bottom: 6px;
  padding: 8px 11px;
  border: 1px solid rgba(160,126,229,.38);
  border-radius: 9px;
  background: linear-gradient(180deg,rgba(49,35,78,.96),rgba(17,12,30,.98));
  color: #f1e9ff;
  font: 900 10px/1 system-ui,sans-serif;
  letter-spacing: .06em;
  text-transform: uppercase;
  cursor: pointer;
}
.main-menu-profile-action-btn:hover,
.main-menu-profile-action-btn:focus-visible {
  border-color: rgba(207,178,255,.72);
  box-shadow: 0 0 14px rgba(139,84,219,.18), inset 0 0 11px rgba(255,255,255,.04);
}

.friends-overlay {
  position: fixed;
  inset: 0;
  z-index: 15050;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(12px, 3cqw, 38px);
  background: rgba(2,2,7,.82);
