}
.friends-overlay.visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.friends-card {
  position: relative;
  width: min(900px, 96cqw);
  max-height: min(820px, 92cqh);
  overflow: auto;
  padding: clamp(18px, 2.6cqw, 30px);
  border: 1px solid rgba(180,127,235,.42);
  border-radius: 22px;
  background:
    radial-gradient(circle at 22% 0%, rgba(105,50,142,.22), transparent 38%),
    linear-gradient(180deg,rgba(18,13,29,.985),rgba(5,4,10,.992));
  box-shadow: 0 28px 80px rgba(0,0,0,.72), inset 0 0 34px rgba(255,255,255,.025);
  color: #f4eef9;
}
.friends-close {
  position: absolute;
  right: 14px;
  top: 12px;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 50%;
  background: rgba(7,5,12,.82);
  color: #eee6f3;
  font: 700 23px/1 Georgia,serif;
  cursor: pointer;
}
.friends-kicker {
  display: block;
  margin-bottom: 4px;
  color: #caa8ef;
  font: 900 10px/1 system-ui,sans-serif;
  letter-spacing: .2em;
}
.friends-card h2 {
  margin: 0;
  color: #fff1c7;
  font: 700 clamp(25px,3cqw,36px)/1 Georgia,serif;
}
.friends-copy {
  max-width: 720px;
  margin: 8px 0 18px;
  color: #bdb4c8;
  font: 600 12px/1.45 system-ui,sans-serif;
}
.friends-profile-panel {
  display: grid;
  grid-template-columns: minmax(0,1fr) minmax(245px,.6fr);
  gap: 12px;
  margin-bottom: 12px;
}
.friends-profile-name,
.friends-code-box,
.friends-add-panel,
.friends-list-panel {
