  font: 900 11px/1 system-ui,sans-serif;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.friends-section-heading span {
  min-width: 25px;
  padding: 4px 7px;
  border: 1px solid rgba(190,153,224,.24);
