/* ========================================================================== 
   R.O.K Lite v505 · Minokage coherencia visual / trail / slash
   ========================================================================== */
/* La sombra ahora es hija del board y comparte el mismo sistema de coordenadas
   del token animado. Esto evita el doble escalado del stage que la desplazaba. */
.minokage-passive-afterimage-fx {
  position: absolute !important;
  transform: translate(-50%, -50%) scale(.98) !important;
  transform-origin: 50% 50% !important;
  z-index: 470 !important;
}
.minokage-passive-afterimage-fx.is-visible {
  transform: translate(-50%, -50%) scale(1.03) !important;
}
.minokage-passive-afterimage-fx.is-older {
  transform: translate(-50%, -50%) scale(1.01) !important;
}

/* El impacto negro/blanco en X queda retirado por completo. */
.minokage-impact-slash-fx {
  display: none !important;
  content: none !important;
}

/* Nuevo impacto: 2–3 cortes del asset aportado, con rotaciones y tiempos
   escalonados sobre el objetivo real. */
.minokage-hit-slash-burst-fx {
  position: absolute;
  width: clamp(74px, 9.4%, 148px);
  aspect-ratio: 1 / 1;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 492;
  overflow: visible;
  filter: drop-shadow(0 0 4px rgba(255,255,255,.72)) drop-shadow(0 3px 4px rgba(0,0,0,.85));
}
.minokage-hit-slash-burst-fx > img {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: 0;
  transform-origin: 50% 50%;
  animation: minokageHitSlashAsset 430ms cubic-bezier(.12,.78,.18,1) var(--minokage-hit-delay, 0ms) forwards;
}
@keyframes minokageHitSlashAsset {
  0% {
    opacity: 0;
    transform: translate(calc(-50% + var(--minokage-hit-offset-x, 0px)), calc(-50% + var(--minokage-hit-offset-y, 0px))) rotate(var(--minokage-hit-angle, 0deg)) scale(.46);
    filter: blur(1.2px) brightness(1.45);
  }
  18% {
    opacity: .98;
    transform: translate(calc(-50% + var(--minokage-hit-offset-x, 0px)), calc(-50% + var(--minokage-hit-offset-y, 0px))) rotate(var(--minokage-hit-angle, 0deg)) scale(1.05);
    filter: blur(0) brightness(1.2);
  }
  58% {
    opacity: .88;
    transform: translate(calc(-50% + var(--minokage-hit-offset-x, 0px)), calc(-50% + var(--minokage-hit-offset-y, 0px))) rotate(var(--minokage-hit-angle, 0deg)) scale(1.0);
    filter: blur(0) brightness(1.05);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--minokage-hit-offset-x, 0px)), calc(-50% + var(--minokage-hit-offset-y, 0px))) rotate(var(--minokage-hit-angle, 0deg)) scale(1.18);
    filter: blur(.7px) brightness(.92);
  }
}

/* Salto de acercamiento/retirada: giro deliberadamente más lento; el windup
   conserva el giro rápido inmediatamente antes del impacto. */
.minokage-passive-travel-token-fx .minokage-yari-spin-passive-travel,
.minokage-passive-travel-token-fx .minokage-yari-spin-passive-return {
  --minokage-yari-spin-duration: .82s !important;
