  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  transform: none !important;
  margin: 0 !important;
}

/* Reloj/contador: vuelve a obedecer las coordenadas de calibración que ya
   existían arriba del CSS, en vez de recalcularse como % del slot reducido. */
body.rok-battle-mode .cast-panel .cast-item > .cast-status,
body.rok-battle-mode .cast-panel .cast-item.cast-active > .cast-status,
body.rok-battle-mode .cast-panel .cast-item.cast-waiting > .cast-status {
