  z-index: 42 !important;
}

/* ACTIVO/COLA conservan las coordenadas calibradas, pero pasan por encima de
   la miniatura. Esto evita que el token tape el rótulo al escalar el stage. */
body.rok-battle-mode .cast-panel .cast-item.cast-active::after,
body.rok-battle-mode .cast-panel .cast-item.cast-waiting::after {
  position: absolute !important;
  white-space: nowrap !important;
  z-index: 60 !important;
}

body.rok-battle-mode .cast-panel .cast-item.cast-active::after {
  left: 50% !important;
  bottom: var(--player-cast-active-label-bottom) !important;
  transform: translate(calc(-50% + var(--player-cast-active-label-x)), var(--player-cast-active-label-y)) scale(var(--player-cast-active-label-scale)) !important;
  transform-origin: center center !important;
  padding: var(--player-cast-active-label-pad-y) var(--player-cast-active-label-pad-x) !important;
  font-size: var(--player-cast-active-label-font-size) !important;
}

body.rok-battle-mode .cast-panel .cast-item.cast-waiting::after {
  left: 50% !important;
  bottom: var(--player-cast-waiting-label-bottom) !important;
  transform: translate(calc(-50% + var(--player-cast-waiting-label-x)), var(--player-cast-waiting-label-y)) scale(var(--player-cast-waiting-label-scale)) !important;
  transform-origin: center center !important;
  padding: var(--player-cast-waiting-label-pad-y) var(--player-cast-waiting-label-pad-x) !important;
  font-size: var(--player-cast-waiting-label-font-size) !important;
}

body.rok-battle-mode .cast-panel .small-note {
  flex: 0 0 auto !important;
  overflow: visible !important;
}


/* v545 · Área de Agua: el mapa usa un lienzo ampliado y se desplaza hacia el
   encuentro seleccionado. Esta regla debe quedar DESPUÉS de las reglas
   genéricas .adventure-map-canvas > .adventure-map-image. */
.adventure-water-map-canvas > .adventure-map-image {
  inset: auto !important;
  right: auto !important;
  bottom: auto !important;
  left: var(--water-map-offset-x, 0%) !important;
  top: var(--water-map-offset-y, 0%) !important;
  width: calc(100% * var(--water-map-zoom, 1)) !important;
  height: calc(100% * var(--water-map-zoom, 1)) !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: fill;
  object-position: center;
  transition:
    left .48s cubic-bezier(.2,.78,.18,1),
    top .48s cubic-bezier(.2,.78,.18,1),
    width .48s cubic-bezier(.2,.78,.18,1),
    height .48s cubic-bezier(.2,.78,.18,1);
  will-change: left, top, width, height;
}

.adventure-water-map-canvas .adventure-water-marker {
  transition:
    left .48s cubic-bezier(.2,.78,.18,1),
    top .48s cubic-bezier(.2,.78,.18,1),
    filter .2s ease;
}

/* ========================================================================== 
   R.O.K Lite v547 · Aventura: preparación VS, identidad del Kaster y flujo
   de combate. Mantener después de las reglas v545 para que prevalezcan.
