/* El mapa de Agua llena por completo su recuadro. El JS calcula un cover
   conservando la relación natural 916/1717 y desplaza la imagen al marcador. */
.adventure-water-map-frame {
  place-items: stretch !important;
}

.adventure-water-map-canvas {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  aspect-ratio: auto !important;
  overflow: hidden;
}

.adventure-water-map-canvas > .adventure-map-image {
  inset: auto !important;
  left: var(--water-map-left, 0px) !important;
  top: var(--water-map-top, 0px) !important;
  width: var(--water-map-width, 100%) !important;
  height: var(--water-map-height, 100%) !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: fill !important;
  object-position: center !important;
  transition:
    left .48s cubic-bezier(.2,.78,.18,1),
    top .48s cubic-bezier(.2,.78,.18,1),
    width .48s cubic-bezier(.2,.78,.18,1),
    height .48s cubic-bezier(.2,.78,.18,1) !important;
