/* ----------------------- Presentación cinematográfica -------------------- */
.adventure-battle-intro {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: none;
  overflow: hidden;
  background: #020408;
  color: white;
}

.adventure-battle-intro[aria-hidden="false"] {
  display: block;
}

.adventure-intro-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 46%, rgba(255,219,144,.14), transparent 18%),
    linear-gradient(90deg, rgba(4,12,20,.96) 0%, rgba(5,10,18,.92) 45%, rgba(9,8,14,.92) 55%, rgba(18,12,8,.96) 100%);
}

.adventure-intro-bg::before,
.adventure-intro-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.adventure-intro-bg::before {
  background:
    radial-gradient(circle at 50% 48%, rgba(255,228,168,.15), transparent 11%),
    radial-gradient(circle at 50% 48%, rgba(255,228,168,.06), transparent 22%),
    linear-gradient(180deg, rgba(255,255,255,.02), transparent 26%, transparent 74%, rgba(255,255,255,.02));
}

.adventure-intro-bg::after {
  left: calc(50% - 6px);
  width: 12px;
  background: linear-gradient(180deg, transparent 0%, rgba(255,239,193,.9) 20%, rgba(255,239,193,.35) 50%, rgba(255,239,193,.9) 80%, transparent 100%);
  clip-path: polygon(48% 0%, 100% 6%, 55% 14%, 100% 24%, 46% 32%, 92% 42%, 38% 50%, 92% 60%, 40% 68%, 96% 78%, 48% 86%, 100% 94%, 52% 100%, 0% 94%, 46% 86%, 4% 78%, 58% 68%, 8% 60%, 62% 50%, 8% 42%, 54% 32%, 0% 24%, 44% 14%, 0% 6%);
  opacity: 0;
}

.adventure-battle-intro.active .adventure-intro-bg::after {
  animation: introSplitFlash .45s ease 1.02s forwards;
}

@keyframes introSplitFlash {
  0% { opacity: 0; transform: scaleY(.1); filter: blur(10px); }
  60% { opacity: .95; transform: scaleY(1.08); filter: blur(0); }
  100% { opacity: .52; transform: scaleY(1); filter: blur(0); }
}

.adventure-intro-side {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
  overflow: hidden;
}

.adventure-intro-rival { left: 0; }
.adventure-intro-player { right: 0; }

.adventure-intro-side::before,
.adventure-intro-side::after {
  content: '';
  position: absolute;
  inset: -8% -8%;
  pointer-events: none;
}

.adventure-intro-side::before {
  z-index: 1;
  opacity: 0;
  mix-blend-mode: screen;
}

.adventure-intro-side::after {
  z-index: 2;
  opacity: 0;
  filter: blur(.25px);
}

.adventure-intro-rival::before {
  background:
    linear-gradient(90deg, transparent 0%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 90%, transparent) 26%, transparent 46%) 0 18%/360px 8px no-repeat,
    linear-gradient(90deg, transparent 0%, color-mix(in srgb, var(--intro-color-2, #d8b85f) 88%, transparent) 24%, transparent 50%) 0 32%/280px 6px no-repeat,
    linear-gradient(90deg, transparent 0%, color-mix(in srgb, var(--intro-color-3, #7a66f4) 88%, transparent) 30%, transparent 56%) 0 46%/430px 10px no-repeat,
    linear-gradient(90deg, transparent 0%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 84%, transparent) 22%, transparent 52%) 0 59%/250px 5px no-repeat,
    linear-gradient(90deg, transparent 0%, color-mix(in srgb, var(--intro-color-2, #d8b85f) 84%, transparent) 28%, transparent 54%) 0 72%/380px 9px no-repeat,
    radial-gradient(circle at 18% 50%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 20%, transparent) 0, transparent 26%);
}

.adventure-intro-player::before {
  background:
    linear-gradient(270deg, transparent 0%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 90%, transparent) 26%, transparent 46%) 100% 18%/360px 8px no-repeat,
    linear-gradient(270deg, transparent 0%, color-mix(in srgb, var(--intro-color-2, #d8b85f) 88%, transparent) 24%, transparent 50%) 100% 32%/280px 6px no-repeat,
    linear-gradient(270deg, transparent 0%, color-mix(in srgb, var(--intro-color-3, #7a66f4) 88%, transparent) 30%, transparent 56%) 100% 46%/430px 10px no-repeat,
    linear-gradient(270deg, transparent 0%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 84%, transparent) 22%, transparent 52%) 100% 59%/250px 5px no-repeat,
    linear-gradient(270deg, transparent 0%, color-mix(in srgb, var(--intro-color-2, #d8b85f) 84%, transparent) 28%, transparent 54%) 100% 72%/380px 9px no-repeat,
    radial-gradient(circle at 82% 50%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 20%, transparent) 0, transparent 26%);
}

.adventure-intro-rival::after {
  background:
    radial-gradient(circle, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 100%, transparent) 0 1.7px, transparent 2.2px) 8% 22%/180px 90px repeat,
    radial-gradient(circle, color-mix(in srgb, var(--intro-color-2, #d8b85f) 100%, transparent) 0 1.5px, transparent 2px) 18% 36%/210px 110px repeat,
    radial-gradient(circle, color-mix(in srgb, var(--intro-color-3, #7a66f4) 100%, transparent) 0 1.4px, transparent 1.9px) 4% 56%/165px 88px repeat,
    radial-gradient(circle, rgba(255,255,255,.8) 0 1.2px, transparent 1.8px) 20% 70%/250px 120px repeat;
}

.adventure-intro-player::after {
  background:
    radial-gradient(circle, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 100%, transparent) 0 1.7px, transparent 2.2px) 92% 22%/180px 90px repeat,
    radial-gradient(circle, color-mix(in srgb, var(--intro-color-2, #d8b85f) 100%, transparent) 0 1.5px, transparent 2px) 82% 36%/210px 110px repeat,
    radial-gradient(circle, color-mix(in srgb, var(--intro-color-3, #7a66f4) 100%, transparent) 0 1.4px, transparent 1.9px) 96% 56%/165px 88px repeat,
    radial-gradient(circle, rgba(255,255,255,.8) 0 1.2px, transparent 1.8px) 80% 70%/250px 120px repeat;
}

.adventure-battle-intro.active .adventure-intro-rival::before {
  animation: introStreamsLeft .95s ease .08s both, introStreamsLeftLoop 1.5s linear .95s infinite;
}

.adventure-battle-intro.active .adventure-intro-player::before {
  animation: introStreamsRight .95s ease 1.14s both, introStreamsRightLoop 1.5s linear 2.02s infinite;
}

.adventure-battle-intro.active .adventure-intro-rival::after {
  animation: introParticlesLeft .75s ease .2s both, introParticlesDriftLeft 4s linear .95s infinite;
}

.adventure-battle-intro.active .adventure-intro-player::after {
  animation: introParticlesRight .75s ease 1.3s both, introParticlesDriftRight 4s linear 2.05s infinite;
}

@keyframes introStreamsLeft {
  0% { opacity: 0; transform: translateX(-12%) scaleX(.88); }
  100% { opacity: 1; transform: translateX(0) scaleX(1); }
}
@keyframes introStreamsRight {
  0% { opacity: 0; transform: translateX(12%) scaleX(.88); }
  100% { opacity: 1; transform: translateX(0) scaleX(1); }
}
@keyframes introStreamsLeftLoop {
  0% { background-position: -160px 18%, -80px 32%, -220px 46%, -60px 59%, -180px 72%, 18% 50%; }
  100% { background-position: 160px 18%, 80px 32%, 220px 46%, 60px 59%, 180px 72%, 18% 50%; }
}
@keyframes introStreamsRightLoop {
  0% { background-position: calc(100% + 160px) 18%, calc(100% + 80px) 32%, calc(100% + 220px) 46%, calc(100% + 60px) 59%, calc(100% + 180px) 72%, 82% 50%; }
  100% { background-position: calc(100% - 160px) 18%, calc(100% - 80px) 32%, calc(100% - 220px) 46%, calc(100% - 60px) 59%, calc(100% - 180px) 72%, 82% 50%; }
}
@keyframes introParticlesLeft {
  0% { opacity: 0; transform: translateX(-14%) scale(1.06); }
  100% { opacity: .7; transform: translateX(0) scale(1); }
}
@keyframes introParticlesRight {
  0% { opacity: 0; transform: translateX(14%) scale(1.06); }
  100% { opacity: .7; transform: translateX(0) scale(1); }
}
@keyframes introParticlesDriftLeft {
  0% { transform: translateX(-2%); }
  100% { transform: translateX(8%); }
}
@keyframes introParticlesDriftRight {
  0% { transform: translateX(2%); }
  100% { transform: translateX(-8%); }
}

.adventure-intro-caster {
