  clip-path: polygon(50% 0%, 60% 16%, 77% 4%, 76% 25%, 96% 18%, 84% 40%, 100% 50%, 82% 60%, 94% 82%, 72% 74%, 70% 100%, 50% 84%, 30% 100%, 28% 74%, 6% 82%, 18% 60%, 0% 50%, 16% 40%, 4% 18%, 24% 25%, 23% 4%, 40% 16%);
