}

@keyframes introVsSplash {
  0% { opacity: 0; transform: scale(.18) rotate(-12deg); }
  75% { opacity: 1; transform: scale(1.08) rotate(3deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}
@keyframes introVsLetter {
  0% { opacity: 0; transform: translateY(18px) scale(1.8) rotate(-10deg); }
  70% { opacity: 1; transform: translateY(-2px) scale(.92) rotate(4deg); }
  100% { opacity: 1; transform: translateY(0) scale(1) rotate(0); }
}
@keyframes introVsSpark {
  0% { opacity: 0; transform: scale(.55); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes introVsPulse {
  0%,100% { filter: drop-shadow(0 14px 24px rgba(0,0,0,.55)); }
  50% { filter: drop-shadow(0 16px 26px rgba(0,0,0,.62)) drop-shadow(0 0 18px rgba(255,217,97,.34)); }
}
@keyframes introVsSparkPulse {
  0%,100% { transform: scale(1); opacity: .85; }
