/* =========================================================
   FIX FINAL: OPACIDAD A/B SEPARADA POR GRID
   Este bloque va al final para que los cuadros A y B sí respondan
   a sus valores de opacidad aunque haya reglas anteriores.
   ========================================================= */

.enemy-grid .cell:nth-child(odd) {
  background-color: rgba(var(--enemy-cell-fill-color-a), var(--enemy-cell-fill-opacity-a)) !important;
  background-image: none !important;
}

.enemy-grid .cell:nth-child(even) {
  background-color: rgba(var(--enemy-cell-fill-color-b), var(--enemy-cell-fill-opacity-b)) !important;
  background-image: none !important;
}

.ally-grid .cell:nth-child(odd) {
  background-color: rgba(var(--ally-cell-fill-color-a), var(--ally-cell-fill-opacity-a)) !important;
  background-image: none !important;
}

.ally-grid .cell:nth-child(even) {
  background-color: rgba(var(--ally-cell-fill-color-b), var(--ally-cell-fill-opacity-b)) !important;
  background-image: none !important;
}

/* =========================================================
   ROK PATCH: HUD VERTICAL, ARENA MÁS GRANDE Y RECURSOS LATERALES
   ========================================================= */

/* El layout ya no usa barra superior ni barra inferior.
   La arena ocupa toda la altura disponible. */
.game-shell {
  height: 100cqh;
  width: 100cqw;
  display: grid;
  grid-template-columns: 92px minmax(430px, 1fr) 96px 150px 440px;
  grid-template-rows: 1fr;
  gap: 8px;
  padding: 8px;
}

/* La barra superior y la barra inferior quedan anuladas por si quedaron en HTML viejo. */
.top-bar,
.bottom-bar {
  display: none !important;
}

/* Panel izquierdo: se limpia el texto informativo y se usa para elementos. */
.left-panel {
  grid-column: 1;
  grid-row: 1;
  position: relative;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
}

.player-block,
.hint-card {
  display: none !important;
}

.info-chip {
  position: absolute;
  top: 5px;
  left: 5px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, .28);
  background: rgba(0, 0, 0, .55);
  color: rgba(255, 255, 255, .72);
  font: 11px Arial, sans-serif;
  line-height: 1;
  padding: 0;
  cursor: default;
}

.hidden-player-readout {
  display: none;
}

.resource-title {
  margin-top: 24px;
  text-transform: uppercase;
  color: #bdb5c8;
  font-size: 11px;
  letter-spacing: 1px;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  opacity: .86;
}

.resource-bar,
.vertical-resource-bar {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  min-width: 0;
  width: 100%;
  overflow: auto;
  padding-top: 8px;
}

.orb {
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
}

.orb::after {
  content: none !important;
}

/* Arena central ampliada. */
.board-panel {
  grid-column: 2;
  grid-row: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  align-items: stretch;
  justify-content: center;
  overflow: hidden;
}

.board {
  position: relative;
  height: 100%;
  max-height: 100%;
  width: auto;
  aspect-ratio: var(--board-aspect);
  max-width: 100%;
  background: #050505;
  overflow: hidden;
  cursor: grab;
  touch-action: none;
}

/* Columna vertical de fases entre arena y casteo. */
.phase-rail {
  grid-column: 3;
  grid-row: 1;
  padding: 8px 6px;
  display: grid;
  grid-template-rows: auto auto minmax(26px, auto) 1fr;
  gap: 8px;
  min-width: 0;
}

.phase-boxes,
.phase-boxes-vertical {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.phase-box {
  min-height: 52px;
  height: auto;
  padding: 6px 4px;
  border: 1px solid #363642;
  background: #0b0b0d;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: .7px;
  color: #8e8790;
  font-size: 11px;
  line-height: 1.1;
  position: relative;
}

.next-phase-vertical {
  height: 54px;
  padding: 5px;
  font-size: 10px;
  line-height: 1.1;
  white-space: normal;
}

.turn-banner,
.turn-banner-vertical {
  text-align: center;
  font: 10px Arial, sans-serif;
  letter-spacing: .6px;
  text-transform: uppercase;
  color: #b9afc2;
  opacity: .9;
}

.system-log,
.system-log-vertical {
  font: 10px Arial, sans-serif;
  color: #d7cce5;
  background: #09090c;
  border: 1px solid #2d2d36;
  min-height: 42px;
  padding: 6px;
  overflow: hidden;
}

/* Zona de casteo permanece a la derecha de la columna de fases. */
.cast-panel {
  grid-column: 4;
  grid-row: 1;
  padding: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

/* Panel de cartas/caster a la derecha. */
.right-panel {
  grid-column: 5;
  grid-row: 1;
  padding: 10px;
  display: grid;
  grid-template-rows: 36px 1fr 182px;
  gap: 10px;
}

/* =========================================================
   FIX FINAL: OPACIDAD A/B SEPARADA POR GRID
   Este bloque va al final para que los cuadros A y B sí respondan
   a sus valores de opacidad aunque haya reglas anteriores.
   ========================================================= */

.enemy-grid .cell:nth-child(odd) {
  background-color: rgba(var(--enemy-cell-fill-color-a), var(--enemy-cell-fill-opacity-a)) !important;
  background-image: none !important;
}

.enemy-grid .cell:nth-child(even) {
  background-color: rgba(var(--enemy-cell-fill-color-b), var(--enemy-cell-fill-opacity-b)) !important;
  background-image: none !important;
}

.ally-grid .cell:nth-child(odd) {
  background-color: rgba(var(--ally-cell-fill-color-a), var(--ally-cell-fill-opacity-a)) !important;
  background-image: none !important;
}

.ally-grid .cell:nth-child(even) {
  background-color: rgba(var(--ally-cell-fill-color-b), var(--ally-cell-fill-opacity-b)) !important;
  background-image: none !important;
}

/* Responsive simple */
@container rok-app-stage  (max-width: 1200px) {
  .game-shell {
    grid-template-columns: 82px minmax(360px, 1fr) 86px 130px 360px;
  }

  .phase-box {
    font-size: 10px;
  }
}

/* =========================================================
   ROK PATCH: AJUSTE FINO LAYOUT VERTICAL
   - Fases más anchas
   - Zona de casteo más angosta
   - Sin textos informativos extra
   - Elementos sin título vertical
   ========================================================= */

/* Barra izquierda de elementos un poco más ancha.
   Columna de fases más ancha.
   Zona de casteo más angosta. */
.game-shell {
  grid-template-columns: 112px minmax(430px, 1fr) 128px 118px 440px !important;
}

/* El panel izquierdo queda solo para orbes/elementos. */
.left-panel {
  padding: 8px 6px !important;
  align-items: center !important;
}

.resource-title {
  display: none !important;
}

.resource-bar,
.vertical-resource-bar {
  padding-top: 28px !important;
  gap: 10px !important;
  overflow: auto !important;
}

/* Orbes un poco más visibles en la barra izquierda. */
.orb {
  width: 48px !important;
  height: 48px !important;
}

.orb::after {
  content: none !important;
}

/* Fases más legibles por ancho, sin texto auxiliar debajo. */
.phase-rail {
  grid-template-rows: auto auto auto !important;
  gap: 8px !important;
  padding: 8px !important;
}

.phase-box {
  min-height: 54px !important;
  font-size: 12px !important;
  letter-spacing: .8px !important;
  padding: 7px 5px !important;
}

.next-phase-vertical {
  height: 56px !important;
  font-size: 11px !important;
}

/* Quitar textos informativos de abajo de las fases. */
.turn-banner,
.turn-banner-vertical,
.system-log,
.system-log-vertical {
  display: none !important;
}

/* Zona de casteo más comprimida a lo ancho. */
.cast-panel {
  padding: 8px 6px !important;
}

.cast-panel h3 {
  font-size: 13px !important;
  text-align: center !important;
}

.cast-item {
  width: 82px !important;
  height: 116px !important;
}

.small-note {
  display: none !important;
}

/* Ajuste responsive del nuevo layout */
@container rok-app-stage  (max-width: 1200px) {
  .game-shell {
    grid-template-columns: 96px minmax(360px, 1fr) 112px 106px 360px !important;
  }
}

/* =========================================================
   ROK BETA v0.12: INTERACCIÓN DE ARENA
   - Click izquierdo queda libre para casillas y fichas.
   - Arrastre/pan solo con botón central del mouse.
   ========================================================= */

.board {
  cursor: default !important;
}

.board.is-panning {
  cursor: grabbing !important;
}

.grid-layer {
  pointer-events: auto !important;
}

.cell {
  cursor: pointer;
}

.cell.occupied {
  pointer-events: auto !important;
  cursor: pointer;
}

.units-layer {
  pointer-events: none;
}

.unit {
  pointer-events: auto;
  cursor: pointer;
}

.unit img {
  pointer-events: none;
}

/* =========================================================
   ROK BETA v0.13 CORREGIDA: PANEL WIDE DE INFO DEL KASTER
   Base revertida desde v0.12. Este cambio NO usa el panel raro
   de v0.13 anterior.
   ========================================================= */

/* La pantalla ahora tiene 2 filas:
   - fila 1: arena + contador de turno + casteo + pestañas
   - fila 2: panel ancho del Kaster, desde la izquierda del contador
             de turno hasta el borde derecho de la ventana */
.game-shell {
  grid-template-columns: 112px minmax(430px, 1fr) 128px 118px 440px !important;
  grid-template-rows: minmax(0, 1fr) 220px !important;
}

/* Paneles que deben usar toda la altura izquierda/arena. */
.left-panel {
  grid-column: 1 !important;
  grid-row: 1 / 3 !important;
}

.board-panel {
  grid-column: 2 !important;
  grid-row: 1 / 3 !important;
}

/* Contador de turno/fases. El botón queda justo después de Espera. */
.phase-rail {
  grid-column: 3 !important;
  grid-row: 1 !important;
  align-content: start !important;
  grid-template-rows: auto auto auto !important;
  gap: 8px !important;
}

.phase-boxes,
.phase-boxes-vertical {
  align-content: start !important;
}

.next-phase-vertical {
  margin-top: 6px !important;
}

/* Casteo más angosto y en la fila superior. */
.cast-panel {
  grid-column: 4 !important;
  grid-row: 1 !important;
  min-height: 0 !important;
  max-height: none !important;
  overflow: hidden !important;
}

/* Pestañas y cartas arriba a la derecha. Ya no contiene el panel del Kaster. */
.right-panel {
  grid-column: 5 !important;
  grid-row: 1 !important;
  grid-template-rows: 36px minmax(0, 1fr) !important;
}

/* Panel ancho del Kaster:
   desde la izquierda del contador de turno hasta el borde derecho. */
.caster-wide-panel {
  grid-column: 3 / 6 !important;
  grid-row: 2 !important;
  display: grid !important;
  grid-template-columns: 150px minmax(0, 1fr) !important;
  gap: 16px !important;
  padding: 12px !important;
  overflow: hidden !important;
  align-items: center !important;
}

/* Carta del Kaster dentro del panel.
   Mantiene proporción, no se estira. */
.caster-card-shell {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  min-width: 0;
  min-height: 0;
}

.caster-wide-card {
  position: relative !important;
  inset: auto !important;
  width: auto !important;
  height: 100% !important;
  aspect-ratio: 2 / 3 !important;
  max-width: 138px !important;
  max-height: 196px !important;
