  border: 1px solid rgba(255,255,255,.22);
  box-shadow: 0 0 10px rgba(0,0,0,.24);
  overflow: hidden;
}

.caster-domain-element-wrap {
  left: 0;
  z-index: 1;
}

.caster-domain-attribute-wrap {
  right: 0;
