@keyframes kastDropLanding {
  0% {
    opacity: 0;
    transform: translateY(-120px) scale(.82);
    filter: blur(3px);
  }
  54% {
    opacity: 1;
    transform: translateY(0) scale(1.02);
    filter: blur(0);
  }
  66% {
    transform: translateY(0) scale(.94, 1.06);
  }
  78% {
    transform: translateY(-6px) scale(1.03, .98);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

