.unit-heart-icon::after {
  content: '';
  position: absolute;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: #fff;
}
.unit-heart-icon::before { top: -9px; left: 0; }
.unit-heart-icon::after { top: 0; left: 7px; }

