  height: calc(var(--guardian-resistance-icon-size) * 1.08) !important;
  background: #ffffff !important;
  box-shadow: 0 0 6px rgba(255,255,255,.52) !important;
}

.guardian-resistance-status .status-number {
  width: var(--guardian-resistance-number-size) !important;
  height: var(--guardian-resistance-number-size) !important;
  right: var(--guardian-resistance-number-x) !important;
  bottom: var(--guardian-resistance-number-y) !important;
  background: var(--guardian-resistance-number-bg) !important;
  color: var(--guardian-resistance-number-color) !important;
  font: bold var(--guardian-resistance-number-font-size) Arial, sans-serif !important;
}

