.invocation-stat-status {
  position: absolute !important;
  left: 50% !important;
  right: auto !important;
  bottom: var(--invocation-badges-y) !important;
  transform: translateX(calc(-50% + var(--invocation-badges-x))) !important;
  z-index: 12 !important;
  width: 0 !important;
  height: 0 !important;
  display: block !important;
  pointer-events: none !important;
  overflow: visible !important;
}

.unit-stat-icon-badge {
  position: absolute !important;
  left: 0 !important;
  top: 0 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  overflow: visible !important;
  display: block !important;
  pointer-events: none !important;
}

.unit-damage-badge {
  width: var(--damage-badge-box-size) !important;
  height: var(--damage-badge-box-size) !important;
  transform: translate(calc(-50% + var(--damage-badge-x)), var(--damage-badge-y)) !important;
}

.unit-life-badge {
  width: var(--life-badge-box-size) !important;
  height: var(--life-badge-box-size) !important;
  transform: translate(calc(-50% + var(--life-badge-x)), var(--life-badge-y)) !important;
}

.unit-damage-badge .unit-sword-icon,
.unit-life-badge .unit-heart-icon {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
}

.unit-damage-badge .unit-weapon-icon {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  width: var(--damage-icon-size) !important;
  height: var(--damage-icon-size) !important;
  object-fit: contain !important;
  transform: translate(calc(-50% + var(--damage-icon-x)), calc(-50% + var(--damage-icon-y))) !important;
  filter: drop-shadow(0 0 5px rgba(255,255,255,.72)) !important;
  pointer-events: none !important;
