  z-index: 430 !important;
  filter: drop-shadow(0 18px 10px rgba(0,0,0,.55)) !important;
  will-change: transform !important;
}

@keyframes unitOscillationAttackOrbit {
  0% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y)), 0) scale(1) rotate(0deg);
  }
  18% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--oscillation-orbit-a-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--oscillation-orbit-a-y, 0px)), 0) scale(1.06) rotate(-1.2deg);
  }
  42% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--oscillation-orbit-b-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--oscillation-orbit-b-y, 0px)), 0) scale(1.045) rotate(1.6deg);
  }
  66% {
    transform: translate3d(calc(-50% + var(--invocation-offset-x) + var(--oscillation-orbit-c-x, 0px)), calc(-80% + var(--invocation-offset-y) + var(--oscillation-orbit-c-y, 0px)), 0) scale(1.025) rotate(-1.4deg);
  }
  84% {
