  box-shadow: 0 0 7px rgba(255,255,255,.62) !important;
}

/* Icono de tiempo en cast queue y respawn: mismo SVG, plano, sin cápsula de fondo. */
.cooldown-time-badge {
  position: relative !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: transparent !important;
  overflow: visible !important;
}

.cooldown-time-icon {
