.return-to-spellbook-token.traveling {
  animation: returnToSpellbookElemental 2.05s cubic-bezier(.16,.84,.22,1) forwards !important;
}
@keyframes returnToSpellbookElemental {
  0% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
    filter: drop-shadow(0 0 10px var(--return-color, #5400FF)) drop-shadow(0 8px 8px rgba(0,0,0,.62));
  }
  42% {
    opacity: 1;
    transform: translate(calc(-50% + (var(--return-x) * .52)), calc(-50% + (var(--return-y) * .44) - 42px)) scale(1.60);
    filter: drop-shadow(0 0 24px var(--return-color, #5400FF)) drop-shadow(0 18px 16px rgba(0,0,0,.54));
  }
  82% {
    opacity: .92;
    transform: translate(calc(-50% + var(--return-x)), calc(-50% + var(--return-y))) scale(.78);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--return-x)), calc(-50% + var(--return-y))) scale(.38);
  }
}
.restore-travel-token.traveling {
  animation: restoreToSpawnElemental 1.24s cubic-bezier(.18,.82,.24,1) forwards !important;
}
@keyframes restoreToSpawnElemental {
  0% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
    filter: drop-shadow(0 0 10px var(--restore-fly-color, #5400FF)) drop-shadow(0 8px 8px rgba(0,0,0,.62));
  }
  46% {
    opacity: 1;
    transform: translate(calc(-50% + (var(--restore-x) * .55)), calc(-50% + (var(--restore-y) * .48) - 28px)) scale(1.38);
    filter: drop-shadow(0 0 22px var(--restore-fly-color, #5400FF)) drop-shadow(0 15px 14px rgba(0,0,0,.52));
  }
  86% {
    opacity: .95;
    transform: translate(calc(-50% + var(--restore-x)), calc(-50% + var(--restore-y))) scale(.88);
  }
  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--restore-x)), calc(-50% + var(--restore-y))) scale(.55);
  }
}
.element-burst-fx {
  position: fixed;
  left: 0;
  top: 0;
  width: 1px;
  height: 1px;
  z-index: 9997;
  pointer-events: none;
  filter: drop-shadow(0 0 7px var(--burst-color, #5400FF));
}
.element-burst-fx::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--burst-color, #5400FF) 70%, white 30%);
  transform: translate(-50%, -50%) scale(.1);
  opacity: .8;
  animation: elementBurstRing .82s ease-out forwards;
}
.element-burst-fx span {
  position: absolute;
  left: 0;
  top: 0;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--burst-color, #5400FF) 80%, white 20%);
  box-shadow: 0 0 8px var(--burst-color, #5400FF);
  animation: elementBurstParticle .92s cubic-bezier(.16,.84,.22,1) forwards;
}
@keyframes elementBurstRing {
  0% { opacity: .82; transform: translate(-50%, -50%) scale(.1); }
  74% { opacity: .45; transform: translate(-50%, -50%) scale(1.55); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.9); }
}
@keyframes elementBurstParticle {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.25); }
  12% { opacity: 1; }
  78% { opacity: .9; transform: translate(calc(-50% + var(--px)), calc(-50% + var(--py))) scale(1); }
  100% { opacity: 0; transform: translate(calc(-50% + (var(--px) * 1.35)), calc(-50% + (var(--py) * 1.35))) scale(.18); }
}


