/* =========================================================
   ROK v5.3.213ZZS · FEEDBACK FLOTANTE MÁS LARGO Y LEGIBLE
   =========================================================
   Regla visual temporal/global:
   - Los avisos flotantes duran aprox. 3x más.
   - Suben más en eje Y.
   - El desvanecimiento es más suave.
   - No toca reglas de combate, daño, armadura ni letalidad.
*/

:root {
  --rok-float-feedback-duration: 5.45s;
  --rok-float-feedback-fast-duration: 4.05s;
  --rok-float-feedback-y-start: -18%;
  --rok-float-feedback-y-pop: -64%;
  --rok-float-feedback-y-hold: -138%;
  --rok-float-feedback-y-end: -245%;
}

/* Daño normal, armadura y chips con daño/factor. */
.floating-damage,
.floating-armor-damage,
.floating-factor-damage-chip,
.floating-critical-damage-chip,
.floating-lethality-execution-chip,
.floating-lethality-execution-free {
  animation: rokFloatFeedbackLong var(--rok-float-feedback-duration) cubic-bezier(.15,.82,.18,1) forwards !important;
}

/* Textos de combate/acciones: DISTANCIA, ATAQUE EXTRA, COMBATIENDO, ATACANDO, INVOCA, RESTAURA 0, 100%, 50%. */
.floating-combat,
.floating-combat.buff,
.floating-combat.critical,
.floating-combat.oscillation-hit-label {
  animation: rokFloatFeedbackLong var(--rok-float-feedback-duration) cubic-bezier(.15,.82,.18,1) forwards !important;
}

/* Fallos normales y fallos con factor: FALLÓ, EVASIÓN, LETALIDAD FALLÓ, crítico fallido. */
.floating-miss,
.floating-factor-miss,
.floating-factor-evasion-miss {
  animation: rokFloatFeedbackLong var(--rok-float-feedback-duration) cubic-bezier(.15,.82,.18,1) forwards !important;
}

/* Animación común: aparece, se queda legible, sube más y se desvanece suave. */
@keyframes rokFloatFeedbackLong {
  0% {
    opacity: 0;
    transform: translate(-50%, var(--rok-float-feedback-y-start)) scale(.72);
    filter: blur(.5px);
  }
  9% {
    opacity: 1;
    transform: translate(-50%, var(--rok-float-feedback-y-pop)) scale(1.08);
    filter: blur(0);
  }
  54% {
    opacity: 1;
    transform: translate(-50%, var(--rok-float-feedback-y-hold)) scale(1);
    filter: blur(0);
  }
  78% {
    opacity: .82;
    transform: translate(-50%, calc(var(--rok-float-feedback-y-end) * .82)) scale(.98);
    filter: blur(.2px);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, var(--rok-float-feedback-y-end)) scale(.92);
    filter: blur(var(--particle-blur, 1.2px));
  }
}

/* Los efectos slash quedan rápidos porque son impacto visual, no lectura de texto. */
.critical-slash-fx {
  animation-duration: 940ms !important;
}

/* Un poco más de separación visual para ejecución, sin contenedor. */
.floating-lethality-execution-free {
  z-index: 985 !important;
}

.floating-armor-damage {
  z-index: 975 !important;
}

.floating-critical-damage-chip {
  z-index: 982 !important;
}


/* =========================================================
   ROK v5.3.213ZZT · DESVANECIMIENTO PROGRESIVO DE FEEDBACK
   =========================================================
   Ajuste sobre ZZS:
   - Mantiene duración larga y desplazamiento alto.
   - El fade empieza antes.
   - El aviso se desplaza y se disuelve durante el viaje, no solo al final.
*/

:root {
  --rok-float-feedback-duration: 5.25s;
  --rok-float-feedback-y-start: -18%;
  --rok-float-feedback-y-pop: -62%;
  --rok-float-feedback-y-mid-a: -96%;
  --rok-float-feedback-y-mid: -132%;
  --rok-float-feedback-y-late: -205%;
  --rok-float-feedback-y-late-a: -238%;
  --rok-float-feedback-y-end: -270%;
}

.floating-damage,
.floating-armor-damage,
.floating-factor-damage-chip,
.floating-critical-damage-chip,
.floating-lethality-execution-chip,
.floating-lethality-execution-free,
.floating-combat,
.floating-combat.buff,
.floating-combat.critical,
.floating-combat.oscillation-hit-label,
.floating-miss,
.floating-factor-miss,
.floating-factor-evasion-miss {
  animation-name: rokFloatFeedbackProgressiveFade !important;
  animation-duration: var(--rok-float-feedback-duration) !important;
  animation-timing-function: cubic-bezier(.14,.78,.22,1) !important;
  animation-fill-mode: forwards !important;
}

/* Aparece fuerte, luego se va apagando durante el desplazamiento. */
@keyframes rokFloatFeedbackProgressiveFade {
  0% {
    opacity: 0;
    transform: translate(-50%, var(--rok-float-feedback-y-start)) scale(.72);
    filter: blur(.65px);
  }
  8% {
    opacity: 1;
    transform: translate(-50%, var(--rok-float-feedback-y-pop)) scale(1.08);
    filter: blur(0);
  }
  24% {
    opacity: .95;
    transform: translate(-50%, var(--rok-float-feedback-y-mid-a)) scale(1.02);
    filter: blur(0);
  }
  46% {
    opacity: .62;
    transform: translate(-50%, var(--rok-float-feedback-y-mid)) scale(.99);
    filter: blur(.18px);
  }
  68% {
    opacity: .31;
    transform: translate(-50%, var(--rok-float-feedback-y-late)) scale(.96);
    filter: blur(.5px);
  }
  86% {
    opacity: .12;
    transform: translate(-50%, var(--rok-float-feedback-y-late-a)) scale(.93);
    filter: blur(.85px);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, var(--rok-float-feedback-y-end)) scale(.9);
    filter: blur(1.25px);
  }
}

/* Armadura aparece primero y se apaga antes que ejecución para contaminar menos. */
.floating-armor-damage {
  animation-duration: 4.65s !important;
}

/* Ejecución conserva presencia, pero también se disuelve durante el viaje. */
.floating-lethality-execution-free {
