@keyframes opponentThinkingNoticeIn {
  from { opacity: 0; transform: translateX(-50%) translateY(-6px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

@keyframes opponentThinkingHourglassPulse {
  from { transform: scale(.94); filter: brightness(.92); }
