}

@keyframes casterEnemyZoneWarningPulse {
  0%, 100% { transform: translateY(0) scale(1); filter: brightness(1); }
  16% { transform: translateY(-1px) scale(1.04); filter: brightness(1.55); }
  34% { transform: translateY(1px) scale(.98); filter: brightness(1.15); }
  52% { transform: translateY(-1px) scale(1.06); filter: brightness(1.48); }
  76% { transform: translateY(0) scale(1.01); filter: brightness(1.25); }
}

@keyframes casterEnemyZoneCellPulse {
  0% { filter: brightness(1); }
  20% { filter: brightness(1.85) saturate(1.35); }
  42% { filter: brightness(1.05); }
  64% { filter: brightness(1.7) saturate(1.25); }
  100% { filter: brightness(1); }
}

