/* =========================================================
   ROK v102 · VENTANA DE ACCIÓN REAL POR FASE + MODAL EN ARENA
   ========================================================= */
.quick-reaction-window.visible {
  animation: quickReactionNoticeFlash .52s ease-out both !important;
}

@keyframes quickReactionNoticeFlash {
  0% { opacity: 0; filter: brightness(.9); }
  18% { opacity: 1; filter: brightness(1.18); }
  78% { opacity: 1; filter: brightness(1); }
  100% { opacity: 0; filter: brightness(.92); }
}

.quick-reaction-modal {
  position: fixed !important;
