/* Guardián + objetivos apilados en una sola tarjeta VS. */
.combat-hud .guardian-combat-group {
  position: relative;
  grid-template-rows: minmax(52px, auto) 18px minmax(58px, auto) !important;
  overflow: visible !important;
  min-height: 142px;
}
.combat-hud .guardian-combat-side {
  min-height: 54px !important;
}
