  overflow: hidden !important;
}
.combat-hud .guardian-combat-art {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  background: rgba(4,3,8,.72);
  filter: drop-shadow(0 0 7px var(--combat-element-color, #5400FF));
}
.combat-hud .guardian-combat-resistance {
  z-index: 6;
}
.combat-hud .guardian-combat-target-stack {
  position: relative;
  width: 100%;
  min-height: 64px;
  overflow: visible;
}
.combat-hud .guardian-combat-target-card {
  position: absolute !important;
  left: calc(var(--guardian-stack-index, 0) * var(--shared-card-stack-step-x));
  top: calc(var(--guardian-stack-index, 0) * var(--shared-card-stack-step-y));
  width: calc(100% - 14px) !important;
  opacity: calc(1 - (var(--guardian-stack-index, 0) * var(--shared-card-stack-opacity-step)));
  transform: scale(calc(1 - (var(--guardian-stack-index, 0) * var(--shared-card-stack-scale-step))));
  transform-origin: top left;
  pointer-events: none;
  transition: transform .22s ease, opacity .22s ease, top .22s ease, left .22s ease;
}
.combat-hud .guardian-combat-target-card.is-focused {
  left: 0;
  top: 0;
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}
.combat-hud .guardian-channel-remaining-badge {
  position: absolute;
  left: -8px;
  top: -9px;
  z-index: 15;
  min-width: 18px;
