}

/* Kaster derrotado y resultado de partida. */
.caster-defeat-fx {
  position: absolute;
  width: 96px;
  height: 96px;
  transform: translate(-50%, -50%);
  z-index: 250;
  pointer-events: none;
  border-radius: 50%;
  border: 3px solid var(--caster-defeat-color, #5400FF);
  box-shadow: 0 0 24px var(--caster-defeat-color, #5400FF), inset 0 0 26px var(--caster-defeat-color, #5400FF);
  animation: casterDefeatCollapse 1.65s ease-out forwards;
}
.caster-defeat-fx span,
.caster-defeat-fx i {
  position: absolute;
  inset: 50%;
  width: 6px;
  height: 40px;
  background: linear-gradient(to top, transparent, var(--caster-defeat-color, #5400FF));
  transform-origin: 50% 0;
}
.caster-defeat-fx span:nth-child(1) { transform: rotate(0deg); }
.caster-defeat-fx span:nth-child(2) { transform: rotate(120deg); }
.caster-defeat-fx span:nth-child(3) { transform: rotate(240deg); }
.caster-defeat-fx i { transform: rotate(55deg); opacity: .7; }
@keyframes casterDefeatCollapse {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.35) rotate(0deg); }
  22% { opacity: 1; transform: translate(-50%, -50%) scale(1.25) rotate(20deg); }
  70% { opacity: .9; transform: translate(-50%, -50%) scale(.82) rotate(120deg); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(.05) rotate(220deg); }
}
