    min-height: 54px;
    padding-block: 14px;
  }
}

/* =========================================================
   ROK v233 · COMPATIBILIDAD DE KASTER Y CAMBIO SEGURO
   ========================================================= */

.library-builder-caster-chip {
  appearance: none;
  cursor: pointer;
  max-width: 190px;
  text-align: left;
  transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease;
}

.library-builder-caster-chip:hover,
.library-builder-caster-chip:focus-visible {
  transform: translateY(-1px);
  border-color: rgba(255, 226, 143, .62);
  box-shadow: 0 0 18px rgba(173, 93, 255, .2), inset 0 0 12px rgba(255,255,255,.04);
  outline: none;
}

.library-builder-caster-chip:disabled {
  cursor: default;
}

.library-builder-caster-chip-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.library-builder-caster-chip-copy strong {
  max-width: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #ffeec2;
  font: 850 10px/1 system-ui, sans-serif;
}

.library-builder-caster-chip-copy small {
  color: #d2adff;
  font: 850 8px/1 system-ui, sans-serif;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.library-builder-card-tile.incompatible {
  border-color: rgba(255, 73, 73, .84) !important;
  box-shadow:
    inset 0 0 24px rgba(123, 0, 0, .7),
    0 0 0 2px rgba(255, 53, 53, .16),
    0 0 24px rgba(255, 31, 31, .28) !important;
}

.library-builder-card-tile.incompatible::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 18;
  pointer-events: none;
  background:
    linear-gradient(118deg, transparent 0 24%, rgba(255, 70, 70, .2) 36%, transparent 48% 58%, rgba(176, 0, 0, .22) 69%, transparent 82%),
    radial-gradient(circle at 50% 42%, rgba(255, 0, 0, .08), rgba(116, 0, 0, .32));
  mix-blend-mode: screen;
  animation: libraryBuilderIncompatibleFoil 2.8s linear infinite;
}

.library-builder-card-tile.incompatible::after {
  content: 'INCOMPATIBLE';
  position: absolute;
  left: 50%;
  bottom: 10px;
  z-index: 22;
  transform: translateX(-50%);
  padding: 4px 7px;
  border: 1px solid rgba(255, 183, 183, .55);
  border-radius: 999px;
  background: rgba(92, 0, 0, .86);
  color: #fff1f1;
  box-shadow: 0 0 15px rgba(255, 28, 28, .34);
  font: 950 7px/1 system-ui, sans-serif;
  letter-spacing: .08em;
  white-space: nowrap;
  pointer-events: none;
}

.library-builder-incompatible-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 25;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid rgba(255,255,255,.72);
  border-radius: 50%;
  background: #a50000;
  color: #fff;
  box-shadow: 0 0 14px rgba(255, 22, 22, .65);
  font: 1000 13px/1 system-ui, sans-serif;
  pointer-events: none;
}

@keyframes libraryBuilderIncompatibleFoil {
  from { background-position: -140px 0, 0 0; }
  to { background-position: 180px 0, 0 0; }
}

.caster-change-card {
  width: min(92cqw, 520px);
}

.caster-change-warning {
  margin: 0 0 18px;
  padding: 12px 14px;
  border: 1px solid rgba(255, 102, 102, .32);
  border-radius: 11px;
  background: rgba(116, 0, 0, .18);
  color: #ffd0d0;
  font: 750 12px/1.4 system-ui, sans-serif;
}

.spellbooks-primary-btn.danger-confirm {
  border-color: rgba(255, 117, 117, .5);
  background: linear-gradient(180deg, rgba(164, 38, 50, .98), rgba(81, 13, 24, .98));
  box-shadow: 0 0 18px rgba(255, 53, 73, .16);
}

/* =========================================================
