   ========================================================================== */

/* Spellbook: sin Caudillo válido, la carta permanece visible pero oscura. */
.card-slot.despliegue-spell-unavailable .despliegue-spell-unavailable-card {
  opacity: .66 !important;
  filter: grayscale(.46) brightness(.74) contrast(.96) !important;
  transition: opacity .18s ease, filter .18s ease !important;
}

/* Spellbook: requisitos de arena cumplidos. Reutiliza el lenguaje foil de
   las ventanas de acción sin convertirlo en una segunda miniatura. */
.card-slot.despliegue-spell-ready {
  overflow: visible !important;
}
.card-slot.despliegue-spell-ready .despliegue-spell-ready-card {
  position: relative !important;
  overflow: hidden !important;
  opacity: 1 !important;
  filter: brightness(1.04) saturate(1.08) !important;
  box-shadow:
    0 0 0 1px rgba(255,239,173,.82),
    0 0 10px rgba(255,213,92,.68),
    0 0 19px rgba(255,111,36,.42) !important;
}
.card-slot.despliegue-spell-ready .despliegue-spell-ready-card::after {
  content: "";
  position: absolute;
  inset: -30%;
  z-index: 14;
  pointer-events: none;
  background: linear-gradient(
    115deg,
    transparent 0%,
    transparent 35%,
    rgba(255,255,255,.14) 42%,
    rgba(255,244,188,.58) 49%,
    rgba(255,255,255,.18) 56%,
    transparent 65%,
    transparent 100%
  );
  transform: translateX(-82%) rotate(4deg);
  mix-blend-mode: screen;
  animation: despliegueSpellbookFoilSweep 1.65s ease-in-out infinite;
}
@keyframes despliegueSpellbookFoilSweep {
  0% { transform: translateX(-82%) rotate(4deg); opacity: .12; }
  42% { opacity: .9; }
  100% { transform: translateX(82%) rotate(4deg); opacity: .12; }
}

/* Punto de disponibilidad, equivalente al indicador de acción de arena. */
.spellbook-action-ready-indicator {
  position: absolute !important;
  left: 3px !important;
  top: 3px !important;
  width: 7px !important;
  height: 7px !important;
  min-width: 7px !important;
  min-height: 7px !important;
  border-radius: 50% !important;
  border: 1px solid rgba(255,255,255,.94) !important;
  background: radial-gradient(circle at 35% 30%, #fffdf0 0 25%, #ffe787 44%, #e5aa2e 74%, #6b3c05 100%) !important;
  box-shadow: 0 0 4px rgba(255,255,255,.96), 0 0 10px rgba(255,221,105,.90) !important;
  z-index: 90 !important;
  pointer-events: none !important;
  animation: unitActionReadyIndicatorPulse .9s ease-in-out infinite !important;
}

/* Selección del Caudillo: solo ficha + foil + punto. No se usa cuadro de
   casilla ni glifo adicional. */
.unit.despliegue-target-selectable-foil {
  overflow: visible !important;
}
.unit.despliegue-target-selectable-foil > .unit-token-img {
  filter:
    drop-shadow(1px 0 0 rgba(255,255,255,.82))
    drop-shadow(-1px 0 0 rgba(255,255,255,.82))
    drop-shadow(0 1px 0 rgba(255,255,255,.82))
    drop-shadow(0 -1px 0 rgba(255,255,255,.82))
    drop-shadow(0 0 9px rgba(255,226,121,.82))
    drop-shadow(0 0 17px rgba(255,118,35,.64)) !important;
}
.despliegue-target-selectable-foil-img {
  opacity: .68 !important;
}
.despliegue-target-ready-indicator {
  left: -1px !important;
  top: -2px !important;
}

/* v361 · Hechizos vinculados en miniatura persistente.
   Reutiliza literalmente la lectura visual del apilado del VS:
   la invocación permanece al frente y cada carta vinculada aparece detrás,
   desplazada 5 px hacia la derecha y 5 px hacia abajo, con la misma
   reducción progresiva de escala y opacidad. */
.selected-command-card-composite {
  position: relative !important;
  overflow: visible !important;
  isolation: isolate;
}
.persistent-linked-spell-card-stack {
  position: absolute;
  left: 4px;
  top: 4px;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  overflow: visible;
}
.persistent-linked-spell-card-mini {
