/* =========================================================
   ROK v399.x · EFECTO VISUAL DE QUEMADURA SOBRE INVOCACIÓN
   Fueguitos persistentes con secuencia 1-2-3 y reaparición por zonas.
   Máximo 5 llamitas según las fases restantes del factor.
   ========================================================= */
.unit-burn-fx {
  position: absolute;
  left: 50%;
  top: -10%;
  width: 88%;
  height: 96%;
  transform: translateX(-50%);
  pointer-events: none;
  z-index: 38;
  overflow: visible;
}

.unit-burn-flame {
  position: absolute;
  left: 50%;
  top: 50%;
  width: clamp(7px, 0.57cqw, 11px);
  height: clamp(9px, 0.74cqw, 14px);
  transform: translate(-50%, -50%);
  opacity: 0;
  pointer-events: none;
  filter:
    drop-shadow(0 0 1px rgba(255, 243, 196, .14))
    drop-shadow(0 0 3px rgba(255, 153, 42, .18));
  animation: burnFlameTeleportCycle 6s linear infinite;
  animation-delay: var(--burn-teleport-delay, 0ms);
  will-change: left, top, opacity;
}

.unit-burn-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.unit-burn-frame-1,
.unit-burn-frame-2,
.unit-burn-frame-3 {
  animation-duration: .54s;
  animation-timing-function: steps(1, end);
  animation-iteration-count: infinite;
  animation-delay: var(--burn-frame-delay, 0ms);
}

.unit-burn-frame-1 { animation-name: burnFrameCycle1; }
.unit-burn-frame-2 { animation-name: burnFrameCycle2; }
.unit-burn-frame-3 { animation-name: burnFrameCycle3; }

@keyframes burnFrameCycle1 {
  0%, 32.99% { opacity: .50; visibility: visible; }
  33%, 100% { opacity: 0; visibility: hidden; }
}

@keyframes burnFrameCycle2 {
  0%, 32.99% { opacity: 0; visibility: hidden; }
  33%, 65.99% { opacity: .50; visibility: visible; }
  66%, 100% { opacity: 0; visibility: hidden; }
}

@keyframes burnFrameCycle3 {
  0%, 65.99% { opacity: 0; visibility: hidden; }
  66%, 100% { opacity: .50; visibility: visible; }
}

@keyframes burnFlameTeleportCycle {
  0%, 2% {
    left: var(--burn-p1-x, 50%);
    top: var(--burn-p1-y, 50%);
    opacity: 0;
  }
  4%, 25% {
    left: var(--burn-p1-x, 50%);
    top: var(--burn-p1-y, 50%);
    opacity: 1;
  }
  26%, 32% {
    left: var(--burn-p1-x, 50%);
    top: var(--burn-p1-y, 50%);
    opacity: 0;
  }
  33%, 35% {
    left: var(--burn-p2-x, 50%);
    top: var(--burn-p2-y, 50%);
    opacity: 0;
  }
  37%, 58% {
    left: var(--burn-p2-x, 50%);
    top: var(--burn-p2-y, 50%);
    opacity: 1;
  }
  59%, 65% {
    left: var(--burn-p2-x, 50%);
    top: var(--burn-p2-y, 50%);
    opacity: 0;
  }
  66%, 68% {
    left: var(--burn-p3-x, 50%);
    top: var(--burn-p3-y, 50%);
    opacity: 0;
  }
  70%, 91% {
    left: var(--burn-p3-x, 50%);
    top: var(--burn-p3-y, 50%);
    opacity: 1;
  }
  92%, 100% {
    left: var(--burn-p3-x, 50%);
    top: var(--burn-p3-y, 50%);
    opacity: 0;
  }
}

.unit.invocation.unit-burn-tick-flash {
  animation: burnTickUnitShake .88s cubic-bezier(.18,.78,.22,1) both !important;
}

.unit.invocation.unit-burn-tick-flash > .unit-token-img {
  animation: burnTickUnitRedBlink .88s cubic-bezier(.18,.78,.22,1) both !important;
}

@keyframes burnTickUnitShake {
  0%   { transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1); }
  12%  { transform: translate(calc(-50% + var(--invocation-offset-x) - 2px), calc(-80% + var(--invocation-offset-y))) scale(1.01) rotate(-1deg); }
  24%  { transform: translate(calc(-50% + var(--invocation-offset-x) + 2px), calc(-80% + var(--invocation-offset-y))) scale(1.015) rotate(1deg); }
  36%  { transform: translate(calc(-50% + var(--invocation-offset-x) - 3px), calc(-80% + var(--invocation-offset-y))) scale(1.02) rotate(-1.4deg); }
  50%  { transform: translate(calc(-50% + var(--invocation-offset-x) + 3px), calc(-80% + var(--invocation-offset-y))) scale(1.02) rotate(1.4deg); }
  66%  { transform: translate(calc(-50% + var(--invocation-offset-x) - 2px), calc(-80% + var(--invocation-offset-y))) scale(1.014) rotate(-0.8deg); }
  82%  { transform: translate(calc(-50% + var(--invocation-offset-x) + 2px), calc(-80% + var(--invocation-offset-y))) scale(1.01) rotate(0.8deg); }
  100% { transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1) rotate(0deg); }
}

@keyframes burnTickUnitRedBlink {
  0%, 100% {
    filter: brightness(1) saturate(1) drop-shadow(0 8px 7px rgba(0,0,0,.55));
  }
  14% {
    filter: brightness(1.28) saturate(1.22) hue-rotate(-10deg) drop-shadow(0 0 8px rgba(255, 85, 50, .42)) drop-shadow(0 8px 7px rgba(0,0,0,.55));
  }
  28% {
    filter: brightness(0.95) saturate(1.04) hue-rotate(-6deg) drop-shadow(0 8px 7px rgba(0,0,0,.55));
  }
  42% {
    filter: brightness(1.24) saturate(1.18) hue-rotate(-10deg) drop-shadow(0 0 10px rgba(255, 68, 32, .48)) drop-shadow(0 8px 7px rgba(0,0,0,.55));
  }
  58% {
    filter: brightness(0.98) saturate(1.08) hue-rotate(-4deg) drop-shadow(0 8px 7px rgba(0,0,0,.55));
  }
  74% {
    filter: brightness(1.16) saturate(1.14) hue-rotate(-8deg) drop-shadow(0 0 7px rgba(255, 88, 48, .34)) drop-shadow(0 8px 7px rgba(0,0,0,.55));
  }
}

