  background: radial-gradient(ellipse at center, rgba(255, 248, 203, .96) 0%, rgba(255, 216, 74, .66) 34%, rgba(255, 216, 74, 0) 74%);
  transform: scaleX(.48) scaleY(.24);
  animation: gloriaGroundGlow .72s cubic-bezier(.16,.84,.22,1) both;
}
.gloria-restore-ray {
  position: absolute;
  bottom: 5%;
  width: 9%;
  height: 82%;
  border-radius: 50% 50% 15% 15%;
  transform-origin: 50% 100%;
  background: linear-gradient(to top, rgba(255, 216, 74, .98), rgba(255, 248, 203, .92) 42%, rgba(255,255,255,0) 100%);
  clip-path: polygon(44% 100%, 56% 100%, 72% 42%, 52% 0%, 31% 43%);
  opacity: 0;
  animation: gloriaRayRise .78s cubic-bezier(.15,.78,.2,1) both;
}
.gloria-restore-ray.ray-1 { left: 14%; animation-delay: 0ms; transform: rotate(-9deg) scaleY(.72); }
.gloria-restore-ray.ray-2 { left: 27%; animation-delay: 40ms; transform: rotate(-4deg) scaleY(.92); }
.gloria-restore-ray.ray-3 { left: 43%; animation-delay: 10ms; transform: rotate(1deg) scaleY(1.02); }
.gloria-restore-ray.ray-4 { left: 56%; animation-delay: 55ms; transform: rotate(4deg) scaleY(.88); }
.gloria-restore-ray.ray-5 { left: 69%; animation-delay: 20ms; transform: rotate(8deg) scaleY(.74); }
.gloria-restore-ray.ray-6 { left: 36%; animation-delay: 90ms; transform: rotate(-1deg) scaleY(.62); }
.gloria-restore-spark {
  position: absolute;
  width: 4%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: #fff8cf;
  box-shadow: 0 0 7px #ffd84a, 0 0 14px rgba(255,216,74,.72);
  opacity: 0;
  animation: gloriaSparkUp .68s ease-out both;
}
.gloria-restore-spark.spark-1 { left: 22%; bottom: 18%; animation-delay: 70ms; }
.gloria-restore-spark.spark-2 { left: 74%; bottom: 13%; animation-delay: 10ms; }
.gloria-restore-spark.spark-3 { left: 47%; bottom: 26%; animation-delay: 120ms; }
.gloria-restore-spark.spark-4 { left: 60%; bottom: 31%; animation-delay: 45ms; }

.healing-factor-cell-fx {
  mix-blend-mode: screen;
  animation: healingCellFxFade 1.08s ease-out both;
}
.healing-cell-glow {
  position: absolute;
