  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--healing-secondary) 72%, transparent 28%) 0%, color-mix(in srgb, var(--healing-primary) 34%, transparent 66%) 42%, transparent 72%);
  animation: healingCellGlow .82s ease-out both;
}
.healing-cross {
  position: absolute;
  width: 18%;
  height: 18%;
  opacity: 0;
  filter: drop-shadow(0 0 5px var(--healing-primary)) drop-shadow(0 0 9px color-mix(in srgb, var(--healing-primary) 64%, transparent 36%));
  animation: healingCrossRise .92s cubic-bezier(.16,.84,.22,1) both;
}
.healing-cross::before,
.healing-cross::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  border-radius: 18%;
  background: var(--healing-primary);
  transform: translate(-50%, -50%);
}
.healing-cross::before { width: 100%; height: 34%; }
.healing-cross::after { width: 34%; height: 100%; }
.healing-cross.cross-2::before,
.healing-cross.cross-2::after,
.healing-cross.cross-4::before,
.healing-cross.cross-4::after { background: var(--healing-secondary); }
.healing-cross.cross-1 { left: 8%; top: 44%; animation-delay: 20ms; transform: scale(.72); }
.healing-cross.cross-2 { left: 36%; top: 13%; animation-delay: 90ms; transform: scale(.54); }
.healing-cross.cross-3 { right: 8%; top: 35%; animation-delay: 45ms; transform: scale(.86); }
.healing-cross.cross-4 { left: 47%; bottom: 8%; animation-delay: 135ms; transform: scale(.62); }
.healing-cross.cross-5 { left: 20%; bottom: 18%; animation-delay: 170ms; transform: scale(.46); }
.healing-particle {
  position: absolute;
  width: 4.5%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--healing-particle);
  box-shadow: 0 0 6px var(--healing-particle), 0 0 10px color-mix(in srgb, var(--healing-particle) 66%, transparent 34%);
  opacity: 0;
  animation: healingParticleFloat .84s ease-out both;
}
.healing-particle.particle-1 { left: 12%; bottom: 16%; animation-delay: 0ms; }
.healing-particle.particle-2 { left: 25%; bottom: 8%; animation-delay: 90ms; }
.healing-particle.particle-3 { left: 41%; bottom: 20%; animation-delay: 35ms; }
.healing-particle.particle-4 { left: 56%; bottom: 11%; animation-delay: 120ms; }
.healing-particle.particle-5 { left: 72%; bottom: 22%; animation-delay: 55ms; }
.healing-particle.particle-6 { left: 84%; bottom: 12%; animation-delay: 150ms; }
.healing-particle.particle-7 { left: 33%; bottom: 34%; animation-delay: 180ms; }
.healing-particle.particle-8 { left: 66%; bottom: 38%; animation-delay: 80ms; }

@keyframes gloriaRestoreFxFade {
  0% { opacity: 0; }
  10% { opacity: 1; }
  72% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes gloriaGroundGlow {
