/* =========================================================
   v412 · 天灯籠 / Tentōrō · Lámparas Celestiales
   ========================================================= */
.celestial-lamp-layer {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  overflow: visible;
}

.celestial-lamp-field {
  position: absolute;
  transform: translate(-50%, -50%);
  pointer-events: none;
  overflow: visible;
  isolation: isolate;
  filter: drop-shadow(0 0 9px rgba(255, 218, 79, .68));
}

.celestial-lamp-halo {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 300%;
  height: 300%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid rgba(255, 244, 177, .44);
  background:
    radial-gradient(circle at center,
      rgba(255, 253, 218, .38) 0%,
      rgba(255, 228, 108, .26) 34%,
      rgba(255, 204, 62, .12) 62%,
      rgba(255, 201, 52, 0) 76%);
  box-shadow:
    inset 0 0 22px rgba(255, 245, 186, .22),
    0 0 16px rgba(255, 222, 91, .46),
    0 0 34px rgba(255, 191, 42, .20);
  mix-blend-mode: screen;
  animation: tentorouHaloBreath 2.6s ease-in-out infinite alternate;
}

.celestial-lamp-cell-flash {
  position: absolute;
  left: 50%;
  top: 54%;
  width: 118%;
  height: 118%;
  transform: translate(-50%, -50%) scale(.24);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,.96) 0 12%, rgba(255,237,145,.80) 25%, rgba(255,202,65,.30) 54%, transparent 72%);
  opacity: 0;
  mix-blend-mode: screen;
}

.celestial-lamp-spark-burst {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 180%;
  height: 180%;
  transform: translate(-50%, -50%);
  opacity: 0;
  background:
    radial-gradient(circle at 18% 62%, #fff9c8 0 1.2%, transparent 2.2%),
    radial-gradient(circle at 34% 29%, #ffd857 0 1.5%, transparent 2.5%),
    radial-gradient(circle at 56% 18%, #fffdf0 0 1.1%, transparent 2.1%),
    radial-gradient(circle at 76% 36%, #ffd44d 0 1.5%, transparent 2.6%),
    radial-gradient(circle at 83% 68%, #fff7b5 0 1.2%, transparent 2.3%),
    radial-gradient(circle at 47% 82%, #ffd34a 0 1.4%, transparent 2.5%);
  filter: drop-shadow(0 0 5px #ffd34a);
}

.celestial-lamp-sprite {
  position: absolute;
  left: 50%;
  bottom: -10%;
  width: 92%;
  height: 148%;
  object-fit: contain;
  transform: translateX(-50%);
  transform-origin: 50% 100%;
  filter: drop-shadow(0 5px 6px rgba(0,0,0,.68)) drop-shadow(0 0 8px rgba(255,211,70,.62));
  z-index: 3;
}

.celestial-lamp-entering .celestial-lamp-cell-flash {
  animation: tentorouCellFlash 1.28s ease-out both;
}
.celestial-lamp-entering .celestial-lamp-spark-burst {
  animation: tentorouSparkBurst 1.48s ease-out both;
}
.celestial-lamp-entering .celestial-lamp-sprite {
  animation: tentorouLampRise 1.55s cubic-bezier(.16,.78,.18,1) both;
}
.celestial-lamp-entering .celestial-lamp-halo {
  animation: tentorouHaloEnter 1.55s ease-out both, tentorouHaloBreath 2.6s 1.55s ease-in-out infinite alternate;
}

.celestial-lamp-ambient-particles {
  position: absolute;
  left: -32%;
  top: -56%;
  width: 164%;
  height: 190%;
  z-index: 4;
  overflow: visible;
}
.celestial-lamp-ambient-particles i {
  position: absolute;
  left: var(--tentorou-particle-x, 50%);
  bottom: 4%;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #fff8bf;
  box-shadow: 0 0 5px #ffe269, 0 0 10px rgba(255,205,55,.72);
  opacity: 0;
  animation: tentorouAmbientParticle var(--tentorou-particle-duration, 3s) var(--tentorou-particle-delay, 0s) ease-out infinite;
}

.card-info-granted-movement-chip {
  box-shadow: 0 0 10px rgba(255, 226, 112, .22);
}

@keyframes tentorouLampRise {
  0% {
    opacity: 0;
    transform: translate(-50%, 62%) scale(.72, .28);
    filter: brightness(4.8) saturate(3.2) sepia(1) drop-shadow(0 0 20px #ffe35d);
  }
  24% {
    opacity: 1;
  }
  64% {
    transform: translate(-50%, -5%) scale(1.02, 1.04);
    filter: brightness(2.5) saturate(2.2) sepia(.72) drop-shadow(0 0 16px #ffd84b);
  }
  100% {
    opacity: 1;
    transform: translate(-50%, 0) scale(1);
    filter: brightness(1) saturate(1) sepia(0) drop-shadow(0 5px 6px rgba(0,0,0,.68)) drop-shadow(0 0 8px rgba(255,211,70,.62));
  }
}

@keyframes tentorouCellFlash {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.18); }
  22% { opacity: 1; transform: translate(-50%, -50%) scale(.76); }
  68% { opacity: .72; transform: translate(-50%, -50%) scale(1.12); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.46); }
}

@keyframes tentorouSparkBurst {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.42) rotate(-4deg); }
  30% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -58%) scale(1.18) rotate(5deg); }
}

@keyframes tentorouHaloEnter {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.22); }
  36% { opacity: .92; }
  100% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

@keyframes tentorouHaloBreath {
  from { opacity: .52; filter: brightness(.92) saturate(1); transform: translate(-50%, -50%) scale(.98); }
  to { opacity: .78; filter: brightness(1.16) saturate(1.18); transform: translate(-50%, -50%) scale(1.06); }
}

@keyframes tentorouAmbientParticle {
  0%, 12% { opacity: 0; transform: translate(0, 8px) scale(.35); }
  32% { opacity: .92; }
  72% { opacity: .58; }
  100% { opacity: 0; transform: translate(var(--tentorou-particle-drift, 0px), -62px) scale(1.18); }
}

/* =========================================================
   v414 · Nagayoru / Larga Noche
   ========================================================= */
.long-night-layer {
  position: absolute;
  inset: 0;
  z-index: 19;
  pointer-events: none;
  overflow: hidden;
}

.long-night-shell {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.long-night-global-mask,
.long-night-vignette,
.long-night-activation-wave,
.long-night-fireflies,
.long-night-fog-banks {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.long-night-global-mask {
  background:
    radial-gradient(circle at 50% 46%, rgba(80, 106, 180, .10) 0%, rgba(18, 28, 60, .26) 28%, rgba(5, 10, 26, .46) 62%, rgba(2, 4, 12, .68) 100%),
    linear-gradient(180deg, rgba(18, 28, 64, .42) 0%, rgba(7, 12, 28, .58) 48%, rgba(3, 5, 16, .74) 100%);
  mix-blend-mode: multiply;
  opacity: 0;
  transition: opacity 2s ease, filter 2s ease;
  filter: brightness(1.08);
}

.long-night-vignette {
  background: radial-gradient(circle at center, rgba(0,0,0,0) 34%, rgba(2,6,18,.18) 56%, rgba(0,0,0,.42) 100%);
  opacity: 0;
  transition: opacity 1.05s ease;
}

.long-night-layer.active .long-night-global-mask {
  opacity: 1;
  filter: brightness(1);
}

.long-night-layer.active .long-night-vignette {
  opacity: 1;
}

.long-night-activation-wave {
  opacity: 0;
  background:
    radial-gradient(circle at 50% 50%, rgba(174, 203, 255, .18) 0%, rgba(83, 113, 194, .12) 12%, rgba(30, 44, 92, .08) 22%, rgba(9, 13, 32, 0) 42%),
    radial-gradient(circle at 50% 50%, rgba(0,0,0,0) 0 28%, rgba(84, 98, 166, .20) 35%, rgba(8, 12, 34, 0) 52%);
  mix-blend-mode: screen;
}

.long-night-layer.activating .long-night-activation-wave {
  animation: longNightArenaPulse 1.9s ease-out both;
}

.long-night-fireflies {
  filter: drop-shadow(0 0 4px rgba(255, 239, 154, .78)) drop-shadow(0 0 10px rgba(255, 225, 102, .22));
  opacity: 0;
  transition: opacity 1.1s ease;
}

.long-night-layer.active .long-night-fireflies {
  opacity: 1;
}

.long-night-firefly {
  position: absolute;
  left: var(--firefly-x, 10%);
  top: var(--firefly-y, 10%);
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255,250,203,.98) 0%, rgba(255,233,124,.82) 42%, rgba(255,220,92,0) 74%);
  animation: longNightFireflyPulse var(--firefly-duration, 6.8s) ease-in-out infinite;
  animation-delay: var(--firefly-delay, 0s);
  opacity: 0;
}

.long-night-firefly::after {
  content: '';
  position: absolute;
  inset: -16px;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255, 226, 110, .12) 0%, rgba(255, 226, 110, 0) 70%);
}

.long-night-fog-bank {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 999px;
  background:
    radial-gradient(circle at 35% 50%, rgba(255,255,255,.11) 0%, rgba(215, 224, 245, .08) 24%, rgba(105, 126, 175, .05) 54%, rgba(10, 18, 42, 0) 76%),
    radial-gradient(circle at 62% 46%, rgba(229, 238, 255, .08) 0%, rgba(189, 201, 235, .05) 28%, rgba(7, 12, 30, 0) 74%);
  filter: blur(10px);
  opacity: .85;
  animation: longNightFogDrift var(--long-night-fog-duration, 11s) ease-in-out infinite alternate;
  animation-delay: var(--long-night-fog-delay, 0s);
}

.long-night-fog-banks {
  opacity: 0;
  transition: opacity 1.05s ease;
}

.long-night-layer.active .long-night-fog-banks {
  opacity: 1;
}

.arena-effect-long-night {
  box-shadow: 0 0 0 1px rgba(95, 124, 219, .34), 0 10px 20px rgba(0, 0, 0, .24);
}

@keyframes longNightArenaPulse {
  0% { opacity: 0; transform: scale(.72); }
  18% { opacity: .9; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.65); }
}

@keyframes longNightFireflyPulse {
  0% {
    opacity: 0;
    transform: translate(0, 0) scale(.54);
    box-shadow: 0 0 0 rgba(255, 231, 125, 0);
  }
  16% {
    opacity: .82;
    transform: translate(calc(var(--firefly-drift-x, 10px) * .18), calc(var(--firefly-drift-y, -6px) * .18)) scale(.88);
    box-shadow: 0 0 7px rgba(255, 231, 125, .32);
  }
  46% {
    opacity: 1;
    transform: translate(calc(var(--firefly-drift-x, 10px) * .58), calc(var(--firefly-drift-y, -6px) * .58)) scale(1.02);
    box-shadow: 0 0 10px rgba(255, 231, 125, .46);
  }
  74% {
    opacity: .26;
    transform: translate(calc(var(--firefly-drift-x, 10px) * .86), calc(var(--firefly-drift-y, -6px) * .86)) scale(.84);
    box-shadow: 0 0 2px rgba(255, 231, 125, .16);
  }
  100% {
    opacity: 0;
    transform: translate(var(--firefly-drift-x, 10px), var(--firefly-drift-y, -6px)) scale(.62);
    box-shadow: 0 0 0 rgba(255, 231, 125, 0);
  }
}

@keyframes longNightFogDrift {
  0% {
    transform: translate(-50%, -50%) translate3d(-6px, -2px, 0) scale(.96);
    opacity: .48;
  }
  50% {
    opacity: .88;
  }
  100% {
    transform: translate(-50%, -50%) translate3d(10px, 6px, 0) scale(1.06);
    opacity: .62;
  }
}

