.unit.invocation.unit-card-ninjaSaqueadorNovato,
.unit.invocation[data-card-id="ninjaSaqueadorNovato"] {
  overflow: visible !important;
}

.unit.invocation.unit-card-ninjaSaqueadorNovato > .unit-hitbox,
.unit.invocation[data-card-id="ninjaSaqueadorNovato"] > .unit-hitbox {
  left: 0 !important;
  top: -70% !important;
  right: auto !important;
  bottom: auto !important;
  width: 100% !important;
  height: 170% !important;
  min-width: 100% !important;
  min-height: 170% !important;
  max-width: 100% !important;
  max-height: 170% !important;
  transform: translate(var(--saqueador-novato-token-x), var(--saqueador-novato-token-y)) !important;
  transform-origin: center bottom !important;
  z-index: 120 !important;
}

.unit.invocation.unit-card-ninjaSaqueadorNovato .move-ready-badge,
.unit.invocation[data-card-id="ninjaSaqueadorNovato"] .move-ready-badge {
  top: -70% !important;
  transform:
    translate(
      calc(-50% + var(--move-ready-x) + var(--saqueador-novato-token-x)),
      calc(var(--move-ready-y) + var(--saqueador-novato-token-y))
    ) !important;
