/* Apertura individual. */
.booster-opening-view,
.booster-reveal-view,
.booster-results-view {
  position:relative;
  min-height:100%;
  height:100%;
  overflow:hidden;
  border:1px solid rgba(214,164,88,.16);
  border-radius:18px;
  background:radial-gradient(circle at 50% 45%,rgba(66,29,91,.22),rgba(6,5,9,.62) 52%,rgba(3,3,5,.80));
}
.booster-opening-view {
  display:grid;
