}
.booster-opening-closed { z-index:8; }
.booster-opening-closed.is-tearing { transform:scale(1.06) translateY(-3px); filter:brightness(1.22) drop-shadow(0 0 22px rgba(200,119,255,.30)); }
.booster-opening-closed.is-hidden { opacity:0; transform:scale(.92) translateY(12px); pointer-events:none; }
.booster-pack-visual-opening { width:min(290px,30cqw); height:min(455px,54cqh); }
.booster-opening-open { z-index:7; opacity:0; transform:scale(.94) translateY(8px); pointer-events:none; }
.booster-opening-open.is-visible { opacity:1; transform:scale(1) translateY(0); }
.booster-opening-back,
.booster-opening-front {
  position:absolute;
  left:50%;
  top:50%;
  width:min(305px,31cqw);
  height:min(470px,56cqh);
  transform:translate(-50%,-50%);
  object-fit:contain;
  pointer-events:none;
  filter:drop-shadow(0 18px 20px rgba(0,0,0,.62));
}
.booster-opening-back { z-index:1; }
.booster-opening-front { z-index:5; }
.booster-opening-card-stack {
  position:absolute;
  left:50%;
  top:23%;
  width:220px;
  height:300px;
  transform:translateX(-50%);
  z-index:3;
  pointer-events:none;
}
.booster-opening-card-stack .booster-reveal-card.inside-pack {
  position:absolute;
  left:50%;
  bottom:-50px;
  width:112px;
  height:170px;
  opacity:0;
  transform:translateX(-50%) translateY(85px) rotate(calc((var(--opening-card-index) - 2) * 1.7deg)) scale(.82);
  transition:none;
}
.booster-opening-open.cards-emerging .booster-reveal-card.inside-pack {
  animation:boosterCardEmerge .82s cubic-bezier(.15,.78,.18,1) forwards;
  animation-delay:calc(var(--opening-card-index) * 105ms);
}
/* Fallback sin abs() CSS: posiciones explícitas de los cinco slots. */
.booster-opening-open.cards-emerging .booster-reveal-card.inside-pack:nth-child(1) { --opening-end-x:-90px; --opening-end-y:-112px; }
.booster-opening-open.cards-emerging .booster-reveal-card.inside-pack:nth-child(2) { --opening-end-x:-45px; --opening-end-y:-121px; }
.booster-opening-open.cards-emerging .booster-reveal-card.inside-pack:nth-child(3) { --opening-end-x:0px; --opening-end-y:-128px; }
.booster-opening-open.cards-emerging .booster-reveal-card.inside-pack:nth-child(4) { --opening-end-x:45px; --opening-end-y:-121px; }
.booster-opening-open.cards-emerging .booster-reveal-card.inside-pack:nth-child(5) { --opening-end-x:90px; --opening-end-y:-112px; }
@keyframes boosterCardEmerge {
  0% { opacity:0; transform:translateX(-50%) translateY(90px) rotate(calc((var(--opening-card-index) - 2) * 1.7deg)) scale(.78); }
  28% { opacity:1; }
  100% { opacity:1; transform:translateX(calc(-50% + var(--opening-end-x,0px))) translateY(var(--opening-end-y,-110px)) rotate(calc((var(--opening-card-index) - 2) * 6deg)) scale(.94); }
}
.booster-opening-status { position:relative; z-index:12; color:rgba(239,221,191,.72); font:700 10px/1 system-ui,sans-serif; letter-spacing:.08em; }
.booster-opening-effects { position:absolute; inset:0; pointer-events:none; z-index:0; }
.booster-opening-effects i { position:absolute; left:50%; top:45%; width:4px; height:4px; border-radius:50%; background:#f1d39b; box-shadow:0 0 10px rgba(208,126,255,.72); animation:boosterOpeningSpark 1.8s ease-in-out infinite; }
.booster-opening-effects i:nth-child(1){transform:translate(-150px,-80px);animation-delay:.1s}.booster-opening-effects i:nth-child(2){transform:translate(130px,-110px);animation-delay:.45s}.booster-opening-effects i:nth-child(3){transform:translate(-180px,90px);animation-delay:.8s}.booster-opening-effects i:nth-child(4){transform:translate(175px,70px);animation-delay:1.05s}.booster-opening-effects i:nth-child(5){transform:translate(-80px,-160px);animation-delay:1.3s}.booster-opening-effects i:nth-child(6){transform:translate(85px,145px);animation-delay:1.55s}
@keyframes boosterOpeningSpark { 0%,100%{opacity:0;filter:blur(1px)} 45%{opacity:.9;filter:blur(0);box-shadow:0 0 15px rgba(207,124,255,.9),0 0 26px rgba(255,195,94,.46)} }

/* Cartas reveladas y foil por rareza. */
.booster-reveal-view {
  display:grid;
