.booster-reveal-card-art { position:absolute !important; inset:0 !important; width:100% !important; height:100% !important; }
.booster-reveal-card-copy { min-height:31px; text-align:center; }
.booster-reveal-card-copy strong { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:#efe3cd; font:800 10px/1.2 system-ui,sans-serif; }
.booster-reveal-card-copy span { display:block; margin-top:3px; color:rgba(227,207,174,.62); font:700 8px/1 system-ui,sans-serif; }
@keyframes boosterRevealCardIn { from{opacity:0;transform:translateY(26px) scale(.9)} to{opacity:1;transform:translateY(0) scale(1)} }
.booster-card-rarity-foil,
.booster-card-rarity-flare { position:absolute; inset:0; z-index:14; pointer-events:none; }
.booster-card-rarity-foil {
