}
.booster-card-rarity-flare { opacity:0; box-shadow:inset 0 0 0 1px rgba(255,255,255,.12); }
@keyframes boosterCardFoilSweep { 0%,9%{background-position:145% 0;opacity:0} 23%{opacity:.55} 50%{opacity:.9} 82%{opacity:.35} 93%,100%{background-position:-90% 0;opacity:0} }
.booster-reveal-card.rarity-uncommon .booster-card-rarity-foil { opacity:.38; animation-duration:3.2s; }
.booster-reveal-card.rarity-extraordinary .booster-card-rarity-foil { opacity:.52; animation-duration:2.85s; }
.booster-reveal-card.rarity-singular .booster-card-rarity-foil,
.booster-reveal-card.rarity-infrequent .booster-card-rarity-foil,
.booster-reveal-card.rarity-unusual .booster-card-rarity-foil { opacity:.72; filter:saturate(1.18); }
.booster-reveal-card.rarity-strange .booster-card-rarity-foil,
.booster-reveal-card.rarity-mythic .booster-card-rarity-foil,
.booster-reveal-card.rarity-legendary .booster-card-rarity-foil { opacity:.95; animation-duration:1.65s; filter:saturate(1.55) brightness(1.16); }
.booster-reveal-card.rarity-singular .booster-card-rarity-flare,
.booster-reveal-card.rarity-infrequent .booster-card-rarity-flare,
.booster-reveal-card.rarity-unusual .booster-card-rarity-flare { opacity:.36; box-shadow:inset 0 0 16px rgba(186,112,255,.34),0 0 14px rgba(155,88,224,.20); }
.booster-reveal-card.rarity-strange .booster-card-rarity-flare,
.booster-reveal-card.rarity-mythic .booster-card-rarity-flare,
.booster-reveal-card.rarity-legendary .booster-card-rarity-flare { opacity:.68; box-shadow:inset 0 0 20px rgba(255,211,111,.42),0 0 18px rgba(189,94,255,.38),0 0 34px rgba(70,200,255,.18); animation:boosterRareCardPulse 1.3s ease-in-out infinite alternate; }
.booster-reveal-card.rarity-legendary .booster-card-rarity-flare { opacity:1; box-shadow:inset 0 0 24px rgba(255,231,139,.72),0 0 22px rgba(255,190,79,.72),0 0 50px rgba(203,102,255,.62); animation-duration:.82s; }
@keyframes boosterRareCardPulse { from{filter:brightness(.92);transform:scale(.992)} to{filter:brightness(1.2);transform:scale(1.008)} }
.booster-reveal-actions,.booster-results-actions { position:relative; z-index:6; display:flex; justify-content:center; gap:10px; padding-top:7px; }
.booster-reveal-burst { position:absolute; inset:0; pointer-events:none; opacity:0; }
.booster-reveal-tier-mid .booster-reveal-burst { opacity:.45; background:radial-gradient(circle at 50% 48%,rgba(184,102,255,.15),transparent 40%); animation:boosterTierBurst 1.4s ease-out both; }
.booster-reveal-tier-high .booster-reveal-burst { opacity:.82; background:radial-gradient(circle at 50% 48%,rgba(255,208,102,.22),rgba(181,88,255,.17) 22%,transparent 48%); animation:boosterTierBurstHigh 1.7s ease-out both; }
.booster-reveal-tier-legendary .booster-reveal-burst { opacity:1; background:radial-gradient(circle at 50% 48%,rgba(255,242,168,.38),rgba(255,166,69,.23) 20%,rgba(174,78,255,.22) 38%,transparent 58%); animation:boosterTierLegendary 2.1s ease-out both; }
@keyframes boosterTierBurst { 0%{transform:scale(.55);opacity:0} 32%{opacity:.7} 100%{transform:scale(1.15);opacity:.18} }
@keyframes boosterTierBurstHigh { 0%{transform:scale(.35) rotate(-8deg);filter:brightness(1.8);opacity:0} 28%{opacity:1} 100%{transform:scale(1.22) rotate(5deg);filter:brightness(1);opacity:.22} }
@keyframes boosterTierLegendary { 0%{transform:scale(.25);filter:brightness(2.4) blur(4px);opacity:0} 22%{opacity:1} 54%{filter:brightness(1.5) blur(0)} 100%{transform:scale(1.35);filter:brightness(1);opacity:.30} }

/* Resultado de abrir varios de una sola vez. */
