/* Apertura: el pack abierto funciona como un bolsillo real. La trasera queda
   detrás, el frente delante y las cartas atraviesan el centro hacia arriba. */
.booster-opening-open.is-clearing {
  opacity: 0 !important;
  transform: scale(.94) translateY(16px) !important;
  filter: blur(1px) brightness(.85);
}
.booster-opening-card-stack {
  left: 50% !important;
  top: 50% !important;
  width: 1px !important;
  height: 1px !important;
  transform: none !important;
  /* La capa de vuelo queda por encima del frente una vez que la carta se hace
     visible. En v450 estaba debajo del frente y además opacity/transform estaban
     forzados con !important, por lo que la animación nunca podía mostrarlas. */
  z-index: 6 !important;
  overflow: visible !important;
}
.booster-opening-card-stack .booster-reveal-card.inside-pack {
  position: absolute !important;
  left: 0 !important;
  top: 0 !important;
  bottom: auto !important;
  width: 116px !important;
  height: 174px !important;
  opacity: 0;
  transform: translate(-50%, 62px) scale(.78);
  transform-origin: center center !important;
  animation: none !important;
  pointer-events: none !important;
  z-index: calc(7 + var(--opening-card-index,0)) !important;
}
.booster-opening-open.cards-extracting .booster-reveal-card.inside-pack {
  animation: boosterCardExtractVertical 820ms cubic-bezier(.16,.74,.19,1) var(--booster-extract-delay,0ms) both !important;
}
@keyframes boosterCardExtractVertical {
  0% {
    opacity: 0;
    transform: translate(-50%, 76px) scale(.76);
    filter: brightness(.82);
  }
  12% {
    opacity: 1;
    transform: translate(-50%, 24px) scale(.84);
    filter: brightness(1.04) drop-shadow(0 8px 10px rgba(0,0,0,.42));
  }
  36% {
    opacity: 1;
    transform: translate(-50%, -52px) scale(.91);
  }
  72% {
    opacity: 1;
    transform: translate(-50%, -48cqh) scale(.98);
    filter: brightness(1.05);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -78cqh) scale(1);
    filter: brightness(1.06);
  }
}

/* La presentación final reaparece explícitamente 1→5, de izquierda a derecha. */
