/* ========================================================================== 
   R.O.K Lite v487 · Escala universal + jerarquía de modales
   Base visual: 1600x900. La ventana física solo modifica una escala global.
   ========================================================================== */
:root {
  --rok-design-width: 1600;
  --rok-design-height: 900;
  --rok-app-scale: 1;
  --rok-modal-safe-gap: 12px;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden !important;
}

#rokAppViewport {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #05050b;
  isolation: isolate;
}

#rokAppStage {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 1600px;
  height: 900px;
  transform: translate(-50%, -50%) scale(var(--rok-app-scale, 1));
  transform-origin: 50% 50%;
  container-type: size;
  container-name: rok-app-stage;
  overflow: hidden;
  isolation: isolate;
}

/* El viewport lógico, no el dispositivo físico, manda todos los fullscreen. */
#rokAppStage .game-shell,
#rokAppStage .main-menu-screen,
#rokAppStage .library-builder-screen,
#rokAppStage .spellbooks-collection-screen,
#rokAppStage .booster-store-screen,
#rokAppStage .account-auth-overlay,
#rokAppStage .profile-center-overlay,
#rokAppStage .friends-overlay,
#rokAppStage .online-lobby-overlay,
#rokAppStage .bot-match-mode-modal,
#rokAppStage .match-spellbook-select-modal,
#rokAppStage .spellbook-name-modal,
#rokAppStage .transition-overlay,
#rokAppStage .game-menu-overlay,
#rokAppStage .quick-reaction-modal,
#rokAppStage .opponent-action-notice,
#rokAppStage .opponent-thinking-notice,
#rokAppStage .patch-info-overlay,
#rokAppStage .meta-info-overlay,
#rokAppStage .random-cost-overlay,
#rokAppStage .power-image-preview-overlay,
#rokAppStage .global-fx-layer {
  max-width: 1600px;
  max-height: 900px;
}

/* Zona segura: cada modal padre limita el área disponible para su caja hija. */
#rokAppStage [role="dialog"][aria-modal="true"],
#rokAppStage .card-info-box,
#rokAppStage .random-cost-box,
#rokAppStage .meta-info-box,
#rokAppStage .power-image-preview-box,
#rokAppStage .quick-reaction-modal-shell,
#rokAppStage .opponent-action-notice-shell,
#rokAppStage .patch-info-card {
  box-sizing: border-box;
  min-width: 0;
  min-height: 0;
  max-width: calc(100% - (var(--rok-modal-safe-gap) * 2));
  max-height: calc(100% - (var(--rok-modal-safe-gap) * 2));
  transform-origin: 50% 50%;
  scale: var(--rok-modal-fit-scale, 1);
}

#rokAppStage .card-info-overlay,
#rokAppStage .random-cost-overlay,
#rokAppStage .meta-info-overlay,
#rokAppStage .power-image-preview-overlay,
#rokAppStage .game-menu-overlay,
#rokAppStage .patch-info-overlay,
#rokAppStage .account-auth-overlay,
#rokAppStage .profile-center-overlay,
#rokAppStage .friends-overlay,
#rokAppStage .online-lobby-overlay,
#rokAppStage .bot-match-mode-modal,
#rokAppStage .match-spellbook-select-modal,
#rokAppStage .spellbook-name-modal {
  overflow: hidden !important;
}

