/* ========================================================================== 
   R.O.K Lite v514 · FX viewport + acción de Kaster coherente
   ========================================================================== */
/* Cualquier efecto que use px obtenidos de getBoundingClientRect/viewport debe
   vivir fuera de #rokAppStage. Este selector blinda el layer contra escala,
   límites lógicos y transformaciones heredadas. */
body > #globalFxLayer.global-fx-layer {
  position: fixed !important;
  inset: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  max-width: none !important;
  max-height: none !important;
  transform: none !important;
  scale: 1 !important;
  contain: none !important;
  overflow: visible !important;
  pointer-events: none !important;
  z-index: 99998 !important;
}

/* Habilidad nativa de Kaster disponible: mismo idioma visual de selección
   (foil móvil + burbuja amarilla) aplicado a TODO el bloque de Elemento puro. */
.caster-pure-meter.caster-ability-action-ready {
  position: relative !important;
  isolation: isolate !important;
  overflow: visible !important;
  border-radius: 999px !important;
  filter: drop-shadow(0 0 7px rgba(255,231,135,.42));
}
.caster-pure-meter.caster-ability-action-ready::before {
  content: '';
  position: absolute;
  inset: -2px;
  z-index: 8;
  pointer-events: none;
  border-radius: inherit;
  clip-path: inset(0 round 999px);
  background: linear-gradient(112deg,
    transparent 0%,
    transparent 29%,
    rgba(255,255,255,.12) 38%,
    rgba(255,250,208,.92) 48%,
    rgba(255,255,255,.22) 56%,
    transparent 68%,
    transparent 100%);
  background-size: 260% 100%;
  mix-blend-mode: screen;
  opacity: .92;
  animation: casterPureActionFoilSweep 1.18s ease-in-out infinite;
}
.caster-pure-meter.caster-ability-action-ready::after {
  content: '';
  position: absolute;
  right: -4px;
  top: -5px;
  width: 8px;
  height: 8px;
  z-index: 12;
  pointer-events: none;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.94);
  background: radial-gradient(circle at 35% 30%, #fffdf0 0 25%, #ffe787 44%, #e5aa2e 74%, #6b3c05 100%);
  box-shadow: 0 0 4px rgba(255,255,255,.96), 0 0 10px rgba(255,221,105,.86);
  animation: unitActionReadyIndicatorPulse .9s ease-in-out infinite;
}
@keyframes casterPureActionFoilSweep {
  0% { background-position: 120% 50%; opacity: .28; }
  45% { opacity: .98; }
  100% { background-position: -50% 50%; opacity: .28; }
}


