    0 0 0 1px rgba(255,239,173,.84),
    0 0 10px rgba(255,213,92,.70),
    0 0 19px rgba(255,111,36,.40) !important;
}

body.rok-battle-mode .card-slot.shirahadori-spell-ready > .card.shirahadori-spell-ready-card::after {
  content: '' !important;
  position: absolute !important;
  inset: -30% !important;
  z-index: 14 !important;
  pointer-events: none !important;
  background: linear-gradient(
    115deg,
    transparent 0%,
    transparent 35%,
    rgba(255,255,255,.14) 42%,
    rgba(255,244,188,.58) 49%,
    rgba(255,255,255,.18) 56%,
    transparent 65%,
    transparent 100%
  ) !important;
  transform: translateX(-82%) rotate(4deg);
  mix-blend-mode: screen;
  animation: shirahadoriSpellbookFoilSweep 1.65s ease-in-out infinite !important;
}

@keyframes shirahadoriSpellbookFoilSweep {
  0% { transform: translateX(-82%) rotate(4deg); opacity: .12; }
  42% { opacity: .9; }
  100% { transform: translateX(82%) rotate(4deg); opacity: .12; }
}

