/* --------------------------------------------------------------------------
   Zona de kasteo local: una única coordenada central para TODAS las miniaturas.
   Se usan porcentajes del slot para que el redimensionamiento 1600x900 no
   produzca diferencias entre invocaciones, hechizos o posiciones de cola.
   -------------------------------------------------------------------------- */
body.rok-battle-mode .cast-item {
  --cast-visual-center-x: 50%;
  --cast-visual-center-y: 48%;
  --cast-token-w: 78%;
  --cast-token-h: 82%;
  --cast-spell-size: 72%;
  position: relative !important;
  overflow: visible !important;
}

body.rok-battle-mode .cast-item > .cast-token-image {
  position: absolute !important;
  left: var(--cast-visual-center-x) !important;
  top: var(--cast-visual-center-y) !important;
  width: var(--cast-token-w) !important;
  height: var(--cast-token-h) !important;
  max-width: none !important;
  max-height: none !important;
  transform: translate(-50%, -50%) !important;
  object-fit: contain !important;
  margin: 0 !important;
}

body.rok-battle-mode .cast-item > .cast-spell-composite-mini,
body.rok-battle-mode .cast-item > .cast-spell-art-mini {
  position: absolute !important;
  left: var(--cast-visual-center-x) !important;
  top: var(--cast-visual-center-y) !important;
  width: var(--cast-spell-size) !important;
  height: auto !important;
  aspect-ratio: 1 / 1 !important;
  max-width: none !important;
  max-height: none !important;
  transform: translate(-50%, -50%) !important;
  margin: 0 !important;
}

body.rok-battle-mode .cast-item > .cast-spell-composite-mini .spell-mini-bg,
body.rok-battle-mode .cast-item > .cast-spell-composite-mini .spell-mini-skin {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  transform: none !important;
  margin: 0 !important;
}

/* El contador/ícono de Kasteo utiliza exactamente el mismo anclaje en la
   primera carta activa y en todas las cartas que esperan en cola. */
body.rok-battle-mode .cast-item > .cast-status,
body.rok-battle-mode .cast-item.cast-active > .cast-status,
body.rok-battle-mode .cast-item.cast-waiting > .cast-status {
  position: absolute !important;
  right: -8% !important;
  bottom: -4% !important;
  left: auto !important;
  top: auto !important;
  transform: none !important;
  transform-origin: right bottom !important;
  margin: 0 !important;
  z-index: 40 !important;
}

/* --------------------------------------------------------------------------
   Cola rival: misma lógica relativa. Token y hechizo comparten centro; el
   reloj/contador deja de cambiar de coordenadas entre activo y en espera.
   -------------------------------------------------------------------------- */
.opponent-caster-hud .enemy-mini-cast-item {
  --enemy-cast-center-x: 46%;
  --enemy-cast-center-y: 50%;
  position: relative !important;
  overflow: visible !important;
}

.opponent-caster-hud .enemy-mini-cast-item > .cast-token-image {
