  object-fit: contain !important;
  margin: 0 !important;
}

.opponent-caster-hud .enemy-mini-cast-item > .cast-spell-composite-mini,
.opponent-caster-hud .enemy-mini-cast-item > .cast-spell-art-mini {
  position: absolute !important;
  left: var(--enemy-cast-center-x) !important;
  top: var(--enemy-cast-center-y) !important;
  width: 74% !important;
  height: auto !important;
  aspect-ratio: 1 / 1 !important;
  max-width: none !important;
  max-height: none !important;
  transform: translate(-50%, -50%) !important;
  margin: 0 !important;
}

.opponent-caster-hud .enemy-mini-cast-item > .cast-spell-composite-mini .spell-mini-bg,
.opponent-caster-hud .enemy-mini-cast-item > .cast-spell-composite-mini .spell-mini-skin {
