  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 12px 4px 4px;
}

.adventure-option {
  position: relative;
  width: 100%;
  min-height: 56px;
  box-sizing: border-box;
  padding: 9px 12px 9px 14px;
  border-radius: 12px;
  border: 1px solid rgba(157, 170, 178, .15);
  background:
    linear-gradient(90deg, rgba(11,16,20,.94), rgba(21,25,29,.72));
  color: #d8dee2;
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  transition: transform .14s ease, border-color .14s ease, background .14s ease, filter .14s ease;
}

.adventure-option::before {
  content: '';
  position: absolute;
  left: 0;
  top: 9px;
  bottom: 9px;
  width: 4px;
  border-radius: 999px;
  background: linear-gradient(180deg, var(--option-accent-from, var(--option-accent, rgba(159,179,187,.45))), var(--option-accent-to, var(--option-accent, rgba(159,179,187,.18))));
  opacity: .88;
  box-shadow: 0 0 10px color-mix(in srgb, var(--option-accent-from, var(--option-accent, transparent)) 65%, transparent);
}

.adventure-option:hover,
.adventure-option:focus-visible,
.adventure-option.selected {
  transform: translateX(3px);
  border-color: color-mix(in srgb, var(--option-accent-from, var(--option-accent, #8fa8b2)) 58%, rgba(255,255,255,.2));
  background:
    linear-gradient(90deg,
      color-mix(in srgb, var(--option-accent-from, var(--option-accent, #8fa8b2)) 18%, rgba(8,13,18,.94)),
      color-mix(in srgb, var(--option-accent-to, var(--option-accent, #8fa8b2)) 12%, rgba(15,20,25,.82))
    );
  outline: none;
}

.adventure-option.selected {
  box-shadow: inset 0 0 20px color-mix(in srgb, var(--option-accent-from, var(--option-accent, #8fa8b2)) 9%, transparent);
}

.adventure-option.locked {
  opacity: .58;
}

.adventure-option.locked:hover,
.adventure-option.locked:focus-visible,
.adventure-option.locked.selected {
  opacity: .78;
}

.adventure-option-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.adventure-option-name {
  color: #f0e8d8;
  font: 700 14px/1.15 Cinzel, Georgia, serif;
}

.adventure-option small {
  display: block;
  margin-top: 4px;
  color: rgba(209,219,225,.62);
  font-size: 10px;
  line-height: 1.2;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.adventure-option-badge {
