  font: 700 9px/1 Cinzel, Georgia, serif;
  text-align: center;
  letter-spacing: .08em;
}

.adventure-option.available .adventure-option-badge {
  color: color-mix(in srgb, var(--option-accent-from, #bdefff) 70%, white);
  border-color: color-mix(in srgb, var(--option-accent-from, rgba(88,217,255,.38)) 45%, rgba(255,255,255,.18));
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--option-accent-from, #00FFE4) 18%, rgba(17,102,129,.18)),
    color-mix(in srgb, var(--option-accent-to, #0f617f) 14%, rgba(12,24,30,.16))
