}

.adventure-caster-profile-line {
  display: grid;
  gap: 2px;
}

.adventure-caster-profile-line b {
  color: #f1ddb4;
  font: 700 9px/1.15 Cinzel, Georgia, serif;
  letter-spacing: .08em;
