  color: rgba(218,229,234,.73);
  font-size: 10px;
  line-height: 1.3;
}

.adventure-role-pill-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 4px;
}

.adventure-role-pill b {
