  min-height: 26px;
  max-width: 820px;
  box-sizing: border-box;
  padding: 6px 16px;
  border-radius: 999px;
  border: 1px solid rgba(216,182,107,.24);
  background: rgba(2,7,11,.85);
  color: #e9dcc0;
