@container rok-app-stage (max-width: 1160px) {
  .adventure-view {
    grid-template-columns: 280px minmax(0, 1fr);
  }
  .adventure-water-top {
    grid-template-columns: minmax(300px, .72fr) minmax(390px, 1fr);
  }
  .adventure-zone-info .adventure-primary-btn,
  .adventure-caster-info .adventure-primary-btn {
    min-width: 180px;
  }
}

/* v529 · el marcador vive sobre un lienzo con la misma relación de aspecto
   que cada mapa, evitando que sus coordenadas cambien al escalar la ventana. */
.adventure-map-frame {
  display: grid;
  place-items: center;
}

.adventure-map-canvas {
  position: relative;
  height: 100%;
  max-width: 100%;
  overflow: hidden;
  isolation: isolate;
  box-shadow: 0 0 24px rgba(0,0,0,.32);
}

.adventure-world-map-canvas {
  aspect-ratio: 1448 / 1086;
}

.adventure-water-map-canvas {
  aspect-ratio: 916 / 1717;
}

.adventure-map-canvas > .adventure-map-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: fill;
}

.adventure-world-map-frame .adventure-map-image,
.adventure-water-map-frame .adventure-map-image {
  object-fit: fill;
  object-position: center;
}

@media (max-width: 1560px) {
  .adventure-caster-visual {
    padding-left: 170px;
    padding-right: 160px;
  }
  .adventure-caster-visual > img {
    transform: scale(var(--caster-art-scale, 1.58)) translate(var(--caster-art-shift-x, -7%), var(--caster-art-shift-y, 12%));
  }
  .adventure-caster-stats {
    width: 160px;
  }
  .adventure-caster-domain-panel {
    width: 82px;
    right: 8px;
  }
}


/* ========================================================================== 
   R.O.K Lite v530 · Cancelación universal en HUD de fases
   - Sustituye el aviso flotante sobre la arena.
   - Mouse: clic derecho conserva la cancelación.
   - Táctil/móvil: botón Cancelar la acción ejecuta la misma ruta.
   ========================================================================== */
.quick-reaction-cancel-hint {
  display: none !important;
}

.phase-rail-bottom-controls .cancel-action-button {
  display: none;
  min-height: 42px;
  margin: 0;
  border-color: rgba(218, 118, 94, .62);
