.adventure-prep-vs span:first-child { transform: translateX(2px) rotate(-5deg); }
.adventure-prep-vs span:last-child { transform: translateX(-2px) rotate(5deg); }

.adventure-prep-arena-card,
.adventure-prep-spellbook-card,
.adventure-player-caster-picker {
