  gap: 4px;
}

.adventure-prep-arena-copy strong,
.adventure-prep-spellbook-card strong {
  color: #f0e4ca;
  font: 700 14px/1.15 Cinzel, Georgia, serif;
}

.adventure-prep-arena-copy > span,
.adventure-prep-spellbook-card > div > span {
  color: rgba(210,222,228,.66);
