  line-height: 1.3;
}

.adventure-prep-spellbook-card {
  padding: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.adventure-prep-spellbook-card > div {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.adventure-secondary-btn {
  flex: 0 0 auto;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(108,193,221,.36);
  background: rgba(11,56,72,.62);
  color: #cdebf4;
