}

.adventure-player-caster-picker {
  padding: 8px;
  display: grid;
  gap: 7px;
}

.adventure-player-caster-list {
  display: grid;
  gap: 6px;
}

.adventure-player-caster-option {
  width: 100%;
  min-height: 58px;
  display: grid;
