}

.adventure-player-caster-option.selected {
  border-color: rgba(103,219,255,.55);
  background: rgba(19,83,104,.24);
}

.adventure-player-caster-option img {
  width: 48px;
  height: 48px;
  object-fit: contain;
}

.adventure-player-caster-option span {
  display: grid;
  gap: 3px;
}

.adventure-player-caster-option b {
  color: #efe3cb;
  font: 700 11px/1.1 Cinzel, Georgia, serif;
}

.adventure-player-caster-option small {
  color: rgba(200,217,225,.6);
  font-size: 8px;
}

.adventure-combat-btn {
  justify-self: center;
  min-width: 270px;
  min-height: 48px;
  font-size: 15px;
  letter-spacing: .12em;
}

/* ------------------------------ Ficha modal ------------------------------ */
.adventure-caster-detail-overlay,
.adventure-spellbook-overlay {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: none;
  place-items: center;
  padding: 26px;
  box-sizing: border-box;
  background: rgba(0,0,0,.78);
  backdrop-filter: blur(7px);
}

.adventure-caster-detail-overlay.open,
.adventure-spellbook-overlay.open {
  display: grid;
}

.adventure-caster-detail-shell {
  position: relative;
  width: min(980px, 92%);
  height: min(610px, 88%);
  display: grid;
  grid-template-columns: minmax(360px, .9fr) minmax(420px, 1.1fr);
  overflow: hidden;
  border-radius: 20px;
  border: 1px solid rgba(216,182,107,.34);
  background: radial-gradient(circle at 28% 40%, rgba(49,150,178,.14), transparent 36%), linear-gradient(135deg, #071119, #06090f 65%);
  box-shadow: 0 24px 60px rgba(0,0,0,.68), inset 0 0 0 1px rgba(255,255,255,.02);
}

.adventure-modal-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.15);
  background: rgba(5,8,12,.82);
  color: #eee4d4;
  font-size: 22px;
  cursor: pointer;
}

.adventure-caster-detail-shell > .adventure-modal-close {
  position: absolute;
  right: 14px;
  top: 14px;
  z-index: 4;
}

.adventure-caster-detail-art {
  min-height: 0;
  position: relative;
  display: grid;
  place-items: end center;
  overflow: hidden;
  padding: 22px 8px 0;
  background: linear-gradient(90deg, rgba(6,17,23,.95), rgba(8,18,24,.42));
}

.adventure-caster-detail-art img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center bottom;
  filter: drop-shadow(0 20px 24px rgba(0,0,0,.72));
}

.adventure-caster-detail-copy {
  min-height: 0;
  padding: 30px 28px 24px;
  overflow: auto;
}

.adventure-caster-detail-copy h2 {
  margin: 5px 0 10px;
  color: #f2e5c8;
  font: 700 28px/1.05 Cinzel, Georgia, serif;
}

.adventure-caster-detail-identity {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.adventure-caster-detail-stats {
  margin-top: 16px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 10px;
}

.adventure-detail-stat-section,
.adventure-detail-profile {
  border: 1px solid rgba(113,181,204,.17);
  border-radius: 12px;
  padding: 10px;
  background: rgba(8,22,29,.58);
}

.adventure-detail-stat-section > b {
  display: block;
  margin-bottom: 6px;
  color: #e4cd99;
  font: 700 10px/1 Cinzel, Georgia, serif;
  text-transform: uppercase;
}

.adventure-detail-stat-section > span,
.adventure-detail-profile > span {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 3px 0;
  color: rgba(210,226,234,.77);
  font-size: 10px;
}

.adventure-detail-stat-section em {
  font-style: normal;
}

.adventure-detail-stat-section strong,
.adventure-detail-profile b {
  color: #e9f7fb;
}

.adventure-detail-profile {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 4px 12px;
}

.adventure-detail-profile > span {
  display: grid;
  justify-content: initial;
  gap: 2px;
}

.adventure-caster-detail-dominant-block {
  margin-top: 14px;
  display: grid;
  gap: 7px;
}

/* -------------------------- Biblioteca Aventura -------------------------- */
.adventure-spellbook-shell {
  width: min(1220px, 96%);
  height: min(720px, 92%);
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0,1fr);
  border-radius: 20px;
  border: 1px solid rgba(216,182,107,.32);
  background: linear-gradient(180deg, #0a1016, #05080d);
  box-shadow: 0 24px 60px rgba(0,0,0,.7);
}

.adventure-spellbook-head {
  padding: 16px 18px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid rgba(216,182,107,.17);
}

.adventure-spellbook-head h2 {
  margin: 3px 0 4px;
  color: #f1e5cc;
  font: 700 24px/1.05 Cinzel, Georgia, serif;
}

.adventure-spellbook-head p {
  margin: 0;
  max-width: 760px;
  color: rgba(212,224,230,.68);
  font-size: 11px;
}

.adventure-spellbook-head-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.adventure-spellbook-head-actions > strong {
  color: #c9f0fb;
  font: 700 14px/1 Cinzel, Georgia, serif;
}

.adventure-spellbook-grid {
  min-height: 0;
  overflow: auto;
  padding: 14px;
  display: grid;
  grid-template-columns: repeat(6, minmax(0,1fr));
  align-content: start;
  gap: 10px;
}

.adventure-spellbook-card {
  min-width: 0;
  min-height: 178px;
  display: grid;
  grid-template-rows: 118px auto auto;
  gap: 5px;
  padding: 7px;
  border-radius: 12px;
  border: 1px solid rgba(105,173,197,.17);
  background: rgba(9,18,24,.82);
  color: inherit;
  text-align: left;
}

.adventure-spellbook-card.unlocked {
  cursor: pointer;
}

.adventure-spellbook-card.selected {
  border-color: rgba(86,217,255,.65);
  box-shadow: inset 0 0 18px rgba(56,178,218,.12);
}

.adventure-spellbook-card.locked {
  opacity: .36;
  filter: grayscale(.85);
}

.adventure-spellbook-card-art {
  overflow: hidden;
  border-radius: 8px;
  background: rgba(0,0,0,.3);
}

.adventure-spellbook-card-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.adventure-spellbook-card b {
  overflow: hidden;
  color: #e9dfca;
  font: 700 10px/1.15 Cinzel, Georgia, serif;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.adventure-spellbook-card small {
  color: rgba(190,211,220,.6);
  font-size: 8px;
}

/* ----------------------- Presentación cinematográfica -------------------- */
.adventure-battle-intro {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: none;
  overflow: hidden;
  background: #020408;
  color: white;
}

.adventure-battle-intro[aria-hidden="false"] {
  display: block;
}

.adventure-intro-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 20% 50%, rgba(27,125,161,.2), transparent 34%),
    radial-gradient(circle at 80% 50%, rgba(110,70,42,.17), transparent 34%),
    linear-gradient(90deg, #07131b, #06070b 47%, #06070b 53%, #15100b);
}

.adventure-intro-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 49.7%, rgba(235,204,130,.45) 50%, transparent 50.3%);
  opacity: 0;
  transition: opacity .4s ease 1.2s;
}

.adventure-battle-intro.active .adventure-intro-bg::after {
  opacity: 1;
}

.adventure-intro-side {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
  overflow: hidden;
}

.adventure-intro-rival { left: 0; }
.adventure-intro-player { right: 0; }
.adventure-intro-side::before,
.adventure-intro-side::after {
  content: '';
  position: absolute;
  inset: -8% -10%;
  pointer-events: none;
}

.adventure-intro-side::before {
  z-index: 1;
  opacity: 0;
  filter: blur(12px);
}

.adventure-intro-side::after {
  z-index: 2;
  opacity: 0;
  filter: blur(28px);
  mix-blend-mode: screen;
}

.adventure-intro-rival::before {
  background:
    linear-gradient(100deg, transparent 6%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 78%, transparent) 22%, transparent 38%, color-mix(in srgb, var(--intro-color-2, #c9b86d) 76%, transparent) 52%, transparent 68%, color-mix(in srgb, var(--intro-color-3, #7a66f4) 74%, transparent) 84%, transparent 100%),
    radial-gradient(circle at 18% 32%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 42%, transparent) 0, transparent 42%),
    radial-gradient(circle at 34% 72%, color-mix(in srgb, var(--intro-color-2, #c9b86d) 38%, transparent) 0, transparent 36%);
  transform: translateX(-22%) skewX(-12deg);
}

.adventure-intro-player::before {
  background:
    linear-gradient(260deg, transparent 6%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 78%, transparent) 22%, transparent 38%, color-mix(in srgb, var(--intro-color-2, #c9b86d) 76%, transparent) 52%, transparent 68%, color-mix(in srgb, var(--intro-color-3, #7a66f4) 74%, transparent) 84%, transparent 100%),
    radial-gradient(circle at 82% 32%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 42%, transparent) 0, transparent 42%),
    radial-gradient(circle at 66% 72%, color-mix(in srgb, var(--intro-color-2, #c9b86d) 38%, transparent) 0, transparent 36%);
  transform: translateX(22%) skewX(12deg);
}

.adventure-intro-rival::after {
  background: radial-gradient(circle at 24% 50%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 28%, transparent) 0, transparent 34%), radial-gradient(circle at 48% 48%, color-mix(in srgb, var(--intro-color-2, #c9b86d) 26%, transparent) 0, transparent 30%), radial-gradient(circle at 70% 46%, color-mix(in srgb, var(--intro-color-3, #7a66f4) 24%, transparent) 0, transparent 28%);
}

.adventure-intro-player::after {
  background: radial-gradient(circle at 76% 50%, color-mix(in srgb, var(--intro-color-1, #5fd8ff) 28%, transparent) 0, transparent 34%), radial-gradient(circle at 52% 48%, color-mix(in srgb, var(--intro-color-2, #c9b86d) 26%, transparent) 0, transparent 30%), radial-gradient(circle at 30% 46%, color-mix(in srgb, var(--intro-color-3, #7a66f4) 24%, transparent) 0, transparent 28%);
}

.adventure-battle-intro.active .adventure-intro-rival::before {
  animation: adventureIntroFluxLeft .9s cubic-bezier(.16,.8,.2,1) .16s forwards;
}

.adventure-battle-intro.active .adventure-intro-player::before {
  animation: adventureIntroFluxRight .9s cubic-bezier(.16,.8,.2,1) 1.3s forwards;
}

.adventure-battle-intro.active .adventure-intro-rival::after {
  animation: adventureIntroGlowLeft 1.1s ease .22s forwards;
}

.adventure-battle-intro.active .adventure-intro-player::after {
  animation: adventureIntroGlowRight 1.1s ease 1.36s forwards;
}

@keyframes adventureIntroFluxLeft {
  0% { opacity: 0; transform: translateX(-32%) skewX(-12deg) scale(1.08); }
  100% { opacity: .68; transform: translateX(0) skewX(-12deg) scale(1); }
}

@keyframes adventureIntroFluxRight {
  0% { opacity: 0; transform: translateX(32%) skewX(12deg) scale(1.08); }
  100% { opacity: .68; transform: translateX(0) skewX(12deg) scale(1); }
}

@keyframes adventureIntroGlowLeft {
  0% { opacity: 0; transform: translateX(-18%); }
  100% { opacity: .82; transform: translateX(0); }
}

@keyframes adventureIntroGlowRight {
  0% { opacity: 0; transform: translateX(18%); }
  100% { opacity: .82; transform: translateX(0); }
}

.adventure-intro-caster {
  position: absolute;
  bottom: -5%;
  width: 73%;
  height: 88%;
  object-fit: contain;
  object-position: center bottom;
  filter: drop-shadow(0 24px 30px rgba(0,0,0,.8));
  opacity: 0;
}

.adventure-intro-rival .adventure-intro-caster {
  left: 22.25%;
  transform: translateX(-35%);
}

.adventure-intro-player .adventure-intro-caster {
  right: 21.25%;
  transform: translateX(35%);
}

.adventure-battle-intro.active .adventure-intro-rival .adventure-intro-caster {
  animation: adventureIntroCasterLeft .55s cubic-bezier(.16,.8,.2,1) .15s forwards;
}

.adventure-battle-intro.active .adventure-intro-player .adventure-intro-caster {
  animation: adventureIntroCasterRight .55s cubic-bezier(.16,.8,.2,1) 1.3s forwards;
}

@keyframes adventureIntroCasterLeft {
  to { opacity: 1; transform: translateX(0); }
}

@keyframes adventureIntroCasterRight {
  to { opacity: 1; transform: translateX(0); }
}

.adventure-intro-name {
  position: absolute;
  z-index: 5;
  top: 12%;
  max-width: 70%;
  opacity: 0;
}

.adventure-intro-rival .adventure-intro-name {
  left: 5%;
  transform: translateX(-30px);
}

.adventure-intro-player .adventure-intro-name {
  right: 5%;
  text-align: right;
  transform: translateX(30px);
}

.adventure-battle-intro.active .adventure-intro-rival .adventure-intro-name {
  animation: adventureIntroName .4s ease .55s forwards;
}

.adventure-battle-intro.active .adventure-intro-player .adventure-intro-name {
  animation: adventureIntroName .4s ease 1.65s forwards;
}

@keyframes adventureIntroName {
  to { opacity: 1; transform: translateX(0); }
}

.adventure-intro-name small {
  display: block;
  color: #b8e8f6;
  font: 700 12px/1 Cinzel, Georgia, serif;
  letter-spacing: .18em;
}

.adventure-intro-name strong {
  display: block;
  margin-top: 6px;
  color: #f3e6c8;
  font: 900 30px/1.02 Cinzel, Georgia, serif;
  text-shadow: 0 4px 14px rgba(0,0,0,.85);
}

.adventure-intro-vs {
  position: absolute;
  z-index: 20;
  left: 50%;
  top: 44%;
  transform: translate(-50%,-50%);
  display: flex;
  color: #f5ddb0;
  font: 900 94px/.8 Cinzel, Georgia, serif;
  text-shadow: 0 0 24px rgba(246,201,105,.45), 0 8px 18px #000;
  pointer-events: none;
}

.adventure-intro-vs span {
  opacity: 0;
  transform: scale(2.6) rotate(-12deg);
}

.adventure-battle-intro.active .intro-v {
  animation: adventureVsHit .28s cubic-bezier(.1,.85,.2,1.2) .9s forwards;
}

.adventure-battle-intro.active .intro-s {
  animation: adventureVsHit .28s cubic-bezier(.1,.85,.2,1.2) 1.1s forwards;
}

@keyframes adventureVsHit {
  70% { opacity: 1; transform: scale(.84) rotate(4deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}

.adventure-intro-dominants {
  position: absolute;
  z-index: 9;
  left: 6%;
  right: 6%;
  bottom: 6%;
  display: flex;
  justify-content: center;
  gap: 18px;
  pointer-events: none;
}

.adventure-intro-quality-node {
  --intro-index: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  min-width: 88px;
  opacity: 0;
  filter: drop-shadow(0 12px 16px rgba(0,0,0,.76));
}

.adventure-intro-quality-node .adventure-quality-icon {
  width: 72px;
  height: 72px;
  border-radius: 24px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--quality-tint) 38%, rgba(255,255,255,.16)), rgba(7,12,18,.94));
  border: 1px solid color-mix(in srgb, var(--quality-tint) 70%, rgba(255,255,255,.18));
  box-shadow: 0 0 0 1px rgba(255,255,255,.06) inset, 0 14px 30px rgba(0,0,0,.42), 0 0 28px color-mix(in srgb, var(--quality-tint) 32%, transparent);
}

.adventure-intro-quality-node .adventure-quality-icon img {
  width: 58%;
  height: 58%;
  object-fit: contain;
}

.adventure-intro-quality-node > span {
  display: block;
  color: #d9ecf7;
  font: 700 12px/1.1 Cinzel, Georgia, serif;
  text-align: center;
  text-shadow: 0 3px 10px rgba(0,0,0,.8);
}

.adventure-battle-intro.active .adventure-intro-rival .adventure-intro-quality-node {
  animation: adventureIntroQualityRise .46s cubic-bezier(.12,.76,.16,1) calc(.95s + var(--intro-index) * .12s) forwards;
}

.adventure-battle-intro.active .adventure-intro-player .adventure-intro-quality-node {
  animation: adventureIntroQualityRise .46s cubic-bezier(.12,.76,.16,1) calc(1.85s + var(--intro-index) * .12s) forwards;
}

@keyframes adventureIntroQualityRise {
  0% { opacity: 0; transform: translateY(42px) scale(.72); filter: blur(6px) drop-shadow(0 12px 16px rgba(0,0,0,.76)); }
  70% { opacity: 1; transform: translateY(-4px) scale(1.04); filter: blur(0) drop-shadow(0 12px 16px rgba(0,0,0,.76)); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0) drop-shadow(0 12px 16px rgba(0,0,0,.76)); }
}

.adventure-intro-champion {
  position: absolute;
  bottom: 8%;
  width: 42%;
  height: 60%;
  object-fit: contain;
  object-position: center bottom;
  opacity: 0;
  pointer-events: none;
  z-index: 3;
  filter: drop-shadow(0 20px 26px rgba(0,0,0,.6));
}

.adventure-intro-champion.visible {
  opacity: 0;
}

.adventure-intro-rival .adventure-intro-champion {
  left: 19.3%;
  transform: translateX(-34%) scale(.9);
}

.adventure-intro-player .adventure-intro-champion {
  right: 17.3%;
  transform: translateX(34%) scale(.9);
}

.adventure-battle-intro.active .adventure-intro-rival .adventure-intro-champion.visible {
  animation: adventureIntroChampionLeft .52s cubic-bezier(.16,.8,.2,1) .34s forwards;
}

.adventure-battle-intro.active .adventure-intro-player .adventure-intro-champion.visible {
  animation: adventureIntroChampionRight .52s cubic-bezier(.16,.8,.2,1) 1.48s forwards;
}

@keyframes adventureIntroChampionLeft {
  to { opacity: 1; transform: translateX(0) scale(1); }
}

@keyframes adventureIntroChampionRight {
  to { opacity: 1; transform: translateX(0) scale(1); }
}

.adventure-intro-countdown {
  position: absolute;
  z-index: 30;
  left: 50%;
  top: 67%;
  transform: translate(-50%,-50%);
  color: #fff0c8;
  font: 900 160px/.8 Cinzel, Georgia, serif;
  text-shadow: 0 0 34px rgba(255,210,111,.58), 0 8px 22px #000;
  opacity: 0;
}

.adventure-battle-intro.counting .adventure-intro-countdown:not(:empty) {
  opacity: 1;
  animation: adventureCountPulse .7s ease infinite;
}

@keyframes adventureCountPulse {
  0% { transform: translate(-50%,-50%) scale(1.55); opacity: 0; }
  28% { opacity: 1; }
  100% { transform: translate(-50%,-50%) scale(.72); opacity: 0; }
}

.adventure-intro-combat-flyer {
  position: absolute;
  z-index: 40;
  left: 0;
  right: 0;
  top: 50%;
  transform: translateY(-50%) scaleY(.3);
  padding: 22px 0;
  border-top: 1px solid rgba(255,223,151,.42);
  border-bottom: 1px solid rgba(255,223,151,.42);
  background: linear-gradient(90deg, transparent, rgba(7,13,19,.94) 18%, rgba(49,37,21,.94) 50%, rgba(7,13,19,.94) 82%, transparent);
  color: #ffe9b8;
  font: 900 72px/1 Cinzel, Georgia, serif;
  letter-spacing: .18em;
  text-align: center;
  text-shadow: 0 0 20px rgba(255,207,104,.5), 0 5px 12px #000;
  opacity: 0;
  pointer-events: none;
}

.adventure-battle-intro.combat-ready .adventure-intro-combat-flyer {
  animation: adventureCombatFlyer .75s cubic-bezier(.15,.78,.16,1) forwards;
}

@keyframes adventureCombatFlyer {
  0% { opacity: 0; transform: translateY(-50%) scaleX(.2) scaleY(.3); }
  36% { opacity: 1; transform: translateY(-50%) scaleX(1.05) scaleY(1); }
  100% { opacity: 1; transform: translateY(-50%) scaleX(1) scaleY(1); }
}

@container rok-app-stage (max-width: 1180px) {
  .adventure-prep-versus-grid {
    grid-template-columns: minmax(250px,1fr) minmax(240px,.7fr) minmax(250px,1fr);
  }
  .adventure-spellbook-grid {
    grid-template-columns: repeat(5,minmax(0,1fr));
  }
}

/* v5.5.272 · Revancha PvP coordinada y estado de espera. */
.match-rematch-status {
