/* =========================================================
   ROK v553 · Etapa 2 · Guardia de inactividad
   Aviso compacto anclado a la parte inferior de la arena.
   ========================================================= */
.inactivity-prompt {
  position: absolute;
  left: 50%;
  bottom: 14px;
  width: min(560px, 72%);
  transform: translate(-50%, 18px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  z-index: 18750;
  transition: opacity 160ms ease, transform 160ms ease, visibility 0s linear 160ms;
}

.inactivity-prompt.visible {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
  transition-delay: 0s;
}

.inactivity-prompt-shell {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  min-height: 64px;
  padding: 10px 12px 13px 15px;
  overflow: hidden;
  border: 1px solid rgba(244, 215, 129, .58);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(18, 15, 24, .96), rgba(9, 8, 14, .96)),
    radial-gradient(circle at 18% 0%, rgba(246, 197, 88, .14), transparent 42%);
  box-shadow: 0 13px 34px rgba(0, 0, 0, .5), inset 0 0 24px rgba(255, 220, 122, .04);
  backdrop-filter: blur(8px);
  pointer-events: auto;
}

.inactivity-prompt-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.inactivity-prompt-copy strong {
  color: #f5d47d;
  font-size: 10px;
  letter-spacing: .17em;
  line-height: 1.1;
}

.inactivity-prompt-copy span {
  color: rgba(255, 255, 255, .92);
  font-size: 12px;
  line-height: 1.2;
  white-space: normal;
}

.inactivity-prompt-countdown {
  display: flex;
  align-items: center;
  gap: 7px;
  color: rgba(255,255,255,.68);
  font-size: 9px;
  white-space: nowrap;
}

.inactivity-prompt-countdown b {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border: 1px solid rgba(244, 215, 129, .48);
  border-radius: 50%;
  color: #fff1bd;
  background: rgba(244, 195, 76, .08);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
}

#inactivityPromptContinueBtn {
  min-width: 56px;
  height: 34px;
  padding: 0 14px;
  border: 1px solid rgba(246, 218, 137, .72);
  border-radius: 8px;
  color: #19120a;
  background: linear-gradient(180deg, #f7dc8c, #c99642);
  box-shadow: inset 0 1px rgba(255,255,255,.55), 0 5px 14px rgba(0,0,0,.32);
  font-weight: 800;
  text-transform: uppercase;
  cursor: pointer;
}

#inactivityPromptContinueBtn:hover,
#inactivityPromptContinueBtn:focus-visible {
  filter: brightness(1.08);
  outline: 1px solid rgba(255, 241, 188, .75);
  outline-offset: 2px;
}

.inactivity-prompt-track {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3px;
  background: rgba(255,255,255,.07);
}

.inactivity-prompt-track > span {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, rgba(185,126,44,.9), rgba(255,226,133,.98));
  transition: width 220ms linear;
}

body.rok-menu-mode .inactivity-prompt,
body.rok-library-mode .inactivity-prompt,
body.rok-spellbooks-mode .inactivity-prompt {
  display: none !important;
}

@media (max-width: 900px) {
  .inactivity-prompt {
    width: min(520px, 88%);
    bottom: 9px;
  }
  .inactivity-prompt-shell {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px 10px;
  }
  .inactivity-prompt-countdown {
    grid-column: 1;
    grid-row: 2;
    justify-self: start;
  }
  #inactivityPromptContinueBtn {
    grid-column: 2;
    grid-row: 1 / span 2;
  }
}


