}
.main-menu-buttons {
  grid-template-columns: repeat(3, minmax(0, var(--rok-main-menu-btn-w-stage4))) !important;
  width: min(calc((var(--rok-main-menu-btn-w-stage4) * 3) + (var(--rok-main-menu-btn-gap-x) * 2)), 92cqw) !important;
}
.main-menu-btn-emoji {
  display: block;
  font-size: 34px;
  line-height: 1;
  filter: grayscale(.2) drop-shadow(0 0 4px rgba(255,235,186,.35));
}

/* El lobby de preparación gana altura útil para que los selectores vivan en él. */
.online-friends-lobby-card {
  width: min(1080px, calc(100cqw - 32px));
  max-height: min(882px, calc(100cqh - 18px));
  padding: 24px 30px 22px;
  overflow: hidden;
}
.online-room-view {
  min-height: 620px;
  display: grid;
  grid-template-rows: auto auto minmax(0,1fr) auto;
  gap: 10px;
}
.online-room-carousel-grid {
  min-height: 0;
  grid-template-columns: minmax(0,1fr) minmax(0,1fr);
  gap: 16px;
  margin-top: 2px;
}
.online-room-carousel-grid .online-room-setup-panel {
  min-height: 340px;
  padding: 14px;
  overflow: hidden;
  align-content: stretch;
}
.online-setup-panel-head {
  min-width: 0;
  display: grid;
  gap: 5px;
}
.online-setup-panel-head > strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #f2f8ff;
  font: 900 14px/1.15 system-ui,sans-serif;
}

/* Spellbook: una tarjeta completa y un borde visible de la anterior/siguiente. */
.online-spellbook-carousel {
  min-height: 0;
  display: grid;
  grid-template-rows: 30px minmax(0,1fr) 30px;
  gap: 5px;
  align-items: stretch;
}
.online-spellbook-carousel-viewport {
  position: relative;
  height: 244px;
  min-height: 244px;
  overflow: hidden;
  border: 1px solid rgba(169,126,220,.14);
  border-radius: 13px;
  background: radial-gradient(circle at 50% 50%,rgba(118,65,170,.09),transparent 58%),rgba(0,0,0,.18);
}
.online-spellbook-carousel-card {
  position: absolute !important;
  left: 12px;
  right: 12px;
  width: calc(100% - 24px) !important;
  min-height: 126px !important;
  margin: 0 !important;
  transition: top .22s ease, transform .22s ease, opacity .22s ease, filter .22s ease !important;
  pointer-events: none !important;
}
.online-spellbook-carousel-card.is-current {
  top: 59px;
  z-index: 3;
  opacity: 1;
  transform: scale(1) !important;
  border-color: rgba(197,140,255,.64);
  box-shadow: 0 0 0 1px rgba(155,77,255,.20),0 0 20px rgba(155,77,255,.16);
}
.online-spellbook-carousel-card.is-previous {
  top: -78px;
  z-index: 1;
  opacity: .34;
  transform: scale(.92) !important;
  filter: brightness(.68) saturate(.75);
}
.online-spellbook-carousel-card.is-next {
  top: 196px;
  z-index: 1;
  opacity: .34;
  transform: scale(.92) !important;
  filter: brightness(.68) saturate(.75);
}
.online-carousel-empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 22px;
  color: rgba(225,238,248,.55);
  text-align: center;
  font: 750 11px/1.45 system-ui,sans-serif;
}
.online-carousel-arrow {
  min-width: 38px;
  min-height: 38px;
  border: 1px solid rgba(148,214,255,.28);
  border-radius: 10px;
  background: linear-gradient(180deg,rgba(31,86,129,.95),rgba(8,31,52,.98));
  color: #eaf8ff;
  font: 950 27px/1 system-ui,sans-serif;
  cursor: pointer;
  box-shadow: inset 0 0 13px rgba(255,255,255,.025);
}
.online-carousel-arrow-vertical {
  width: 100%;
  min-height: 30px;
  height: 30px;
  font-size: 22px;
}
.online-carousel-arrow:not(:disabled):hover,
.online-carousel-arrow:not(:disabled):focus-visible {
  border-color: rgba(116,211,255,.66);
  filter: brightness(1.14);
}
.online-carousel-arrow:disabled { opacity:.3; cursor:not-allowed; }

