  content: '';
  position: absolute;
  top: 50%;
  width: var(--comet-core, 4px);
  height: var(--comet-core, 4px);
  border-radius: 50%;
  background: radial-gradient(circle,
    rgba(255,255,255,.98) 0 20%,
    currentColor 36% 62%,
    color-mix(in srgb, currentColor 24%, transparent) 76%,
    transparent 100%);
