}

.adventure-intro-comet.left {
  left: -22%;
  background: linear-gradient(90deg,
    transparent 0%,
    color-mix(in srgb, currentColor 8%, transparent) 12%,
    color-mix(in srgb, currentColor 28%, transparent) 48%,
    color-mix(in srgb, currentColor 72%, transparent) 84%,
    currentColor 100%);
  animation: introCometLeft var(--comet-duration, 1500ms) linear forwards;
}

.adventure-intro-comet.left::before {
  right: calc(var(--comet-core, 4px) * -0.12);
  transform: translateY(-50%);
}

.adventure-intro-comet.right {
  right: -22%;
  background: linear-gradient(270deg,
    transparent 0%,
    color-mix(in srgb, currentColor 8%, transparent) 12%,
    color-mix(in srgb, currentColor 28%, transparent) 48%,
    color-mix(in srgb, currentColor 72%, transparent) 84%,
    currentColor 100%);
  animation: introCometRight var(--comet-duration, 1500ms) linear forwards;
