/* === v560 · Kiara / Farolera del Umbral · Farol Enlazado === */
.farol-portal-fx-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 176;
  overflow: visible;
}

.farol-portal-fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  --farol-portal-color: #00FFE4;
}

.farol-portal-circle,
.farol-portal-lantern {
  position: absolute;
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  pointer-events: none;
}

.farol-portal-circle {
  width: clamp(58px, 7.2%, 104px);
  aspect-ratio: 1;
  opacity: .82;
  z-index: 2;
  filter: drop-shadow(0 0 5px var(--farol-portal-color)) drop-shadow(0 0 13px var(--farol-portal-color));
}

.farol-portal-circle::before,
.farol-portal-circle::after {
  content: '';
  position: absolute;
  inset: 5%;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--farol-portal-color) 82%, white 18%);
  box-shadow: 0 0 8px var(--farol-portal-color), inset 0 0 8px color-mix(in srgb, var(--farol-portal-color) 70%, transparent);
  animation: farolPortalPulse 1.65s ease-in-out infinite;
}

.farol-portal-circle::after {
  inset: 18%;
  animation-delay: -.72s;
}

.farol-portal-circle img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: .72;
  mix-blend-mode: screen;
  animation: farolPortalSpin 9s linear infinite;
}

.farol-portal-fx.pending .farol-portal-circle {
  opacity: .56;
}

.farol-portal-lantern {
  width: clamp(24px, 2.9%, 44px);
  z-index: 4;
  filter: drop-shadow(0 0 4px #fff) drop-shadow(0 0 11px var(--farol-portal-color));
  animation: farolLanternFloat 1.9s ease-in-out infinite;
}

.farol-portal-lantern::before {
  content: '';
  position: absolute;
  width: 165%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--farol-portal-color) 34%, transparent) 0 22%, transparent 64%);
  box-shadow: 0 0 16px var(--farol-portal-color);
  opacity: .75;
}

.farol-portal-lantern img {
  position: relative;
  width: 100%;
  height: auto;
  object-fit: contain;
  z-index: 2;
}

.farol-portal-tether {
  position: absolute;
  height: 4px;
  transform-origin: 0 50%;
  border-radius: 999px;
  z-index: 1;
  opacity: .8;
  background:
    repeating-linear-gradient(90deg,
      color-mix(in srgb, var(--farol-portal-color) 94%, white 6%) 0 10px,
      transparent 10px 15px,
      color-mix(in srgb, var(--farol-portal-color) 72%, white 28%) 15px 21px,
      transparent 21px 27px);
  box-shadow: 0 0 4px var(--farol-portal-color), 0 0 10px var(--farol-portal-color);
  animation: farolTetherFlow .72s linear infinite;
}

.farol-lantern-target {
  border-color: var(--dom-water-primary, #00FFE4) !important;
  box-shadow: inset 0 0 0 2px rgba(0,255,228,.25), 0 0 12px rgba(0,255,228,.72) !important;
}

.farol-lantern-target-glyph {
  display: grid;
  place-items: center;
  width: 44%;
  aspect-ratio: 1;
  margin: auto;
  border-radius: 50%;
  color: #fff;
  font-size: clamp(12px, 1.2vw, 20px);
  text-shadow: 0 0 7px #00FFE4;
  background: rgba(0, 55, 56, .66);
  border: 1px solid rgba(0,255,228,.88);
}

@keyframes farolPortalSpin { to { transform: rotate(360deg); } }
@keyframes farolPortalPulse { 0%,100% { opacity:.5; transform:scale(.92); } 50% { opacity:1; transform:scale(1.06); } }
@keyframes farolLanternFloat { 0%,100% { transform:translate(-50%,-50%) translateY(-2px); } 50% { transform:translate(-50%,-50%) translateY(4px); } }
@keyframes farolTetherFlow { to { background-position: 27px 0; } }

/* =========================================================
   ROK v561 · Farolera del Umbral · Farol Enlazado 2 etapas
   + proyectil mágico base para ataques Magia
   ========================================================= */

/* El círculo solicitado es 30% menor que la primera integración. */
.farol-portal-circle {
  width: clamp(41px, 5.05%, 73px) !important;
}

/* Vuelo físico del farol durante la segunda activación. */
.farol-lantern-throw-fx {
  position: absolute;
  width: clamp(24px, 2.9%, 44px);
  z-index: 52055;
  pointer-events: none;
  display: grid;
  place-items: center;
