/* =========================================================
   ROK v563 · Farolera del Umbral · FX de teletransporte real
   Etapa 2/4
   ========================================================= */

/* Al activarse el umbral el círculo acelera claramente sin reconstruir el nodo. */
.farol-portal-circle.farol-portal-teleporting img {
  animation-duration: .62s !important;
  filter: brightness(1.38) saturate(1.25);
}

.farol-portal-circle.farol-portal-teleporting::before,
.farol-portal-circle.farol-portal-teleporting::after {
  animation-duration: .42s !important;
  box-shadow:
    0 0 12px var(--farol-portal-color),
    0 0 25px color-mix(in srgb, var(--farol-portal-color) 78%, transparent),
    inset 0 0 12px color-mix(in srgb, var(--farol-portal-color) 75%, transparent);
}

/* La ficha se desmaterializa en el círculo. Se anima el contenedor completo
   para que imagen + hitbox desaparezcan juntos mientras dura el bloqueo. */
.unit.invocation.farol-teleport-token-out {
  pointer-events: none !important;
  animation: farolTeleportTokenOut .27s cubic-bezier(.4,0,.8,.2) forwards !important;
}

/* La ficha recién renderizada en destino aparece desde el núcleo del umbral. */
.unit.invocation.farol-teleport-token-in {
  pointer-events: none !important;
  animation: farolTeleportTokenIn .42s cubic-bezier(.15,.8,.25,1) both !important;
}

.farol-teleport-burst {
  position: absolute;
  width: clamp(42px, 5.2%, 78px);
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 52070;
  display: grid;
  place-items: center;
  color: var(--farol-portal-color, #00FFE4);
  filter: drop-shadow(0 0 7px currentColor) drop-shadow(0 0 16px currentColor);
  animation: farolTeleportBurstFade .72s ease-out both;
}

.farol-teleport-burst > span,
.farol-teleport-burst > i,
.farol-teleport-burst > b {
  position: absolute;
  inset: 12%;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, currentColor 84%, white 16%);
  box-shadow: 0 0 10px currentColor, inset 0 0 8px currentColor;
}

.farol-teleport-burst > span {
  animation: farolTeleportRingA .64s ease-out both;
}
.farol-teleport-burst > i {
  inset: 27%;
  border-style: dashed;
  animation: farolTeleportRingB .68s ease-out both;
}
.farol-teleport-burst > b {
  inset: 39%;
  border: 0;
  background: radial-gradient(circle, #fff 0 12%, currentColor 24% 42%, transparent 70%);
  animation: farolTeleportCore .52s ease-out both;
}

.farol-teleport-burst-destination {
  animation-delay: .02s;
}

@keyframes farolTeleportTokenOut {
  0%   { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: none; }
  48%  { opacity: .72; transform: translate(-50%, -50%) scale(.88); filter: brightness(1.6) drop-shadow(0 0 9px var(--dom-water-primary, #00FFE4)); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(.18) rotate(10deg); filter: blur(4px) brightness(2.1); }
}

@keyframes farolTeleportTokenIn {
  0%   { opacity: 0; transform: translate(-50%, -50%) scale(.15) rotate(-8deg); filter: blur(5px) brightness(2.2); }
  55%  { opacity: .84; transform: translate(-50%, -50%) scale(1.12); filter: brightness(1.45) drop-shadow(0 0 10px var(--dom-water-primary, #00FFE4)); }
  100% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: none; }
}

@keyframes farolTeleportBurstFade {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.55); }
  20% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.32); }
}

@keyframes farolTeleportRingA {
  from { transform: rotate(0deg) scale(.55); opacity: 1; }
  to   { transform: rotate(220deg) scale(1.18); opacity: 0; }
}
@keyframes farolTeleportRingB {
  from { transform: rotate(0deg) scale(.72); opacity: .95; }
  to   { transform: rotate(-260deg) scale(1.42); opacity: 0; }
}
@keyframes farolTeleportCore {
  0% { opacity: 0; transform: scale(.2); }
  35% { opacity: 1; transform: scale(1.18); }
  100% { opacity: 0; transform: scale(.35); }
}

