.token-tuning-selected small {
  color: rgba(197,255,248,.5);
  font-size: 8px;
  letter-spacing: .1em;
}

.token-tuning-selected strong {
  overflow: hidden;
  font-size: 11px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.token-tuning-controls > label {
  display: grid;
