/* =========================================================
   R.O.K v567 · VS editor universal en vivo + profundidad sin transparencia
   ========================================================= */
/* La invocación destacada termina totalmente opaca. La separación visual
   respecto al Kaster se obtiene por profundidad, no lavando el sprite. */
.adventure-battle-intro.active .adventure-intro-rival .adventure-intro-champion.visible,
.online-versus-intro.active .adventure-intro-rival .adventure-intro-champion.visible,
.adventure-battle-intro.active .adventure-intro-player .adventure-intro-champion.visible,
.online-versus-intro.active .adventure-intro-player .adventure-intro-champion.visible {
  --vs-champion-final-opacity: 1;
}

/* Sombra paralela con lógica Dominion. Cada mitad ya recibe --intro-color-1
   desde JS, por lo que Agua/Tierra/etc. conservan su paleta canónica. */
.adventure-intro-rival .adventure-intro-caster {
  filter:
    drop-shadow(0 24px 30px rgba(0,0,0,.78))
    drop-shadow(-15px 9px 8px color-mix(in srgb, var(--intro-color-1, var(--domain-agua-dominant)) 54%, transparent)) !important;
}
.adventure-intro-player .adventure-intro-caster {
  filter:
    drop-shadow(0 24px 30px rgba(0,0,0,.78))
    drop-shadow(15px 9px 8px color-mix(in srgb, var(--intro-color-1, var(--domain-tierra-dominant)) 54%, transparent)) !important;
}


