  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 7px 6px 6px;
  border: 1px solid color-mix(in srgb, var(--rt-resource-color) 42%, rgba(255,255,255,.14));
