  align-items: center;
  justify-content: space-between;
  gap: 4px;
}
.rt-resource-identity {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
}
.rt-resource-identity > img {
  width: 18px;
  height: 18px;
  object-fit: contain;
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--rt-resource-color) 55%, transparent));
