  border-radius: 10px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--rt-mode-color) 8%, rgba(4,8,14,.94)), rgba(3,5,11,.86));
  box-shadow: inset 0 0 18px rgba(0,0,0,.32), 0 0 14px color-mix(in srgb, var(--rt-mode-color) 10%, transparent);
