}

/* En RT-04 el Nexo propio se convierte en el selector del perfil de IA. */
body.rok-realtime-playstyle .spawn-marker.realtime-combat-mode-nexus {
  pointer-events: auto;
  cursor: pointer;
}
body.rok-realtime-playstyle .spawn-marker.realtime-combat-mode-nexus::after {
  content: '';
  position: absolute;
  inset: -6px;
  border: 1px solid transparent;
  border-radius: 7px;
  pointer-events: none;
  transition: border-color .14s ease, box-shadow .14s ease, transform .14s ease;
}
body.rok-realtime-playstyle .spawn-marker.realtime-combat-mode-nexus:hover::after,
body.rok-realtime-playstyle .spawn-marker.realtime-combat-mode-nexus:focus-visible::after {
  border-color: color-mix(in srgb, var(--marker-glow) 58%, white 12%);
  box-shadow: 0 0 12px color-mix(in srgb, var(--marker-glow) 30%, transparent);
  transform: scale(1.04);
}
body.rok-realtime-playstyle .spawn-marker.realtime-combat-mode-nexus-selected::after {
  border-color: color-mix(in srgb, var(--marker-glow) 86%, white 12%);
  box-shadow: 0 0 9px color-mix(in srgb, var(--marker-glow) 55%, transparent), inset 0 0 8px color-mix(in srgb, var(--marker-glow) 16%, transparent);
}
body.rok-realtime-playstyle .unit.invocation.realtime-combat-mode-unit-selected {
  filter: drop-shadow(0 0 8px var(--unit-glow)) drop-shadow(0 0 14px var(--unit-glow));
}
body.rok-realtime-playstyle .unit.invocation.realtime-combat-mode-unit-selected::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 82%;
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  border: 1px solid color-mix(in srgb, var(--unit-glow) 74%, white 10%);
  border-radius: 50%;
  box-shadow: 0 0 12px color-mix(in srgb, var(--unit-glow) 32%, transparent);
  pointer-events: none;
}

body.rok-realtime-playstyle .realtime-phase-rail > small:last-child::after {
  content: ' · RT-08.1 · tick 1s/2s/3s · todo el flujo sigue el Tempo';
}

/* ========================================================================== */
/* R.O.K Lite · RT-05 · Tempo de habilidades y estado del runtime            */
/* ========================================================================== */
.realtime-tempo-status,
.realtime-ability-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(100% - 8px);
  min-height: 20px;
  box-sizing: border-box;
  border-radius: 999px;
  font-size: 7px;
  font-weight: 950;
  line-height: 1;
  letter-spacing: .11em;
  text-transform: uppercase;
}
.realtime-tempo-status {
  margin-top: 4px;
  border: 1px solid rgba(0,255,228,.24);
  background: rgba(0,255,228,.065);
  color: rgba(170,255,246,.92);
}
.realtime-tempo-status.is-paused {
  border-color: rgba(255,209,92,.55);
  background: rgba(255,190,56,.13);
  color: #ffe19a;
  box-shadow: 0 0 12px rgba(255,190,56,.12);
}
.realtime-ability-status {
  min-height: 17px;
  border: 1px solid rgba(255,255,255,.09);
