}
body:not(.rok-realtime-playstyle) .realtime-tempo-status,
body:not(.rok-realtime-playstyle) .realtime-ability-status {
  display: none;
}
body.rok-realtime-playstyle .realtime-phase-rail > small:last-child::after {
  content: ' · RT-08.1 · velocidad global 1s/2s/3s · estados + IA por ciclo';
}


/* ========================================================================== */
/* R.O.K Lite · RT-08.1 · Selector del tick maestro                          */
/* ========================================================================== */
.realtime-tempo-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) repeat(3, 28px);
  align-items: center;
  gap: 3px;
  width: calc(100% - 8px);
  min-height: 24px;
  margin: 4px auto 1px;
  padding: 3px;
  box-sizing: border-box;
  border: 1px solid rgba(0,255,228,.15);
  border-radius: 7px;
  background: rgba(0,0,0,.2);
}
.realtime-tempo-controls > span {
  padding-left: 5px;
  overflow: hidden;
  color: rgba(190,255,248,.65);
  font-size: 6px;
  font-weight: 950;
  letter-spacing: .12em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.realtime-tempo-controls button {
  min-width: 0;
  height: 18px;
  padding: 0;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 5px;
  background: rgba(255,255,255,.035);
  color: rgba(255,255,255,.62);
  font: 900 7px/1 inherit;
  cursor: pointer;
}
.realtime-tempo-controls button:hover:not(:disabled) {
  border-color: rgba(0,255,228,.35);
  color: #dffffa;
}
.realtime-tempo-controls button.is-active {
  border-color: rgba(0,255,228,.62);
