}
.realtime-tempo-controls.is-readonly button,
.realtime-tempo-controls button:disabled {
  cursor: default;
  opacity: .45;
}
body:not(.rok-realtime-playstyle) .realtime-tempo-controls {
  display: none;
}


/* ========================================================================== */
/* R.O.K Lite · RT-08.2 · Fuente automática / columnas verticales            */
/* ========================================================================== */
body.rok-realtime-playstyle {
  /* Da a las 3 líneas elementales un poco más de respiración sin tocar Manual. */
  --rok-left-rail-w: clamp(94px, 8.7cqw, 132px);
}

body.rok-realtime-playstyle #resourceBar.vertical-resource-bar {
  width: 100% !important;
  height: 100% !important;
  min-height: 0 !important;
  box-sizing: border-box !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: flex-start !important;
  justify-content: center !important;
  gap: clamp(3px, .42cqw, 7px) !important;
  padding: clamp(6px, 1cqh, 10px) 1px clamp(8px, 1.2cqh, 14px) !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  scrollbar-width: thin;
