  max-width: 44px;
}
body.rok-realtime-playstyle #resourceBar[data-rt-resource-columns="3"] .rt-resource-column {
  max-width: 34px;
}

.rt-resource-column-head {
  width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
