  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 8px color-mix(in srgb, var(--rt-resource-color) 35%, transparent);
}

.rt-resource-column-slots {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(1px, .28cqh, 3px);
  padding: 1px 0;
}
.rt-resource-drop {
  flex: 0 0 auto;
  width: clamp(20px, 2.45cqw, 34px);
  height: clamp(20px, 2.45cqw, 34px);
  display: grid;
  place-items: center;
  transition: opacity .18s ease, filter .18s ease, transform .18s ease;
}
