  width: clamp(18px, 2.15cqw, 30px);
  height: clamp(18px, 2.15cqw, 30px);
}
#resourceBar[data-rt-resource-columns="3"] .rt-resource-drop {
  width: clamp(16px, 1.85cqw, 25px);
  height: clamp(16px, 1.85cqw, 25px);
}
.rt-resource-drop img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
}
.rt-resource-drop.is-charged {
