  transform: scale(1);
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--rt-resource-color) 58%, transparent));
}
.rt-resource-drop.is-spent {
  opacity: .16;
  transform: scale(.94);
  filter: grayscale(.72) saturate(.4);
}

.rt-resource-column-foot {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding-top: 3px;
  border-top: 1px solid rgba(255,255,255,.055);
  color: rgba(255,255,255,.42);
  font-size: 5.5px;
  line-height: 1.05;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

