  display: flex !important;
  align-items: center !important;
  gap: 5px !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
  max-width: 100% !important;
}
.rt-resource-column--compact {
  flex: 0 0 auto;
  width: 46px;
  max-width: 46px;
  gap: 2px;
  padding: 3px 4px;
  border: 1px solid color-mix(in srgb, var(--rt-resource-color) 34%, rgba(255,255,255,.1));
