  background: rgba(2,5,10,.66);
}
.rt-resource-column--compact .rt-resource-column-head {
  position: static;
  flex-direction: row;
  justify-content: space-between;
  padding: 0;
  border: 0;
  background: transparent;
  backdrop-filter: none;
}
.rt-resource-column--compact .rt-resource-column-identity { flex-direction: row; }
.rt-resource-column--compact .rt-resource-column-identity > img { width: 12px; height: 12px; }
.rt-resource-column--compact .rt-resource-column-head > strong { font-size: 7px; }
.rt-resource-compact-meter {
