}


/* ==========================================================================
   R.O.K Lite RT-08.5 · Tiempo de Pensamiento
   ========================================================================== */
.realtime-thought-button {
  display: none;
}

body.rok-realtime-playstyle .realtime-thought-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: min(100%, 128px);
  min-height: 30px;
  margin-top: 4px;
  padding: 5px 9px;
  border: 1px solid rgba(0, 255, 228, .35);
  border-radius: 7px;
  background: linear-gradient(180deg, rgba(0, 255, 228, .10), rgba(0, 0, 0, .36));
  color: rgba(235, 255, 252, .94);
  font: 800 9px/1.1 Arial, sans-serif;
  letter-spacing: .08em;
  cursor: pointer;
  box-shadow: inset 0 0 16px rgba(0, 255, 228, .05);
}

body.rok-realtime-playstyle .realtime-thought-button:hover:not(:disabled),
body.rok-realtime-playstyle .realtime-thought-button.is-active {
  border-color: rgba(0, 255, 228, .78);
  background: linear-gradient(180deg, rgba(0, 255, 228, .22), rgba(0, 0, 0, .42));
  box-shadow: 0 0 16px rgba(0, 255, 228, .13), inset 0 0 18px rgba(0, 255, 228, .08);
}

body.rok-realtime-playstyle .realtime-thought-button.is-rival {
  border-color: rgba(255, 196, 92, .55);
  color: rgba(255, 227, 174, .95);
}

body.rok-realtime-playstyle .realtime-thought-button:disabled {
  cursor: default;
  opacity: .58;
}

.realtime-thought-overlay {
  position: fixed;
  inset: 0;
  z-index: 24000;
  display: none;
  pointer-events: none;
  align-items: flex-start;
  justify-content: center;
  padding-top: clamp(16px, 3.5vh, 42px);
  background:
    radial-gradient(circle at 50% 10%, rgba(0, 255, 228, .055), transparent 30%),
    linear-gradient(180deg, rgba(0, 0, 0, .10), transparent 30%);
}

.realtime-thought-overlay.is-open {
  display: flex;
}

.realtime-thought-shell {
  pointer-events: auto;
  width: min(430px, calc(100vw - 32px));
  padding: 11px 16px 12px;
  border: 1px solid rgba(0, 255, 228, .42);
  border-radius: 11px;
  background: rgba(4, 13, 15, .94);
  box-shadow:
    0 16px 45px rgba(0, 0, 0, .5),
    0 0 24px rgba(0, 255, 228, .08),
    inset 0 0 28px rgba(0, 255, 228, .035);
  text-align: center;
  backdrop-filter: blur(8px);
}

.realtime-thought-kicker {
  display: block;
  color: rgba(0, 255, 228, .76);
  font: 900 9px/1 Arial, sans-serif;
  letter-spacing: .18em;
}

.realtime-thought-title {
  display: block;
  margin-top: 5px;
  color: #f5fffd;
  font: 900 16px/1.1 Arial, sans-serif;
  letter-spacing: .07em;
}

.realtime-thought-clock {
  display: block;
  margin-top: 4px;
  color: #00ffe4;
  font: 900 30px/1 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px rgba(0, 255, 228, .24);
}

.realtime-thought-copy {
  margin: 5px auto 0;
  max-width: 365px;
  color: rgba(255, 255, 255, .70);
  font: 10px/1.35 Arial, sans-serif;
}

.realtime-thought-resume {
  margin-top: 8px;
  min-height: 30px;
  padding: 5px 15px;
  border: 1px solid rgba(0, 255, 228, .55);
  border-radius: 7px;
  background: rgba(0, 255, 228, .12);
  color: #eafffb;
  font: 900 9px/1 Arial, sans-serif;
  letter-spacing: .10em;
  cursor: pointer;
}

.realtime-thought-resume:hover:not(:disabled) {
  background: rgba(0, 255, 228, .22);
}

.realtime-thought-resume[hidden] {
  display: none !important;
}

/* Durante pensamiento el tablero sigue visible/consultable. No se aplica una
   cortina opaca: la pausa es táctica, no una pantalla separada. */
body.rok-realtime-thought-active .realtime-phase-clock {
  text-shadow: 0 0 22px rgba(0, 255, 228, .40);
}

body.rok-realtime-thought-active .realtime-tempo-status.is-paused {
  color: #00ffe4;
}

@media (max-width: 700px) {
  .realtime-thought-overlay {
    padding-top: 10px;
  }
  .realtime-thought-shell {
    width: calc(100vw - 18px);
    padding: 9px 11px 10px;
  }
  .realtime-thought-title { font-size: 13px; }
  .realtime-thought-clock { font-size: 25px; }
}


/* ==========================================================================
   R.O.K Lite RT-08.6 · Calibrador visual de interfaz
   ========================================================================== */

/* La calibración usa transformaciones del bloque completo. Esto evita cambiar
   la lógica interna: hijos, tokens e hitboxes se transforman juntos. */
.rok-ui-tuning-calibrated {
  transform: translateX(var(--rok-ui-tune-x, 0px)) !important;
  transform-origin: center center !important;
}

.rok-ui-tuning-selected {
  outline: 2px solid rgba(255, 211, 106, .95) !important;
  outline-offset: -2px !important;
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,.16),
    0 0 18px rgba(255, 211, 106, .30) !important;
}

#board.rok-ui-tuning-selected {
  outline-offset: 2px !important;
}

.token-tuning-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 8px 10px;
  border-bottom: 1px solid rgba(255,255,255,.08);
  background: rgba(0,0,0,.14);
}

.token-tuning-tabs button {
  min-height: 31px;
  border: 1px solid rgba(255,255,255,.11);
  border-radius: 6px;
  background: rgba(255,255,255,.035);
  color: rgba(228,255,251,.68);
  font: 900 9px/1 system-ui, sans-serif;
  letter-spacing: .09em;
  cursor: pointer;
}

.token-tuning-tabs button:hover,
.token-tuning-tabs button.active {
  border-color: rgba(0,255,228,.55);
  background: rgba(0,255,228,.10);
  color: #f5ffff;
}

.token-tuning-pane {
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  overflow: hidden;
}

.token-tuning-pane[hidden] {
  display: none !important;
}

.ui-tuning-list {
  max-height: 252px;
}

.ui-tuning-entry small {
  color: rgba(255,220,143,.58);
}

.ui-tuning-entry:hover,
.ui-tuning-entry.active {
  border-color: rgba(255,211,106,.55);
  background: rgba(255,211,106,.075);
}

.ui-tuning-controls .token-tuning-selected em {
  margin-top: 3px;
  color: rgba(220,255,250,.52);
  font: 400 9px/1.35 system-ui, sans-serif;
  white-space: normal;
}

.ui-tuning-controls > label {
  grid-template-columns: 82px 1fr 64px;
}

.ui-tuning-controls input[type="range"] {
  accent-color: #ffd36a;
}

.token-tuning-panel {
  width: min(390px, calc(100vw - 28px));
}

/* Mantener el editor por encima de cualquier bloque que el usuario agrande. */
.token-tuning-panel,
.token-tuning-toggle {
  isolation: isolate;
}


/* ==========================================================================
   R.O.K Lite RT-08.8 · Viewport adaptable + calibración horizontal
   ========================================================================== */

/* En combate el lienzo lógico puede crecer más allá de 1600x900 para absorber
   la relación de aspecto visible completa. La escala física sigue siendo
   UNIFORME; no hay estiramiento X/Y independiente ni recorte del escenario. */
#rokAppStage {
  width: var(--rok-stage-logical-width, 1600px) !important;
  height: var(--rok-stage-logical-height, 900px) !important;
}

body.rok-battle-mode #rokAppStage .game-shell {
  width: 100cqw !important;
  height: 100cqh !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
}

/* RT-08.8 · El calibrador de INTERFAZ ahora es exclusivamente horizontal:
   posición X + ancho X. La altura y posición vertical permanecen intactas. */
.rok-ui-tuning-calibrated {
  transform: translateX(var(--rok-ui-tune-x, 0px)) !important;
  transform-origin: center center !important;
}

/* Señal visual inequívoca de que abrir AJUSTES VISUALES detuvo la partida. */
body.rok-token-tuning-paused #tokenTuningPanel .token-tuning-header::after {
  content: 'PARTIDA PAUSADA';
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 20px;
  margin-left: auto;
  padding: 0 7px;
  border: 1px solid rgba(255, 210, 92, .52);
  border-radius: 999px;
  background: rgba(255, 192, 55, .09);
  color: rgba(255, 226, 157, .94);
  font: 900 8px/1 system-ui, sans-serif;
  letter-spacing: .09em;
  white-space: nowrap;
}

/* La arena no recibe input mientras el editor visual está abierto; el panel,
   que vive fuera de #rokAppStage, continúa completamente operable. */
body.rok-token-tuning-paused #rokAppStage {
  pointer-events: none !important;
}


/* ==========================================================================
   R.O.K Lite RT-08.9 · Ancho X REAL, sin scaleX
   ========================================================================== */

/* El calibrador ya no estira la caja ni sus hijos. Solo Posición X permanece
   como transform independiente. */
.rok-ui-tuning-calibrated {
  transform: translateX(var(--rok-ui-tune-x, 0px)) !important;
  transform-origin: center center !important;
}

/* MANUAL: cada carril utiliza el ancho real calculado por el calibrador si
   existe; de lo contrario conserva el responsive original. */
body.rok-battle-mode:not(.rok-realtime-playstyle) .game-shell {
  grid-template-columns:
    var(--rok-ui-elements-track-w, var(--rok-left-rail-w))
    minmax(0, 1fr)
    var(--rok-ui-phase-track-w, var(--rok-phase-rail-w))
    var(--rok-ui-cast-track-w, var(--rok-cast-rail-w))
    var(--rok-ui-spellbook-track-w, var(--rok-spellbook-w)) !important;
}

/* TIEMPO REAL: añade la pista real del panel Modos de combate. */
body.rok-battle-mode.rok-realtime-playstyle .game-shell {
  grid-template-columns:
    var(--rok-ui-elements-track-w, var(--rok-left-rail-w))
    minmax(0, 1fr)
    var(--rok-ui-phase-track-w, var(--rok-phase-rail-w))
    var(--rok-ui-mode-track-w, var(--rok-mode-rail-w))
    var(--rok-ui-cast-track-w, var(--rok-cast-rail-w))
    var(--rok-ui-spellbook-track-w, var(--rok-spellbook-w)) !important;
}

/* Los carriles no deben mantener un ancho interno fijo cuando su pista cambia. */
body.rok-battle-mode .left-panel.rok-ui-tuning-calibrated,
body.rok-battle-mode .phase-rail.rok-ui-tuning-calibrated,
body.rok-battle-mode .cast-panel.rok-ui-tuning-calibrated,
body.rok-battle-mode .right-panel.rok-ui-tuning-calibrated,
body.rok-battle-mode .realtime-combat-mode-dock.rok-ui-tuning-calibrated {
  width: auto !important;
  max-width: none !important;
  min-width: 0 !important;
}


/* ==========================================================================
   R.O.K Lite RT-08.10 · Contenedor ancho, contenido intrínseco
   ========================================================================== */

/* La segunda columna (Arena) también puede recibir ancho REAL. El objeto
   #board sigue gobernado por aspect-ratio y nunca se escala en X. */
body.rok-battle-mode:not(.rok-realtime-playstyle) .game-shell {
  grid-template-columns:
    var(--rok-ui-elements-track-w, var(--rok-left-rail-w))
    var(--rok-ui-board-track-w, minmax(0, 1fr))
    var(--rok-ui-phase-track-w, var(--rok-phase-rail-w))
    var(--rok-ui-cast-track-w, var(--rok-cast-rail-w))
    var(--rok-ui-spellbook-track-w, var(--rok-spellbook-w)) !important;
}

body.rok-battle-mode.rok-realtime-playstyle .game-shell {
  grid-template-columns:
    var(--rok-ui-elements-track-w, var(--rok-left-rail-w))
    var(--rok-ui-board-track-w, minmax(0, 1fr))
    var(--rok-ui-phase-track-w, var(--rok-phase-rail-w))
    var(--rok-ui-mode-track-w, var(--rok-mode-rail-w))
    var(--rok-ui-cast-track-w, var(--rok-cast-rail-w))
    var(--rok-ui-spellbook-track-w, var(--rok-spellbook-w)) !important;
}

/* Nunca permitir que el calibrador fuerce una dimensión al tablero interno.
   El ancho se asigna a .board-panel; #board conserva proporción. */
body.rok-battle-mode .board-panel[data-rok-ui-tune-key="arena"] {
  width: auto !important;
  max-width: none !important;
  min-width: 0 !important;
}
body.rok-battle-mode .board-panel[data-rok-ui-tune-key="arena"] > .board {
  width: min(100%, calc(66.6667cqh - 12px)) !important;
  height: auto !important;
  aspect-ratio: var(--board-aspect) !important;
  max-height: 100% !important;
  transform: none !important;
}

/* SPELLBOOK
   El panel puede ganar ancho, pero las 12 cartas NO crecen con él. Las
   columnas conservan el ancho que tenían antes de abrir el calibrador y el
   espacio adicional se convierte en separación real entre columnas. */
body.rok-battle-mode .right-panel[data-rok-ui-tune-key="spellbook"] .card-grid {
  grid-template-columns:
    repeat(3, minmax(1px, var(--rok-ui-intrinsic-card-slot-w, 88px))) !important;
  grid-auto-columns: var(--rok-ui-intrinsic-card-slot-w, 88px) !important;
  justify-content: space-evenly !important;
  align-content: start !important;
  column-gap: clamp(4px, .55cqw, 8px) !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
}
body.rok-battle-mode .right-panel[data-rok-ui-tune-key="spellbook"] .card-slot {
  width: var(--rok-ui-intrinsic-card-slot-w, 88px) !important;
  min-width: var(--rok-ui-intrinsic-card-slot-w, 88px) !important;
  max-width: var(--rok-ui-intrinsic-card-slot-w, 88px) !important;
  height: auto !important;
  aspect-ratio: var(--card-skin-aspect) !important;
}

/* TEMPO
   Ensanchar el carril añade aire alrededor de los controles; no cambia su
   tamaño base ni su tipografía. */
body.rok-battle-mode .phase-rail[data-rok-ui-tune-key="tempo"] .phase-boxes,
body.rok-battle-mode .phase-rail[data-rok-ui-tune-key="tempo"] .phase-boxes-vertical,
body.rok-battle-mode .phase-rail[data-rok-ui-tune-key="tempo"] .next-phase-vertical,
body.rok-battle-mode .phase-rail[data-rok-ui-tune-key="tempo"] .phase-rail-bottom-controls,
body.rok-battle-mode .phase-rail[data-rok-ui-tune-key="tempo"] .realtime-tempo-controls,
body.rok-battle-mode .phase-rail[data-rok-ui-tune-key="tempo"] .realtime-thought-button {
  width: min(100%, var(--rok-ui-intrinsic-tempo-content-w, 118px)) !important;
  max-width: var(--rok-ui-intrinsic-tempo-content-w, 118px) !important;
  justify-self: center !important;
  margin-left: auto !important;
  margin-right: auto !important;
}

/* KASTEO
   Las cartas ya tenían tamaño propio. Cuando el contenedor crece, mantenemos
   ese tamaño y usamos el ancho sobrante para centrar el flujo. */
body.rok-battle-mode .cast-panel[data-rok-ui-tune-key="cast"] .cast-queue {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
}
body.rok-battle-mode .cast-panel[data-rok-ui-tune-key="cast"] .cast-item {
  flex: 0 0 auto !important;
}

/* ELEMENTOS
   Las gotas/columnas no crecen; el nuevo ancho se convierte en separación. */
body.rok-realtime-playstyle .left-panel[data-rok-ui-tune-key="elements"] #resourceBar.vertical-resource-bar {
  justify-content: space-evenly !important;
}
body.rok-realtime-playstyle .left-panel[data-rok-ui-tune-key="elements"] .rt-resource-column {
  flex-grow: 0 !important;
  flex-shrink: 0 !important;
}

/* MODOS DE COMBATE
   La miniatura y cada opción mantienen el ancho intrínseco capturado. El panel
   exterior sí crece y redistribuye las opciones en el espacio nuevo. */
body.rok-realtime-playstyle .realtime-combat-mode-dock[data-rok-ui-tune-key="combat-modes"]
  .realtime-combat-mode-preview-card-wrap {
  width: var(--rok-ui-intrinsic-mode-preview-w, 76px) !important;
  max-width: var(--rok-ui-intrinsic-mode-preview-w, 76px) !important;
}
body.rok-realtime-playstyle .realtime-combat-mode-dock[data-rok-ui-tune-key="combat-modes"]
  .realtime-combat-mode-buttons {
  grid-template-columns:
    repeat(2, minmax(1px, var(--rok-ui-intrinsic-mode-btn-w, 76px))) !important;
  justify-content: space-evenly !important;
  align-items: start !important;
}
body.rok-realtime-playstyle .realtime-combat-mode-dock[data-rok-ui-tune-key="combat-modes"]
  .realtime-combat-mode-btn {
  width: var(--rok-ui-intrinsic-mode-btn-w, 76px) !important;
  max-width: var(--rok-ui-intrinsic-mode-btn-w, 76px) !important;
}

/* KASTER
   La caja puede aumentar, pero la carta y las celdas no se convierten en
   globos elásticos. El espacio nuevo se reparte entre piezas de tamaño estable. */
body.rok-battle-mode .caster-wide-panel[data-rok-ui-tune-key="caster"] .caster-wide-card {
  width: var(--rok-ui-intrinsic-caster-card-w, auto) !important;
  max-width: var(--rok-ui-intrinsic-caster-card-w, 92px) !important;
}
body.rok-battle-mode .caster-wide-panel[data-rok-ui-tune-key="caster"] .caster-wide-stats {
  grid-template-columns:
    repeat(4, minmax(1px, var(--rok-ui-intrinsic-caster-stat-w, 78px))) !important;
  justify-content: space-between !important;
}
body.rok-battle-mode .caster-wide-panel[data-rok-ui-tune-key="caster"] .caster-wide-stats .stats-line {
  width: var(--rok-ui-intrinsic-caster-stat-w, 78px) !important;
  max-width: var(--rok-ui-intrinsic-caster-stat-w, 78px) !important;
}

/* Garantía final: ninguna regla del calibrador de interfaz puede volver a
   escalar horizontalmente el target ni sus hijos. */
.rok-ui-tuning-calibrated,
.rok-ui-tuning-calibrated * {
  scale: none !important;
}


/* ==========================================================================
   R.O.K Lite RT-08.11 · Spellbook restaurado + Tempos + telemetría
   ========================================================================== */

/* CORRECCIÓN solicitada: RT-08.10 no puede fijar las cartas a una anchura
   intrínseca pequeña. El Spellbook vuelve a distribuir sus 12 slots en 3
   columnas fluidas ocupando TODO el contenedor disponible. */
body.rok-battle-mode .right-panel[data-rok-ui-tune-key="spellbook"] .card-grid,
body.rok-battle-mode .right-panel .card-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  grid-auto-columns: unset !important;
  justify-content: stretch !important;
  width: 100% !important;
  overflow: hidden !important;
}

body.rok-battle-mode .right-panel[data-rok-ui-tune-key="spellbook"] .card-slot,
body.rok-battle-mode .right-panel .card-slot {
  width: auto !important;
  min-width: 0 !important;
  max-width: 100% !important;
}

/* El calibrador tiene ahora 3 pestañas. */
.token-tuning-tabs {
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
}

.realtime-timing-tuning-scroll {
  min-height: 0;
  overflow: auto;
  padding: 9px 10px 12px;
}

.realtime-timing-tuning-group {
  display: grid;
  gap: 6px;
  padding: 8px;
  margin-bottom: 8px;
  border: 1px solid rgba(0,255,228,.12);
  border-radius: 8px;
  background: rgba(0,0,0,.16);
}

.realtime-timing-tuning-group > strong,
