/* ==========================================================================
   R.O.K Lite RT-08.13 · ETAPA 5
   Pulido visual y proporciones del Panel de Invocaciones
   ========================================================================== */

/*
  El ancho base deja de depender de cqw. Esto es importante con el viewport
  lógico expansible: en ultrawide el Panel ya no crece solo porque creció el
  ancho lógico del stage.
*/
body.rok-battle-mode {
  --rok-mode-rail-w: 232px !important;
  --rok-invocation-card-w: 72px;
  --rok-invocation-status-size: 25px;
  --rok-invocation-action-h: 27px;
  --rok-invocation-gap: 6px;
}

/* El carril conserva medidas internas estables aunque Ancho X lo haga mayor. */
body.rok-battle-mode .realtime-combat-mode-dock {
  min-width: 0 !important;
  padding: 6px !important;
}

body.rok-battle-mode .realtime-combat-mode-dock .invocation-control-panel {
  grid-template-rows: auto auto minmax(0, 1fr) auto auto !important;
  gap: 5px !important;
  padding: 8px !important;
}

/* ---------- Cabecera ---------- */
.invocation-control-head > span {
  font-size: 8px !important;
  letter-spacing: .13em !important;
}
.invocation-control-head > b {
  font-size: 7px !important;
}
.invocation-control-hint {
  max-height: 24px;
  overflow: hidden;
  font-size: 6.5px !important;
  line-height: 1.2 !important;
}

/* ---------- Lista principal: siempre recibe la prioridad vertical ---------- */
.invocation-control-list {
  gap: 6px !important;
  padding: 1px 3px 2px 0 !important;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}
.invocation-control-list::-webkit-scrollbar {
  width: 5px;
}
.invocation-control-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: color-mix(in srgb, var(--rt-mode-color) 28%, rgba(255,255,255,.14));
}

/* ---------- Tarjeta ---------- */
.invocation-control-item {
  gap: var(--rok-invocation-gap) !important;
  padding: 7px !important;
  border-radius: 9px !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,.032), rgba(255,255,255,.014)) !important;
}

.invocation-control-item-top {
  grid-template-columns: var(--rok-invocation-card-w) minmax(0, 1fr) !important;
  gap: 7px !important;
  align-items: start !important;
}

/*
  RT-08.13 S2 había forzado 1:1. Para una miniatura de carta eso deformaba el
  marco. Volvemos a la proporción real del skin.
*/
.invocation-control-card {
  width: var(--rok-invocation-card-w) !important;
  min-width: var(--rok-invocation-card-w) !important;
  max-width: var(--rok-invocation-card-w) !important;
}
.invocation-control-card .selected-command-card-composite {
