}
.invocation-control-card .selected-command-card-shell.card {
  width: var(--rok-invocation-card-w) !important;
  max-width: var(--rok-invocation-card-w) !important;
  height: auto !important;
  aspect-ratio: var(--card-skin-aspect, .71) !important;
  transform: none !important;
}

/* El arte adicional/vinculado no puede inflar la columna de la miniatura. */
.invocation-control-card .persistent-linked-spell-card-stack {
  max-width: var(--rok-invocation-card-w) !important;
}

/* ---------- Nombre / Vida / Info ---------- */
.invocation-control-info {
  gap: 4px !important;
  align-content: start !important;
}
.invocation-control-name {
  font-size: 8px !important;
  line-height: 1.1 !important;
}
.invocation-control-meta {
  font-size: 6px !important;
  line-height: 1 !important;
}

.invocation-control-hp-track {
