  display: block;
  width: 100%;
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255,255,255,.075);
  box-shadow: inset 0 0 4px rgba(0,0,0,.45);
}
.invocation-control-hp-fill {
  position: absolute;
  inset: 0 auto 0 0;
