/* ==========================================================================
   R.O.K Lite RT-08.15 · Turno visible en HUD + captura de defensa
   ========================================================================== */

/* Ambos HUD son superficies de foil, no la Arena. */
body.rok-battle-mode .caster-wide-panel,
body.rok-battle-mode .opponent-caster-hud {
  position: relative !important;
  isolation: isolate;
}

/* Texto persistente: solo existe visualmente en el HUD del jugador activo. */
.caster-turn-indicator {
  position: absolute;
  z-index: 45;
  top: 5px;
  right: 6px;
  min-height: 19px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px 3px 5px;
  border: 1px solid color-mix(in srgb, var(--caster-turn-color, #00ffe4) 54%, rgba(255,255,255,.18));
  border-radius: 999px;
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--caster-turn-color, #00ffe4) 16%, rgba(8,10,14,.94)),
      rgba(5,7,11,.92));
  color: color-mix(in srgb, var(--caster-turn-color, #00ffe4) 66%, white 34%);
  box-shadow:
    0 0 11px color-mix(in srgb, var(--caster-turn-color, #00ffe4) 20%, transparent),
    inset 0 0 8px rgba(255,255,255,.025);
  pointer-events: none;
  opacity: 0;
  transform: translateY(-3px) scale(.96);
  transition: opacity .15s ease, transform .15s ease;
}
.caster-turn-indicator[aria-hidden="false"] {
  opacity: 1;
  transform: translateY(0) scale(1);
}
.caster-turn-indicator-dot {
  width: 10px;
  height: 10px;
  flex: 0 0 7px;
  border-radius: 50%;
  background: var(--caster-turn-color, #00ffe4);
  box-shadow:
    0 0 5px var(--caster-turn-color, #00ffe4),
    0 0 9px color-mix(in srgb, var(--caster-turn-color, #00ffe4) 60%, transparent);
}
.caster-turn-indicator b {
  font: 900 6.5px/1 system-ui, sans-serif;
  letter-spacing: .075em;
  white-space: nowrap;
}

/* Foil de transición: dos barridos breves y luego desaparece por completo. */
.caster-turn-foil-layer {
  position: absolute;
  z-index: 38;
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
}
.caster-turn-foil-layer i {
  position: absolute;
  top: -35%;
  bottom: -35%;
  left: -48%;
  width: 30%;
  transform: skewX(-18deg) translateX(0);
  opacity: 0;
  background:
    linear-gradient(90deg,
      transparent 0%,
      color-mix(in srgb, var(--caster-turn-color, #00ffe4) 12%, transparent) 18%,
      color-mix(in srgb, var(--caster-turn-color, #00ffe4) 62%, white 18%) 52%,
      color-mix(in srgb, var(--caster-turn-color, #00ffe4) 10%, transparent) 82%,
      transparent 100%);
  filter: blur(.3px);
}
.caster-turn-foil-layer i:nth-child(2) {
  width: 18%;
  left: -34%;
  filter: blur(.7px);
}

.caster-turn-transition-foil .caster-turn-foil-layer {
  opacity: 1;
}
.caster-turn-transition-foil .caster-turn-foil-layer i:first-child {
  animation: rok-caster-turn-foil-pass .66s cubic-bezier(.18,.72,.18,1) both;
}
.caster-turn-transition-foil .caster-turn-foil-layer i:nth-child(2) {
  animation: rok-caster-turn-foil-pass .54s .16s cubic-bezier(.2,.74,.2,1) both;
}

@keyframes rok-caster-turn-foil-pass {
  0%   { transform: skewX(-18deg) translateX(0); opacity: 0; }
  14%  { opacity: .86; }
  70%  { opacity: .48; }
  100% { transform: skewX(-18deg) translateX(680%); opacity: 0; }
}

/* En Tiempo real no se muestra lenguaje visual de "turno". */
body.rok-realtime-playstyle .caster-turn-indicator,
body.rok-realtime-playstyle .caster-turn-foil-layer {
  display: none !important;
}

/* Ventana de defensa: refuerza visualmente que toda la entrada del mouse está
   temporalmente dirigida a este recuadro. */
.caster-defense-menu {
  cursor: default;
}
.caster-defense-shortcuts {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px 7px;
  width: 100%;
  margin: 0 0 4px;
  padding: 4px 5px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 6px;
  background: rgba(0,0,0,.18);
  color: rgba(255,255,255,.55);
  font: 650 6px/1.15 system-ui,sans-serif;
  pointer-events: none;
}
.caster-defense-shortcuts b {
  color: rgba(255,255,255,.86);
  font-weight: 900;
  letter-spacing: .04em;
}


