/* ========================================================================== 
   R.O.K Lite v9.03 · ETAPA 4 · Nael — Aura de Provocación
   Aura persistente de radio 6 + onda expansiva sincronizada con el pulso.
   ========================================================================== */
.nael-provocation-aura-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: visible;
  z-index: 4;
}

.nael-provocation-aura-field {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1.8px solid rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .68);
  background:
    radial-gradient(circle at center,
      rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .035) 0 23%,
      rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .055) 24% 48%,
      rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .075) 49% 72%,
      rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .115) 73% 100%);
  box-shadow:
    inset 0 0 28px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .10),
    0 0 10px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .42),
    0 0 26px rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .16);
  opacity: .56;
  filter: saturate(1.08);
  animation: naelProvocationAuraBreath 3.1s ease-in-out infinite alternate;
}

.nael-provocation-aura-field::before,
.nael-provocation-aura-field::after {
  content: '';
  position: absolute;
  border-radius: inherit;
  pointer-events: none;
}

.nael-provocation-aura-field::before {
  inset: 17%;
  border: 1px dashed rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .24);
}

.nael-provocation-aura-field::after {
  inset: -4px;
  border: 1px solid rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .26);
  box-shadow: 0 0 12px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .18);
}

.nael-provocation-aura-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 12%;
  height: 12%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .32);
  box-shadow:
    0 0 10px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .22),
    inset 0 0 8px rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .18);
}

.nael-provocation-aura-field--engaged {
  opacity: .68;
  filter: brightness(1.08) saturate(1.15);
}

.nael-provocation-pulse-fx {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  pointer-events: none;
  z-index: 2;
}

.nael-provocation-ripple {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2.3px solid rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .94);
  box-shadow:
    0 0 8px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .84),
    0 0 22px rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .38),
    inset 0 0 10px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .12);
  opacity: 0;
  transform: scale(.07);
  animation: naelProvocationRipple 1.12s cubic-bezier(.18,.72,.16,1) forwards;
}

.nael-provocation-ripple--second {
  border-width: 1.35px;
  border-color: rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .72);
  animation-delay: .16s;
}

@keyframes naelProvocationAuraBreath {
  from {
    filter: brightness(.92) saturate(1.00);
    box-shadow:
      inset 0 0 22px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .08),
      0 0 8px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .34),
      0 0 20px rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .12);
  }
  to {
    filter: brightness(1.08) saturate(1.14);
    box-shadow:
      inset 0 0 34px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .14),
      0 0 14px rgba(var(--nael-aura-primary-rgb, 0, 255, 228), .52),
      0 0 32px rgba(var(--nael-aura-secondary-rgb, 0, 255, 138), .20);
  }
}

@keyframes naelProvocationRipple {
  0% {
    opacity: 0;
    transform: scale(.07);
    filter: brightness(1.45);
  }
  12% {
    opacity: .95;
  }
  72% {
    opacity: .72;
  }
  100% {
    opacity: 0;
    transform: scale(1);
    filter: brightness(1);
  }
}


