/* ========================================================================== 
   R.O.K Lite · v9.12 · Maeryn — Dominación Mental
   Aura persistente radio 5 + pulso expansivo sincronizado con la activación.
   ========================================================================== */
.maeryn-domination-aura-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: visible;
  z-index: 4;
}

.maeryn-domination-aura-field {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1.7px solid rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .62);
  background:
    repeating-radial-gradient(circle at center,
      rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .025) 0 8%,
      rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .055) 9% 10%,
      transparent 11% 18%),
    radial-gradient(circle at center,
      rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .10),
      rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .035) 52%,
      rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .09) 100%);
  box-shadow:
    inset 0 0 32px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .10),
    0 0 11px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .38),
    0 0 27px rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .14);
  opacity: .56;
  animation: maerynDominationAuraBreath 2.7s ease-in-out infinite alternate;
}

.maeryn-domination-aura-field::before,
.maeryn-domination-aura-field::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}
.maeryn-domination-aura-field::before {
  inset: 15%;
  border: 1px dashed rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .30);
  transform: rotate(12deg);
}
.maeryn-domination-aura-field::after {
  inset: 34%;
  border: 1px solid rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .26);
  box-shadow: 0 0 14px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .15);
}
.maeryn-domination-aura-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 10%;
  height: 10%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .38);
  box-shadow:
    0 0 13px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .32),
    inset 0 0 8px rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .18);
}
.maeryn-domination-aura-field--cooldown {
  opacity: .36;
  filter: saturate(.82) brightness(.88);
}
.maeryn-domination-aura-field--supremacy {
  opacity: .76;
  filter: brightness(1.12) saturate(1.18);
  box-shadow:
    inset 0 0 38px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .15),
    0 0 16px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .55),
    0 0 34px rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .24);
}

.maeryn-domination-pulse-fx {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  pointer-events: none;
  z-index: 3;
}
.maeryn-domination-ripple {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2.4px solid rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .96);
  box-shadow:
    0 0 9px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .90),
    0 0 24px rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .42),
    inset 0 0 12px rgba(var(--maeryn-aura-primary-rgb, 0,255,228), .14);
  opacity: 0;
  transform: scale(.055);
  animation: maerynDominationRipple 1.16s cubic-bezier(.15,.74,.16,1) forwards;
}
.maeryn-domination-ripple--second {
  border-width: 1.3px;
  border-style: dashed;
  border-color: rgba(var(--maeryn-aura-secondary-rgb, 0,255,138), .82);
  animation-delay: .17s;
}

@keyframes maerynDominationAuraBreath {
  from { filter: brightness(.92) saturate(.95); }
  to { filter: brightness(1.10) saturate(1.14); }
}
@keyframes maerynDominationRipple {
  0% { opacity: 0; transform: scale(.055); filter: brightness(1.6); }
  10% { opacity: 1; }
  72% { opacity: .72; }
  100% { opacity: 0; transform: scale(1); filter: brightness(1); }
}


