      0 0 10px color-mix(in srgb, var(--rt-caster-destination-color) 52%, transparent 48%);
  }
}

/* ========================================================================== 
   R.O.K Lite · v9.28 · ETAPA 5 · FX DOMINACIÓN MENTAL
   Aplicación Maeryn → objetivo + halo persistente unido a la ficha + ruptura.
   ========================================================================== */
.maeryn-control-fx-layer {
  position: absolute;
  inset: 0;
  z-index: 478;
  pointer-events: none;
  overflow: visible;
}

.maeryn-control-link-fx,
.maeryn-control-link-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}
.maeryn-control-link-line {
  vector-effect: non-scaling-stroke;
  fill: none;
  stroke-linecap: round;
  opacity: 0;
}
.maeryn-control-link-line--wide {
  stroke: rgba(var(--maeryn-control-primary-rgb, 0,255,228), .28);
  stroke-width: 8px;
  filter: drop-shadow(0 0 7px rgba(var(--maeryn-control-primary-rgb, 0,255,228), .72));
  stroke-dasharray: 1.4 3.8;
  animation: maerynControlFilamentWide .92s cubic-bezier(.18,.78,.2,1) forwards;
}
.maeryn-control-link-line--core {
  stroke: rgba(166,112,255,.96);
  stroke-width: 2.2px;
  filter:
    drop-shadow(0 0 3px rgba(var(--maeryn-control-primary-rgb, 0,255,228), .95))
    drop-shadow(0 0 7px rgba(126,67,255,.78));
  stroke-dasharray: 5 3;
  animation: maerynControlFilamentCore 1.03s ease-out forwards;
}

.maeryn-control-capture-fx,
.maeryn-control-source-burst-fx,
.maeryn-control-persistent-halo {
  position: absolute;
  pointer-events: none;
  overflow: visible;
  transform-origin: 50% 50%;
}

.maeryn-control-capture-fx {
  left: 50%;
  top: -18%;
  width: 96%;
  height: 54%;
  transform: translate(-50%, -50%);
  z-index: 58;
}
.maeryn-control-capture-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 1.7px solid rgba(var(--maeryn-control-primary-rgb, 0,255,228), .94);
  box-shadow:
    0 0 8px rgba(var(--maeryn-control-primary-rgb, 0,255,228), .74),
    0 0 15px rgba(133,73,255,.48),
