/* =========================================================
   ROK v9.31 · INDICADOR GEOMÉTRICO DE BANDO EN INVOCACIONES
   Neutro: no usa la paleta elemental/Dominion.
   Aliada = aro continuo + 1 chevrón hacia su Kaster.
   Rival  = aro segmentado + 2 chevrons hacia su Kaster.
   ========================================================= */
.unit.invocation .unit-side-marker {
  position: absolute;
  left: 50%;
  bottom: 0.5%;
  width: 102%;
  height: 29%;
  transform: translateX(-50%);
  pointer-events: none !important;
  z-index: 5;
  opacity: .88;
  filter: none !important;
  -webkit-filter: none !important;
  transition: opacity .14s ease, transform .14s ease;
}

.unit.invocation .unit-side-marker-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  box-sizing: border-box;
  pointer-events: none;
  background: transparent;
}

.unit.invocation .unit-side-marker--ally .unit-side-marker-ring {
  border: 2.4px solid rgba(248, 248, 248, .92);
  box-shadow:
    0 0 4px rgba(255,255,255,.90),
    0 0 9px rgba(255,255,255,.30),
    inset 0 0 6px rgba(255,255,255,.16);
}

.unit.invocation .unit-side-marker--rival .unit-side-marker-ring {
  border: 2.4px dashed rgba(224, 228, 232, .94);
  box-shadow:
    0 0 4px rgba(255,255,255,.76),
    0 0 8px rgba(255,255,255,.24),
    inset 0 0 5px rgba(255,255,255,.12);
}

.unit.invocation .unit-side-chevron {
  position: absolute;
  width: 10px;
  height: 10px;
  box-sizing: border-box;
  border-right: 2.4px solid rgba(252,252,252,.98);
  border-bottom: 2.4px solid rgba(252,252,252,.98);
  filter: drop-shadow(0 0 2px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(255,255,255,.34));
  pointer-events: none;
}

.unit.invocation .unit-side-marker--ally .unit-side-chevron-b {
  display: none;
}

/* hacia abajo */
.unit.invocation .unit-side-marker--toward-down .unit-side-chevron {
  bottom: -9px;
  transform: rotate(45deg);
}
.unit.invocation .unit-side-marker--toward-down .unit-side-chevron-a { left: calc(50% - 5px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-down .unit-side-chevron-a { left: calc(50% - 14px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-down .unit-side-chevron-b { left: calc(50% + 4px); }

/* hacia arriba */
.unit.invocation .unit-side-marker--toward-up .unit-side-chevron {
  top: -9px;
  transform: rotate(225deg);
}
.unit.invocation .unit-side-marker--toward-up .unit-side-chevron-a { left: calc(50% - 5px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-up .unit-side-chevron-a { left: calc(50% - 14px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-up .unit-side-chevron-b { left: calc(50% + 4px); }

/* hacia la derecha */
.unit.invocation .unit-side-marker--toward-right .unit-side-chevron {
  right: -8px;
  transform: rotate(-45deg);
}
.unit.invocation .unit-side-marker--toward-right .unit-side-chevron-a { top: calc(50% - 3.5px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-right .unit-side-chevron-a { top: calc(50% - 12px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-right .unit-side-chevron-b { top: calc(50% + 3px); }

/* hacia la izquierda */
.unit.invocation .unit-side-marker--toward-left .unit-side-chevron {
  left: -8px;
  transform: rotate(135deg);
}
.unit.invocation .unit-side-marker--toward-left .unit-side-chevron-a { top: calc(50% - 3.5px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-left .unit-side-chevron-a { top: calc(50% - 12px); }
.unit.invocation .unit-side-marker--rival.unit-side-marker--toward-left .unit-side-chevron-b { top: calc(50% + 3px); }

.unit.invocation.unit-hovered .unit-side-marker,
.unit.invocation:hover .unit-side-marker,
.unit.invocation.selected-mover .unit-side-marker,
.unit.invocation.hover-linked .unit-side-marker,
.unit.invocation.realtime-combat-mode-unit-selected .unit-side-marker {
  opacity: 1;
  transform: translateX(-50%) scale(1.06);
}

.unit.invocation.restoring .unit-side-marker {
  opacity: .58;
}

.unit.invocation.unit-online-hidden-own .unit-side-marker,
.unit.invocation.unit-camuflaje-hidden .unit-side-marker {
  opacity: .48;
