/* v9.40 · FX de Silencio */
.silence-control-fx-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 26;
  overflow: visible;
}

.silence-impact-fx,
.silence-status-fx {
  position: absolute;
  left: 50%;
  top: 29%;
  width: calc(34px * var(--silence-scale, 1));
  height: calc(34px * var(--silence-scale, 1));
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 7;
}

.silence-status-fx--caster {
  top: 27%;
}

.silence-impact-fx i,
.silence-status-fx i,
.silence-release-fx i {
  position: absolute;
  display: block;
  box-sizing: border-box;
  pointer-events: none;
}

.silence-impact-ring,
.silence-status-ring,
.silence-release-ring {
  inset: 18% 10% auto 10%;
  height: 11px;
  border-radius: 999px;
  border: 1.5px solid rgba(var(--silence-primary-rgb, 137,249,255), .85);
  box-shadow: 0 0 8px rgba(var(--silence-primary-rgb, 137,249,255), .35), inset 0 0 6px rgba(var(--silence-neutral-rgb,255,255,255), .12);
  background: linear-gradient(180deg, rgba(var(--silence-neutral-rgb,255,255,255),.18), rgba(var(--silence-secondary-rgb,201,183,255),.05));
}

.silence-impact-ring.ring-a { animation: silenceRingIn .72s ease-out both; }
.silence-impact-ring.ring-b { inset: 24% 18% auto 18%; opacity:.7; animation: silenceRingIn .78s ease-out .06s both; }

.silence-impact-seal,
.silence-status-seal {
  left: 50%;
  top: 0;
  width: 18px;
  height: 18px;
  transform: translateX(-50%);
  border-radius: 50%;
  border: 1.4px solid rgba(var(--silence-neutral-rgb,255,255,255), .82);
  box-shadow: 0 0 10px rgba(var(--silence-primary-rgb, 137,249,255), .28), inset 0 0 10px rgba(var(--silence-secondary-rgb,201,183,255), .15);
  background:
    radial-gradient(circle at 50% 50%, rgba(var(--silence-neutral-rgb,255,255,255), .22) 0 18%, transparent 19% 100%),
    linear-gradient(90deg, transparent 0 22%, rgba(var(--silence-neutral-rgb,255,255,255), .82) 22% 28%, transparent 28% 72%, rgba(var(--silence-neutral-rgb,255,255,255), .82) 72% 78%, transparent 78% 100%),
    linear-gradient(180deg, transparent 0 42%, rgba(var(--silence-primary-rgb,137,249,255), .88) 42% 58%, transparent 58% 100%);
}
.silence-impact-seal::before,
.silence-status-seal::before,
.silence-impact-seal::after,
.silence-status-seal::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 64%;
  height: 1.4px;
  background: rgba(var(--silence-secondary-rgb,201,183,255), .86);
  transform-origin: center;
}
.silence-impact-seal::before,
.silence-status-seal::before { transform: translate(-50%, -50%) rotate(55deg); }
.silence-impact-seal::after,
.silence-status-seal::after { transform: translate(-50%, -50%) rotate(-55deg); }

.silence-impact-wave,
.silence-status-wave {
  width: 8px;
  height: 12px;
  border-left: 1.6px solid rgba(var(--silence-primary-rgb, 137,249,255), .84);
  border-radius: 60% 40% 55% 45%;
  opacity: .84;
}
.silence-impact-wave.wave-a,
.silence-status-wave.wave-a { left: 4px; top: 6px; transform: rotate(-28deg); }
.silence-impact-wave.wave-b,
.silence-status-wave.wave-b { right: 4px; top: 6px; transform: rotate(28deg); }
.silence-status-wave.wave-c { left: 50%; top: 18px; width: 10px; height: 9px; transform: translateX(-50%) rotate(90deg); opacity: .58; }

.silence-impact-fx { animation: silenceImpactShell .88s ease-out both; }
.silence-impact-seal { animation: silenceSealIn .74s cubic-bezier(.17,.8,.2,1) both; }
.silence-impact-wave.wave-a { animation: silenceWaveBreak .66s ease-out both; }
.silence-impact-wave.wave-b { animation: silenceWaveBreak .66s ease-out .04s both; }

.silence-status-fx {
  opacity: .94;
}
.silence-status-ring {
  animation: silenceStatusRingPulse calc(1.65s - min(1s, (var(--silence-level, 1) - 1) * .08s)) ease-in-out infinite;
}
.silence-status-seal {
  animation: silenceStatusSealFloat 1.9s ease-in-out infinite;
}
.silence-status-wave.wave-a { animation: silenceStatusWaveFlicker 1.25s ease-in-out infinite; }
.silence-status-wave.wave-b { animation: silenceStatusWaveFlicker 1.25s ease-in-out .18s infinite; }
.silence-status-wave.wave-c { animation: silenceStatusWaveFlicker 1.25s ease-in-out .36s infinite; }

.silence-release-fx {
  position: absolute;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 26;
}
.silence-release-ring {
  inset: 30% 18% auto 18%;
  height: 10px;
  animation: silenceReleaseRing .78s ease-out both;
}
.silence-release-fragment {
  width: 12px;
  height: 2px;
  left: 50%;
  top: 18%;
  background: linear-gradient(90deg, rgba(var(--silence-neutral-rgb,255,255,255), .95), rgba(var(--silence-primary-rgb,137,249,255), .2));
  border-radius: 999px;
  box-shadow: 0 0 8px rgba(var(--silence-primary-rgb,137,249,255), .35);
}
.silence-release-fragment.fragment-a { transform: translate(-50%, -50%) rotate(18deg); animation: silenceReleaseFragmentA .74s ease-out both; }
.silence-release-fragment.fragment-b { transform: translate(-50%, -50%) rotate(-18deg); animation: silenceReleaseFragmentB .74s ease-out both; }
.silence-release-fragment.fragment-c { transform: translate(-50%, -50%) rotate(90deg); animation: silenceReleaseFragmentC .74s ease-out both; }

@keyframes silenceImpactShell {
  0% { opacity: 0; transform: translate(-50%, -62%) scale(.72); }
  18% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.12); }
}
@keyframes silenceRingIn {
  0% { opacity: 0; transform: scale(.65); }
  35% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.25); }
}
@keyframes silenceSealIn {
  0% { opacity: 0; transform: translateX(-50%) scale(.4) rotate(-12deg); }
  45% { opacity: 1; transform: translateX(-50%) scale(1.08) rotate(2deg); }
  100% { opacity: 0; transform: translateX(-50%) scale(1) rotate(0deg); }
}
@keyframes silenceWaveBreak {
  0% { opacity: 0; transform: scale(.55) rotate(var(--wave-rot, 0deg)); }
  30% { opacity: .9; }
  100% { opacity: 0; transform: translateY(-2px) scale(1.15) rotate(var(--wave-rot, 0deg)); }
}
@keyframes silenceStatusRingPulse {
  0%, 100% { opacity: .52; transform: scale(.94); }
  50% { opacity: .96; transform: scale(1.08); }
}
@keyframes silenceStatusSealFloat {
  0%, 100% { opacity: .88; transform: translateX(-50%) translateY(0) scale(1); }
  50% { opacity: 1; transform: translateX(-50%) translateY(-1px) scale(1.04); }
}
@keyframes silenceStatusWaveFlicker {
  0%, 100% { opacity: .3; }
  50% { opacity: .84; }
}
@keyframes silenceReleaseRing {
  0% { opacity: .9; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.34); }
}
@keyframes silenceReleaseFragmentA {
  0% { opacity: .95; }
  100% { opacity: 0; transform: translate(-165%, -180%) rotate(32deg); }
}
@keyframes silenceReleaseFragmentB {
  0% { opacity: .95; }
  100% { opacity: 0; transform: translate(65%, -185%) rotate(-32deg); }
}
@keyframes silenceReleaseFragmentC {
  0% { opacity: .95; }
  100% { opacity: 0; transform: translate(-50%, 58%) rotate(90deg); }
}

